class _SafeExceptionHandler(telebot.ExceptionHandler):
    """Har qanday handler ichidagi kutilmagan xato butun botni yiqitmasligi uchun.
    Xato faqat log'ga yoziladi, bot polling'ni davom ettiraveradi.
    🔧 TUZATILDI (#5): endi xato yuz berganda BOT EGASIGA avtomatik, real vaqtda
    Telegram orqali xabar boradi — avval xatoni faqat log fayldan (server konsolidan)
    ko'rish mumkin edi, endi buni bilish uchun serverga kirish shart emas."""

    def handle(self, exception):
        notify_owner_of_error("global (handler ichida ushlanmagan)", exception)
        return True  # True = xato "boshqarildi" deb hisoblanadi, polling to'xtamaydi


_ERROR_NOTIFY_CACHE = {}

# 🔧 v8: Telegram "chat endi mavjud emas / botga ruxsat yo'q" xatolari (bot guruhdan chiqarilgan, chat o'chirilgan,
# foydalanuvchi botni bloklagan va h.k.). Ular kod xatosi emas — jimgina qayta ishlanadi.
_CHAT_GONE_MARKERS = (
    "bot was kicked", "bot was blocked by the user", "chat not found", "have no rights to send a message",
    "user is deactivated", "group chat was deleted", "bot is not a member", "not enough rights to send",
    "chat_write_forbidden", "bot can't initiate conversation", "peer_id_invalid", "group chat was upgraded",
)
# Bu belgilar chatning O'ZI yo'qolganini bildiradi (bloklash/ruxsat emas) — o'yin holati ham tozalanadi
_CHAT_DEAD_MARKERS = ("bot was kicked", "chat not found", "group chat was deleted", "bot is not a member")


def _is_chat_gone_error(exception):
    code = getattr(exception, "error_code", None)
    text = str(exception).lower()
    if code not in (400, 403) and not any(m in text for m in ("error code: 403", "error code: 400")):
        return False
    return any(m in text for m in _CHAT_GONE_MARKERS)


def _forget_dead_chat(chat_id):
    """Bot guruhdan chiqarilgan/guruh o'chirilgan bo'lsa: shu guruhdagi o'yinni jimgina to'xtatadi
    (taymerlar bekor qilinadi) va guruhni bilinadigan guruhlar ro'yxatidan olib tashlaydi."""
    try:
        chat_id = int(chat_id)
    except Exception:
        return
    if chat_id >= 0:
        return   # faqat guruhlar (shaxsiy chatlar emas)
    try:
        game = GAMES.pop(chat_id, None)
        if game:
            for t in list(game.get("timers", [])):
                try:
                    t.cancel()
                except Exception:
                    pass
            _logger.warning("Guruh %s dan bot chiqarilgan — o'yin jimgina to'xtatildi.", chat_id)
        remove_known_group(chat_id)
        try:
            save_games_state()
        except Exception:
            pass
    except Exception:
        _logger.exception("_forget_dead_chat xatolik")


def notify_owner_of_error(context_label, exception):
    """🔧 Umumiy xato-xabar funksiyasi: istalgan joyda (ichki try/except bo'lsa
    ham) chaqirilib, xatoning ANIQ matnini bot egasiga Telegram orqali
    yuboradi — endi hech qanday xato "log fayl ichida yashirin" qolmaydi,
    /elite kabi buyruqlarda ham darhol nima buzilganini ko'rish mumkin.

    🔇 ISTISNO: 409 Conflict (= shu bot tokeni bilan boshqa nusxa ham polling
    qilyapti) — bu haqiqiy "kod xatosi" emas, asosiy polling tsikli buni
    allaqachon o'zi kutib-qayta urinish orqali boshqaradi. Shuning uchun bu
    Telegram xabari sifatida YUBORILMAYDI (faqat log fayliga yoziladi)."""
    _logger.exception("%s: %s", context_label, exception)
    err_text = f"{type(exception).__name__}: {exception}"
    # 🔧 v14: xato qayerda (qaysi fayl/funksiya/qator) yuz berganini ham
    # Telegram xabariga qo'shamiz — shunda owner serverga kirmasdan ham
    # aniq qaysi joyni tuzatish kerakligini biladi.
    try:
        tb_lines = traceback.format_exception(type(exception), exception, exception.__traceback__)
        tb_text = "".join(tb_lines)
        loc_lines = [ln.strip() for ln in tb_text.splitlines() if ln.strip().startswith("File ")]
        loc_hint = loc_lines[-1] if loc_lines else ""
    except Exception:
        loc_hint = ""
    is_conflict_409 = (
        getattr(exception, "error_code", None) == 409
        or "409" in err_text
        or "Conflict" in err_text
    )
    if is_conflict_409:
        return
    # 🔇 429 (Too Many Requests) — Telegram vaqtinchalik "sekinroq yuboring" deb ogohlantirishi,
    # bu ham "kod xatosi" emas (ayniqsa ommaviy xabar/kunlik menyu kabi ko'p odamga bir vaqtda
    # yuborilganda tabiiy holat) — shuning uchun owner'ga bezovta qiluvchi xabar yubormaymiz,
    # faqat log fayliga yoziladi (yuqorida allaqachon yozilgan).
    is_too_many_requests = getattr(exception, "error_code", None) == 429 or "429" in err_text or "Too Many Requests" in err_text
    if is_too_many_requests:
        return
    # 🔇 "chat not found" (400) — bot guruhdan chiqarib yuborilgan, foydalanuvchi
    # botni hech qachon shaxsan ishga tushirmagan yoki chat/guruh o'chirilgan
    # holatlarda chiqadi. Bu ham "kod xatosi" emas (kod allaqachon try/except
    # bilan bunday holatlarni kutadi) — shuning uchun owner'ga bezovta qiluvchi
    # xabar yubormaymiz, faqat log fayliga yoziladi.
    is_chat_not_found = getattr(exception, "error_code", None) == 400 and "chat not found" in err_text.lower()
    if is_chat_not_found:
        return
    # 🔇 v8: 403/400 "bot was kicked / blocked / no rights to send" — guruhdan chiqarilgan yoki
    # foydalanuvchi botni bloklagan: bu tashqi holat, kod xatosi emas → owner'ga xabar yuborilmaydi.
    if _is_chat_gone_error(exception):
        return
    if not error_notify_enabled():
        return
    try:
        now = time.strftime("%d.%m.%Y %H:%M:%S")
        key = f"errnotify_{hash(context_label + err_text) % 100000}"
        last = _ERROR_NOTIFY_CACHE.get(key, 0)
        if time.time() - last > 120:
            _ERROR_NOTIFY_CACHE[key] = time.time()
            bot.send_message(
                OWNER_ID_FROM_ENV,
                f"🚨 <b>Botda xato yuz berdi!</b>\n"
                f"📍 Joyi: <code>{context_label}</code>\n"
                f"🧭 Qator: <code>{esc(loc_hint)[:250]}</code>\n"
                f"🕐 Vaqt: {now}\n"
                f"📋 Xato: <code>{err_text[:500]}</code>",
            )
    except Exception:
        pass


# ================================================================================
#  🛡 GEROYLAR TIZIMI UCHUN ALOHIDA XATOLIK LOGI
#
#  Asosiy log (yuqorida, _logger) bilan aralashib ketmasligi uchun — geroy
#  funksiyalarida (/geroyim, mahoratlar, admin geroy buyruqlari va h.k.) yuz
#  bergan har qanday xatolik ALOHIDA "hero_errors.log" fayliga yoziladi, shu
#  bilan birga mavjud notify_owner_of_error() orqali bot egasiga DARHOL
#  Telegram xabari ham boradi — owner serverga kirmasdan ham bilib oladi.
# ================================================================================

HERO_ERROR_LOG_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "hero_errors.log")
_hero_logger = logging.getLogger("hunter_mafia.geroy")
_hero_logger.setLevel(logging.INFO)
if not _hero_logger.handlers:
    try:
        _hero_file_handler = logging.FileHandler(HERO_ERROR_LOG_PATH, encoding="utf-8")
        _hero_file_handler.setFormatter(logging.Formatter("%(asctime)s [%(levelname)s] %(message)s"))
        _hero_logger.addHandler(_hero_file_handler)
    except Exception:
        pass
_hero_logger.propagate = False  # asosiy konsol/log fayl bilan qo'shilib ketmasin


def log_hero_error(context_label, exception):
    """🛡 Geroy tizimidagi xatoliklarni hero_errors.log fayliga yozadi VA
    bot egasiga darhol Telegram orqali xabar beradi."""
    try:
        _hero_logger.exception("%s: %s", context_label, exception)
    except Exception:
        pass
    notify_owner_of_error(f"🦸 GEROY: {context_label}", exception)


def hero_safe(context_label):
    """🛡 Geroy bilan bog'liq handler/funksiyalarga qo'yiladigan dekorator —
    ichida kutilmagan xatolik yuz bersa, butun bot yiqilib qolmaydi: xatolik
    hero_errors.log fayliga yoziladi va owner'ga darhol xabar beriladi,
    foydalanuvchi esa shunchaki javobsiz qolmaydi (funksiya jim tugaydi)."""
    def _decorator(func):
        @functools.wraps(func)
        def _wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                log_hero_error(context_label, e)
        return _wrapper
    return _decorator



# 🔧 MUHIM TUZATISH: ENABLE_MIDDLEWARE albatta TeleBot obyekti YARATILISHIDAN
# OLDIN o'rnatilishi SHART. Aks holda kutubxona `self.typed_middleware_handlers`
# atributini __init__ ichida yaratmaydi, lekin bayroq baribir "yoqiq" bo'lib
# qolganidan, keyinchalik HAR BIR kelgan xabar/callback qayta ishlanganda
# (hattoki /start kabi oddiy buyruqlarda ham) botni butunlay chalkashtiruvchi
# "'TeleBot' object has no attribute 'typed_middleware_handlers'" xatoligiga
# olib kelardi — shu sabab bot deyarli hech nimaga javob bermayotgandek va
# ELITE sotib olish tugmalari ham ishlamayotgandek ko'rinardi.
# 🔧 MUSTAHKAMLASH: agar tarmoq/Telegram API vaqtinchalik javob bermay qolsa,
# so'rov abadiy "osilib qolmasligi" uchun aniq timeout, VA vaqtinchalik
# xatoliklarda kutubxonaning o'zi (bizning while-True qayta urinish tsiklimizga
