def _faq_normalize(text):
    text = text.lower().strip()
    text = text.replace("'", "'").replace("’", "'").replace("‘", "'").replace("`", "'")
    text = re.sub(r"[^\w\sʻʼ']", " ", text, flags=re.UNICODE)
    return re.sub(r"\s+", " ", text).strip()


