def _tf_stats(uid, elite):
    u = user_dict(uid)
    games, wins = u["games"] or 0, u["wins"] or 0
    rate = round(wins / games * 100, 1) if games else 0
    if games == 0:
        return "📊 Siz hali birorta ham o'yin o'ynamagansiz. Guruhda /join orqali qo'shiling — birinchi tajribangiz sizni kutmoqda! 🎮"
    comment = ("Zo'r natija, shunday davom eting! 🔥" if rate >= 60 else
               "Yomon emas, lekin yaxshilash mumkin — rollarni diqqat bilan o'ylab o'ynang." if rate >= 35 else
               "Hafsalangiz pir bo'lmasin — har bir mag'lubiyat tajriba beradi, keyingi safar aniq g'alaba qozonasiz! 💪")
    return f"📊 Sizning statistikangiz:\n🎮 Jami o'yin: <b>{games}</b>\n🏆 G'alaba: <b>{wins}</b> ({rate}%)\n\n{comment}"


def _tf_duel_stats(uid, elite):
    u = user_dict(uid)
    dw, dl = u["duel_wins"] or 0, u["duel_losses"] or 0
    total = dw + dl
    if total == 0:
        return "⚔️ Siz hali birorta ham duelga chiqmagansiz. Guruhda kimningdir xabariga Reply qilib /duel summasi deb yozing va sinab ko'ring!"
    rate = round(dw / total * 100, 1)
    return f"⚔️ Duel statistikangiz:\n🏆 Yutgan: <b>{dw}</b>\n💔 Yutqazgan: <b>{dl}</b>\n📈 Foiz: <b>{rate}%</b>"


def _tf_clan_info(uid, elite):
    owner_id = find_member_clan(uid)
    if not owner_id:
        return "🏛 Siz hali biror klanga a'zo emassiz. Klan ochish uchun Hunter Coin do'konidan litsenziya oling va /klan Nomi deb yozing, yoki mavjud klanga /klanga_qoshil egasi_ID orqali qo'shiling."
    clan = get_clan(owner_id)
    if not clan:
        return "🏛 Klaningiz haqida ma'lumot topilmadi."
    role = "Lider" if owner_id == uid else ("O'rinbosar" if is_clan_deputy(uid, owner_id) else "A'zo")
