def _to_umumiy_statistika(uid, elite):
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users")
        total_users = cur.fetchone()[0]
    return (f"📊 <b>Umumiy statistika:</b>\n"
            f"👥 Jami foydalanuvchilar: <b>{total_users}</b>\n"
            f"🎮 Hozir faol o'yinlar: <b>{len(GAMES)}</b>")


def _to_eng_boy_foydalanuvchi(uid, elite):
    with db_lock:
        cur.execute("SELECT user_id, name, dollar FROM users ORDER BY dollar DESC LIMIT 1")
        row = cur.fetchone()
    if not row:
        return "💰 Hozircha foydalanuvchilar bazasi bo'sh."
    return f"💰 Eng boy foydalanuvchi: <b>{row[1]}</b> — <b>{row[2]}$</b>"


def _to_eng_kuchli_klan(uid, elite):
    with db_lock:
        cur.execute("SELECT name, wins FROM clans ORDER BY wins DESC LIMIT 1")
        row = cur.fetchone()
    if not row:
        return "🏛 Hozircha birorta klan yo'q."
    return f"🏛 Eng kuchli klan: <b>{row[0]}</b> — <b>{row[1]}</b> ta jang g'alabasi"


def _to_eng_faol_duelchi(uid, elite):
    with db_lock:
        cur.execute("SELECT user_id, name, duel_wins FROM users ORDER BY duel_wins DESC LIMIT 1")
        row = cur.fetchone()
    if not row or not row[2]:
        return "⚔️ Hozircha birorta duel g'alabasi qayd etilmagan."
    return f"⚔️ Eng ko'p duel yutgan: <b>{row[1]}</b> — <b>{row[2]}</b> ta g'alaba"


def _to_bugungi_faollik(uid, elite):
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users WHERE last_bonus_date = ?", (time.strftime("%Y-%m-%d"),))
        active_today = cur.fetchone()[0]
    return f"📅 Bugun kunlik bonus olgan (faol) foydalanuvchilar: <b>{active_today}</b> ta"

def _to_elite_soni(uid, elite):
    with db_lock:
        cur.execute("SELECT charges FROM users WHERE charges IS NOT NULL")
        rows = cur.fetchall()
    now = time.time()
    count = 0
    for (charges_json,) in rows:
        try:
            if json.loads(charges_json or "{}").get("vip_until", 0) > now:
                count += 1
        except Exception:
            pass
    return f"👑 Hozirgi faol ELITE a'zolar soni: <b>{count}</b> ta"


def _to_haftalik_top(uid, elite):
    rows = get_points_leaderboard("hafta", limit=3)
    if not rows:
        return "🏅 Bu hafta hali ball to'plagan foydalanuvchi yo'q."
    lines = ["🏅 <b>Haftalik top 3:</b>"]
    for i, (_uid, name, total) in enumerate(rows, 1):
        lines.append(f"{i}. {name} — {total} ball")
    return "\n".join(lines)


