def _column_exists(table, column):
    try:
        cur.execute(f"PRAGMA table_info({table})")
        return any(row[1] == column for row in cur.fetchall())
    except Exception:
        return False


@bot.message_handler(commands=["theron"])
def cmd_theron(message):
    """🧠 Theron bilan suhbat. Ish tartibi:
    1) Savol bo'lmasa — tanishtiruv.
    2) Savol FAQ bazasida (eng ko'p so'raladigan mavzular) topilsa — DARHOL
       javob beriladi, AI so'rov QILINMAYDI, kunlik limitdan HECH NARSA
       sarflanmaydi (bu tezkor va bepul yo'l).
    3) FAQ'da topilmasa — haqiqiy AI (Gemini) chaqiriladi, bu safar kunlik
       limitdan 1 ta sarflanadi (owner uchun limit yo'q — u har doim
       ustuvor va cheklovsiz)."""
    try:
        maybe_capture_owner(message.from_user)
        uid = message.from_user.id
        parts = message.text.split(maxsplit=1)
        question = parts[1].strip() if len(parts) > 1 else ""

        if not question:
            bot.reply_to(
                message,
                f"🧠 <b>{THERON_NAME}</b> {THERON_MEANING}\n\n"
                "Savolingizni yozing — javob beraman!\n\n"
                "✍️ <code>/theron savolingiz</code>\n"
                f"👑 ELITE: kuniga {THERON_ELITE_DAILY_LIMIT} ta | 👤 Oddiy: kuniga {THERON_FREE_DAILY_LIMIT} ta\n"
                "📚 Mashhur mavzular (ELITE, klan, duel, nikoh) — limitsiz javob beraman!",
            )
            return

        # 1) 📚 Avval "tezkor bilim bazasi" (FAQ) — limitsiz, AI shart emas
        faq_answer = faq_lookup(question)
        if faq_answer:
            bot.reply_to(message, f"🧠 <b>{THERON_NAME}:</b> {faq_answer}")
            return

        # 2) FAQ'da topilmadi — haqiqiy AI kerak
        if not theron_available():
            bot.reply_to(
                message,
                f"🧠 <b>{THERON_NAME}</b> {THERON_MEANING}\n\n"
                "Bu savolga tayyor javobim yo'q, AI xizmati hozircha o'chirilgan. "
                "Boshqa buyruqlar /yordam orqali ishlayveradi."
            )
            return

        elite_user = is_elite(uid)
        allowed, remaining = theron_check_and_consume_quota(uid, elite_user)
        if not allowed:
            bot.reply_to(
                message,
                f"⏳ Bugungi {THERON_NAME} bilan chuqur AI-suhbat limitingiz tugadi.\n"
                + ("Ertaga qayta urinib ko'ring." if elite_user else
                   f"👑 ELITE a'zolikda kunlik limit {THERON_ELITE_DAILY_LIMIT} tagacha — /elite orqali oling."),
            )
            return

        try:
            bot.send_chat_action(message.chat.id, "typing")
        except Exception:
            pass

        answer = theron_answer_user(uid, question, elite_user)
        if not answer:
            bot.reply_to(message, f"⚠️ {THERON_NAME} hozir javob berolmadi (AI xizmati vaqtincha ishlamayapti). Birozdan keyin qayta urinib ko'ring.")
            return

        suffix = f"\n\n<i>💬 Bugun yana {remaining} ta chuqur AI-savol qoldi.</i>" if not is_owner(uid) else ""
        bot.reply_to(message, f"🧠 <b>{THERON_NAME}:</b> {answer}{suffix}")
    except Exception as e:
        notify_owner_of_error("cmd_theron (/theron buyrug'i)", e)
        try:
            bot.reply_to(message, f"⚠️ {THERON_NAME} bilan bog'lanishda xatolik yuz berdi. Qaytadan urinib ko'ring.")
        except Exception:
            pass


@bot.message_handler(
    func=lambda m: (
        m.chat.type == "private"
        and m.from_user.id in THERON_CHAT_MODE
        and not (m.text or "").startswith("/")
    ),
    content_types=["text"],
)
def theron_free_chat(message):
    """💬 Asosiy menyudagi "Theron" tugmasi orqali suhbat rejimiga kirgan
    foydalanuvchining istalgan (buyruq bo'lmagan) xabarini Theron'ga savol
    sifatida yuboradi — /theron prefiksi yozish shart emas. Har bir javobdan
    keyin "🔙 Bosh menyu" tugmasi qo'shiladi."""
    try:
        maybe_capture_owner(message.from_user)
        uid = message.from_user.id
        question = (message.text or "").strip()
        if not question:
            return

        faq_answer = faq_lookup(question)
        if faq_answer:
            bot.reply_to(message, f"🧠 <b>{THERON_NAME}:</b> {faq_answer}", reply_markup=with_back_button())
            return

        elite_user = is_elite(uid)
        allowed, remaining = theron_check_and_consume_quota(uid, elite_user)
        if not allowed:
            bot.reply_to(
                message,
                f"⏳ Bugungi {THERON_NAME} bilan chuqur suhbat limitingiz tugadi.\n"
                + ("Ertaga qayta urinib ko'ring." if elite_user else
                   f"👑 ELITE a'zolikda kunlik limit {THERON_ELITE_DAILY_LIMIT} tagacha — /elite orqali oling."),
                reply_markup=with_back_button(),
            )
            return

        try:
            bot.send_chat_action(message.chat.id, "typing")
        except Exception:
            pass

        answer = theron_answer_user(uid, question, elite_user)
        suffix = f"\n\n<i>💬 Bugun yana {remaining} ta savol qoldi.</i>" if not is_owner(uid) else ""
        bot.reply_to(message, f"🧠 <b>{THERON_NAME}:</b> {answer}{suffix}", reply_markup=with_back_button())
    except Exception as e:
        notify_owner_of_error("theron_free_chat (Theron suhbat rejimi)", e)
        try:
            bot.reply_to(message, f"⚠️ {THERON_NAME} bilan bog'lanishda xatolik yuz berdi. Qaytadan urinib ko'ring.", reply_markup=with_back_button())
        except Exception:
            pass


@bot.message_handler(commands=["theron_hisobot"])
def cmd_theron_hisobot(message):
    """👑 FAQAT bot egasi — Theron real statistika asosida hisobot + tavsiya beradi."""
    try:
        maybe_capture_owner(message.from_user)
        safe_delete(message)
        if not is_owner(message.from_user.id):
            bot.send_message(message.chat.id, "⛔ Bu buyruq faqat bot egasi uchun.")
            return
        try:
            bot.send_chat_action(message.chat.id, "typing")
        except Exception:
            pass
        bot.send_message(message.chat.id, theron_owner_report_text())
    except Exception as e:
        notify_owner_of_error("cmd_theron_hisobot (/theron_hisobot)", e)
        try:
            bot.send_message(message.chat.id, "⚠️ Hisobotni tayyorlashda xatolik yuz berdi.")
        except Exception:
            pass

# ================================================================================
#  🛡 SPAM/FLOOD HIMOYASI (#4)
#  Bir foydalanuvchi juda tez-tez (soniyasiga bir nechta) xabar/buyruq yuborsa,
#  botni sekinlashtirmasligi uchun — belgilangan chegaradan tez-tez yozganlarning
#  xabarlari (butunlay bloklanmasdan, faqat) o'tkazib yuboriladi.
#  🔒 XAVFSIZLIK: middleware ba'zi pyTelegramBotAPI versiyalarida yo'q bo'lishi
#  mumkin — shuning uchun try/except bilan o'ralgan: agar kutubxona buni
#  qo'llab-quvvatlamasa, bot BARIBIR normal ishga tushadi (faqat shu bitta
#  qo'shimcha himoyasiz qoladi, boshqa hech narsa buzilmaydi).
# ================================================================================

RATE_LIMIT_WINDOW = 2.0      # soniya
RATE_LIMIT_MAX_MSGS = 4      # shu oyna ichida ruxsat etilgan maksimal xabar soni
_RATE_LIMIT_LOG = {}         # uid -> [timestamp, timestamp, ...]
_RATE_LIMIT_WARNED = {}      # uid -> oxirgi ogohlantirish vaqti


def _rate_limit_middleware(bot_instance, message):
    """Har bir kelgan xabar handlerga yetib borishidan OLDIN ishlaydi. Agar
    foydalanuvchi so'nggi RATE_LIMIT_WINDOW soniya ichida RATE_LIMIT_MAX_MSGS
    dan ko'proq xabar yuborgan bo'lsa, shu xabar handlerlarga UZATILMAYDI."""
    try:
        uid = message.from_user.id if message.from_user else None
        # 👥 Guruh a'zoligini kuzatish (top-reyting guruh bo'yicha filtrlash uchun) —
        # rate-limitdan qat'iy nazar, HAR bir guruh xabari uchun yoziladi.
        if uid is not None and message.chat and message.chat.type in ("group", "supergroup"):
            track_group_member(message.chat.id, uid)
        if uid is None or is_owner(uid):
            message._skip_handling = False
            return
        now = time.time()
        log = _RATE_LIMIT_LOG.setdefault(uid, [])
        log[:] = [t for t in log if now - t < RATE_LIMIT_WINDOW]
        log.append(now)
        if len(log) > RATE_LIMIT_MAX_MSGS:
            message._skip_handling = True
            last_warn = _RATE_LIMIT_WARNED.get(uid, 0)
            if now - last_warn > 5:  # ogohlantirishni ham spam qilib yubormaslik uchun
                _RATE_LIMIT_WARNED[uid] = now
                try:
                    bot.send_message(message.chat.id, "⏳ Juda tez-tez yozyapsiz — biroz sekinroq urinib ko'ring.")
                except Exception:
                    pass
        else:
            message._skip_handling = False
    except Exception:
        message._skip_handling = False  # xatolik bo'lsa ham xabar bloklanib qolmasin


def _rate_limited_dropper(message):
    """Middleware 'skip' deb belgilagan xabarlarni jimgina yutadi — boshqa hech
    qanday handlerga yubormaydi. ENG BIRINCHI bo'lib ro'yxatga olinishi shart
    (shuning uchun fayl boshida turadi) — pyTelegramBotAPI xabarni FAQAT birinchi
    mos kelgan handlerga yuboradi."""
    pass


try:
    # (ENABLE_MIDDLEWARE endi yuqorida, bot yaratilishidan OLDIN o'rnatiladi — bu yerda qayta kerak emas)
    bot.middleware_handler(update_types=["message"])(_rate_limit_middleware)
    bot.message_handler(func=lambda m: getattr(m, "_skip_handling", False))(_rate_limited_dropper)
    _logger.info("🛡 Spam/flood himoyasi middleware muvaffaqiyatli yoqildi.")
except Exception as e:
    _logger.warning(
        "🛡 Spam/flood himoyasi middleware'ni yoqib bo'lmadi (kutubxona versiyasi "
        "qo'llab-quvvatlamasligi mumkin) — bot BARIBIR normal ishlayveradi: %s", e,
    )

