def _top_page_markup(kind, page, total_pages, scope="a"):
    if total_pages <= 1:
        return None
    kb = types.InlineKeyboardMarkup()
    row = []
    if page > 0:
        row.append(types.InlineKeyboardButton("◀️", callback_data=f"topPage|{kind}|{page - 1}|{scope}"))
    row.append(types.InlineKeyboardButton(f"{page + 1}/{total_pages}", callback_data=f"topPage|noop|0|{scope}"))
    if page < total_pages - 1:
        row.append(types.InlineKeyboardButton("▶️", callback_data=f"topPage|{kind}|{page + 1}|{scope}"))
    kb.row(*row)
    return kb


_TOP_BUILDERS = {"wins": build_top_text, "diamond": build_top_diamond_text, "dollar": build_top_dollar_text}


@bot.callback_query_handler(func=lambda c: c.data.startswith("topPage|"))
def cb_top_page(call):
    """◀️▶️ #9: uzun reyting ro'yxatlarini sahifalab ko'rsatish tugmalari.
    scope='g' bo'lsa — shu guruh a'zolari bo'yicha, 'a' bo'lsa — barcha foydalanuvchilar bo'yicha."""
    try:
        maybe_capture_owner(call.from_user)
        parts = call.data.split("|")
        kind, page_s = parts[1], parts[2]
        scope = parts[3] if len(parts) > 3 else "a"
        if kind == "noop":
            bot.answer_callback_query(call.id)
            return
        page = int(page_s)
        builder = _TOP_BUILDERS.get(kind)
        if not builder:
            bot.answer_callback_query(call.id, "⚠️ Noma'lum reyting turi.", show_alert=True)
            return
        chat_id_filter = call.message.chat.id if scope == "g" else None
        text, total_pages = builder(page, chat_id=chat_id_filter)
        kb = _top_page_markup(kind, page, total_pages, scope)
        try:
            bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
    except Exception as e:
        _logger.warning("cb_top_page xatolik: %s", e)
        try:
            bot.answer_callback_query(call.id, "⚠️ Xatolik yuz berdi.", show_alert=True)
        except Exception:
            pass


