#  🏅 FAOLLIK BALLARI TIZIMI — har bir o'yin natijasiga qarab ball beriladi/ayiriladi:
#    • G'alaba qozongan (va oxirigacha qolgan) o'yinchi: +5 ball
#    • Mag'lub bo'lgan (lekin oxirigacha qolgan) o'yinchi: -5 ball
#    • O'yin davomidagi ENG FAOL o'yinchi (eng ko'p tun/kun harakati qilgan): +25 ball
#    • O'yinni tashlab ketgan yoki AFK bo'lib chetlashtirilgan o'yinchi: -10 ball
#  /balltop_kun, /balltop_hafta, /balltop_oy, /balltop_mutlaq — davr bo'yicha reyting
# ================================================================================

def add_points(uid, points, reason=""):
    with db_lock:
        cur.execute(
            "INSERT INTO points_log (user_id, points, reason, ts) VALUES (?, ?, ?, ?)",
            (uid, points, reason, time.time()),
        )
        conn.commit()


def get_points_leaderboard(period, limit=10, member_ids=None):
    """period: 'kun', 'hafta', 'oy', 'mutlaq'. member_ids berilsa (masalan bitta
    guruhning a'zolari), faqat o'sha ID'lar hisobga olinadi."""
    now = time.time()
    since = {
        "kun": now - 86400,
        "hafta": now - 7 * 86400,
        "oy": now - 30 * 86400,
        "mutlaq": 0,
    }.get(period, 0)
    with db_lock:
        cur.execute(
            "SELECT user_id, SUM(points) FROM points_log WHERE ts >= ? GROUP BY user_id ORDER BY SUM(points) DESC LIMIT ?",
            (since, limit if member_ids is None else limit * 5),
        )
        rows = cur.fetchall()
    result = []
    for uid, total in rows:
        if total is None:
            continue
        if member_ids is not None and uid not in member_ids:
            continue
        u = user_dict(uid)
        result.append((uid, u.get("name") or "O'yinchi", total))
        if len(result) >= limit:
            break
    return result


PERIOD_LABELS = {"kun": "📅 Kunlik", "hafta": "🗓 Haftalik", "oy": "📆 Oylik", "mutlaq": "♾ Mutlaq (bot boshidan)"}


def build_points_top_text(period, chat_id=None):
    member_ids = get_group_member_ids(chat_id) if chat_id is not None else None
    rows = get_points_leaderboard(period, member_ids=member_ids)
    label = PERIOD_LABELS.get(period, period)
    scope_note = " — shu guruh" if chat_id is not None else ""
    if not rows:
        return f"🏅 {label}{scope_note} ball reytingi hozircha bo'sh."
    lines = [f"🏅 <b>{label}{scope_note} FAOLLIK BALLARI REYTINGI</b>\n"]
    for i, (uid, name, total) in enumerate(rows, 1):
        lines.append(f"{i}. {mention(uid, name)} — <b>{total}</b> ball")
    return "\n".join(lines)


def _balltop_menu_kb(scope):
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(
        types.InlineKeyboardButton("📅 Kunlik", callback_data=f"balltop|kun|{scope}"),
        types.InlineKeyboardButton("🗓 Haftalik", callback_data=f"balltop|hafta|{scope}"),
    )
    kb.add(
        types.InlineKeyboardButton("📆 Oylik", callback_data=f"balltop|oy|{scope}"),
        types.InlineKeyboardButton("♾ Mutlaq", callback_data=f"balltop|mutlaq|{scope}"),
    )
    return kb


@bot.message_handler(commands=["balltop"])
def cmd_balltop(message):
    """🏅 Ball reytingi — soddalashtirildi: 4 ta alohida buyruq (/balltop_kun va h.k.)
    o'rniga BITTA /balltop + davr tanlash tugmalari. Guruhda so'ralsa (bot egasi
    bo'lmasa) faqat shu guruh a'zolari, bot egasi so'raganda esa barcha
    foydalanuvchilar ko'rsatiladi — xuddi /top, /topalmaz, /topdollar kabi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    chat_filter, scope = _top_scope_for(message.chat, message.from_user.id if message.from_user else None)
    text = build_points_top_text("oy", chat_id=chat_filter)
    bot.send_message(message.chat.id, text, reply_markup=_balltop_menu_kb(scope))


@bot.callback_query_handler(func=lambda c: c.data.startswith("balltop|"))
def cb_balltop(call):
    maybe_capture_owner(call.from_user)
    _, period, scope = call.data.split("|")
    chat_filter = call.message.chat.id if scope == "g" else None
    text = build_points_top_text(period, chat_id=chat_filter)
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=_balltop_menu_kb(scope))
    except Exception:
        pass
    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("ptop|"))
def cb_points_top(call):
    maybe_capture_owner(call.from_user)
    _, period = call.data.split("|")
    smart_render(call, build_points_top_text(period), with_back_button())
    bot.answer_callback_query(call.id)


def build_top_groups_text(limit=10):
    groups = list_known_groups()
    if not groups:
        return "🏘 Hozircha ma'lum guruhlar yo'q."
    lines = ["🏘 <b>TOP GURUHLAR</b>\n"]
    for i, (chat_id, title) in enumerate(groups[:limit], 1):
        lines.append(f"{i}. {title or chat_id} (<code>{chat_id}</code>)")
    return "\n".join(lines)


