def alive_role_flavor_lines(game):
    """Tirik o'yinchilar orasidagi rollarga qarab tungi atmosfera matnlarini yig'adi."""
    lines = []
    seen_roles = set()
    for p in alive_players(game).values():
        role = p["role"]
        if role in NIGHT_FLAVOR_TEXTS and role not in seen_roles:
            seen_roles.add(role)
            lines.append(NIGHT_FLAVOR_TEXTS[role])
    return lines


def team_of(role):
    if role in MAFIA_ROLES:
        return "mafia"
    if role in INDEPENDENT_ROLES:
        return "independent"
    return "town"


def role_goal_line(role):
    """🎯 Rol tushganda o'yinchi uzun tavsifni qayta o'qib, o'zi xulosa
    chiqarib o'tirmasin deb — BIR QATORLIK aniq "maqsad" xulosasi qaytaradi.
    Agar rolning o'z tavsifida ALLAQACHON aniq "Maqsad..." ko'rsatilgan bo'lsa
    (masalan Joker/Zombi/Yollanma qotil) — bu yerda takrorlanmaydi."""
    desc = ROLES_INFO.get(role, "")
    if "Maqsad" in desc:
        return ""
    team = team_of(role)
    if team == "mafia":
        return "🎯 Maqsadingiz: hamma tinch aholi yo'q qilingunicha (yoki soningiz ularga teng/ko'p bo'lgunicha) yashirin kurash olib borish."
    if team == "independent":
        return "🎯 Maqsadingiz: qobiliyatingizdan unumli foydalanib omon qolish — mafiya batamom yo'q qilinsa, siz ham tinch aholi bilan birga g'olib hisoblanasiz."
    return "🎯 Maqsadingiz: mafiyani aniqlab, kunduzgi ovoz berish orqali shahardan haydash."


def mafia_count_for(n):
    if n <= 7:
        return 1
    elif n <= 12:
        return 2
    elif n <= 16:
        return 3
    else:
        return max(3, n // 5)


