def hero_price(hero_key, item):
    """Geroy narxi (olmos yoki Stars): bot egasi o'zgartirgan qiymat bo'lsa — o'sha, aks holda standart."""
    tier = "burgut" if hero_key == "burgut" else "oddiy"
    default = HERO_PRICE_DEFAULTS[tier][item]
    try:
        raw = get_setting(f"hero_price_{tier}_{item}")
        return max(1, int(raw)) if raw not in (None, "") else default
    except Exception:
        return default


def hero_auto_enabled(uid):
    """🤖 Geroy mahoratlarining AVTOMATIK ishlashi (standart — yoqilgan). Panel tugmasi bilan o'chiriladi."""
    try:
        return get_charges(uid).get("hero_auto", 1) != 0
    except Exception:
        return True


def _grant_hero(uid, hero_key):
    """Geroyni 1-daraja bilan beradi (foydalanuvchida allaqachon geroy bo'lmasa). True/False qaytaradi."""
    with db_lock:
        cur.execute("INSERT OR IGNORE INTO heroes (user_id, hero_key, level, acquired_at) VALUES (?, ?, 1, ?)",
                    (uid, hero_key, time.time()))
        ok = cur.rowcount > 0
        conn.commit()
    return ok


def _migrate_hero_levels_v8():
    """Eski 1-15 darajalarni yangi 1-3 darajaga BIR MARTA o'tkazadi (1-5→1, 6-10→2, 11-15→3):
    hech kim yo'qotmaydi."""
    try:
        if get_setting("hero_levels_migrated_v8") == "1":
            return
        with db_lock:
            cur.execute("UPDATE heroes SET level = CASE WHEN level <= 5 THEN 1 WHEN level <= 10 THEN 2 ELSE 3 END")
            conn.commit()
        set_setting("hero_levels_migrated_v8", "1")
    except Exception:
        _logger.exception("Geroy darajalarini yangi tizimga o'tkazishda xatolik")


_migrate_hero_levels_v8()


def text_progress_bar(current, total, length=10):
    """🎨 UX: matnli progress-bar, masalan [████████░░] 12/15-daraja ko'rinishida.
    `current`/`total` — joriy va maksimal qiymat, `length` — panjara uzunligi (belgi soni)."""
    total = max(1, total)
    current = max(0, min(current, total))
    filled = round(length * current / total)
    filled = max(0, min(length, filled))
    return "[" + ("█" * filled) + ("░" * (length - filled)) + f"] {current}/{total}"


