def notify_target_touched(game, target_uid, visitor_role=None):
    """🌙 Har qanday rol tunda kimnidir nishonga olsa, o'sha kishiga ANIQ qaysi
    rol kelganini (rolga xos, noyob matn bilan) aytadigan xabar yuboriladi —
    bir kechada bir kishiga faqat bitta marta (bir nechta rol bir xil odamni
    tanlasa ham, birinchi kelgan rol aytiladi)."""
    if target_uid in (None, "skip", "yes", "no") or target_uid not in game["players"]:
        return
    touched = game.setdefault("touched_tonight", set())
    if target_uid in touched:
        return
    touched.add(target_uid)
    if visitor_role and visitor_role in ROLE_VISIT_TEXT:
        safe_send(target_uid, ROLE_VISIT_TEXT[visitor_role])
    elif visitor_role:
        safe_send(target_uid, f"🌙 <i>Siznikiga <b>{visitor_role}</b> keldi...</i>")
    else:
        safe_send(target_uid, "🌙 <i>Kimdir tunda sizga qiziqib, harakatingizni yashirincha kuzatdi...</i>")


def send_scene_photo(chat_id, local_path, url_fallback, caption, reply_markup=None):
    """Mahalliy 'assets' papkasidagi surat bo'lsa o'shani, bo'lmasa zaxira URL'ni yuboradi.
    ⚙️ v8: guruhda "Tun/kun rasmlari" o'chirilgan bo'lsa, faqat matn yuboriladi."""
    if gsv(chat_id, "scene_photo") == "0":
        bot.send_message(chat_id, caption, reply_markup=reply_markup)
        return
    try:
        if os.path.isfile(local_path):
            with open(local_path, "rb") as f:
                bot.send_photo(chat_id, f, caption=caption, reply_markup=reply_markup)
                return
    except Exception:
        pass
    try:
        bot.send_photo(chat_id, url_fallback, caption=caption, reply_markup=reply_markup)
    except Exception:
        bot.send_message(chat_id, caption, reply_markup=reply_markup)


def esc(value):
    """🔒 Foydalanuvchi kiritgan (yoki Telegram'dan kelgan) har qanday matnni
    (ism, familya, username, laqab va h.k.) botning xabarlarida (parse_mode="HTML")
    xavfsiz ko'rsatish uchun escape qiladi. Bot GLOBAL ravishda parse_mode="HTML"
    bilan ishlaydi, shuning uchun agar foydalanuvchi nomida "<", ">" yoki "&"
    belgilari bo'lsa-yu ular escape qilinmasa — Telegram xabarni yubora olmay
    xatolik beradi (yoki, yomonroq holatda, foydalanuvchi o'z ismi orqali soxta
    HTML teglar/havolalar "in'ektsiya" qilishi mumkin). Shu sababli BOTDA
    ISHTIROKCHI NOMI ko'rsatiladigan HAR BIR joyda ushbu funksiya orqali
    o'tkazilishi SHART — ism o'chirilmaydi (eski koddagidek harflar tashlab
    yuborilmaydi), balki to'g'ri kodlanadi va asl ko'rinishida chiqadi."""
    return html.escape(str(value if value is not None else ""), quote=False)


