import string as _string_mod


def _unicode_style_map(base_upper, base_lower, base_digit=None, exceptions=None):
    m = dict(exceptions or {})
    for i, c in enumerate(_string_mod.ascii_uppercase):
        m.setdefault(c, chr(base_upper + i))
    for i, c in enumerate(_string_mod.ascii_lowercase):
        m.setdefault(c, chr(base_lower + i))
    if base_digit is not None:
        for i, c in enumerate("0123456789"):
            m.setdefault(c, chr(base_digit + i))
    return m


_CIRCLED_DIGITS = "⓪①②③④⑤⑥⑦⑧⑨"

NAME_STYLE_MAPS = {
    "bold_serif": _unicode_style_map(0x1D400, 0x1D41A, 0x1D7CE),
    "fraktur": _unicode_style_map(0x1D504, 0x1D51E, None, {
        "C": "\u212D", "H": "\u210C", "I": "\u2111", "R": "\u211C", "Z": "\u2128"}),
    "double_struck": _unicode_style_map(0x1D538, 0x1D552, 0x1D7D8, {
        "C": "\u2102", "H": "\u210D", "N": "\u2115", "P": "\u2119", "Q": "\u211A", "R": "\u211D", "Z": "\u2124"}),
    "monospace": _unicode_style_map(0x1D670, 0x1D68A, 0x1D7F6),
    "cursive": _unicode_style_map(0x1D49C, 0x1D4B6, None, {
        "B": "\u212C", "E": "\u2130", "F": "\u2131", "H": "\u210B", "I": "\u2110",
        "L": "\u2112", "M": "\u2133", "R": "\u211B", "e": "\u212F", "g": "\u210A", "o": "\u2134"}),
    "sans_bold": _unicode_style_map(0x1D5D4, 0x1D5EE, 0x1D7EC),
    "circled": _unicode_style_map(0x24B6, 0x24D0, None, {str(i): _CIRCLED_DIGITS[i] for i in range(10)}),
}

# key -> (ko'rsatiladigan nomi, narxi Stars, kunlik muddati)
NAME_STYLE_CATALOG = {
    "bold_serif":    ("𝐁𝐨𝐥𝐝 — qalin", 220, 30),
    "cursive":       ("𝓒𝓾𝓻𝓼𝓲𝓿𝓮 — go'zal yozuv", 260, 30),
    "fraktur":       ("𝔊𝔬𝔱𝔥𝔦𝔠 — qadimiy", 280, 30),
    "double_struck": ("𝔻𝕠𝕦𝕓𝕝𝕖 — kristall", 320, 30),
    "monospace":     ("𝚃𝚎𝚛𝚖𝚒𝚗𝚊𝚕 — hacker", 260, 30),
    "sans_bold":     ("𝗦𝗮𝗻𝘀 𝗕𝗼𝗹𝗱 — zamonaviy", 220, 30),
    "circled":       ("Ⓒⓘⓡⓒⓛⓔⓓ — dumaloq", 300, 30),
}


def apply_name_style(text, style_key):
    m = NAME_STYLE_MAPS.get(style_key)
    if not m:
        return text
    return "".join(m.get(c, c) for c in text)


def name_style_active(uid):
    ch = get_charges(uid)
    key = ch.get("name_style") or ""
    until = ch.get("name_style_until", 0)
    return key if (key and until and until > time.time()) else None


def name_style_grant(uid, style_key, days):
    if style_key not in NAME_STYLE_CATALOG:
        return
    ch = get_charges(uid)
    now = time.time()
    cur_until = ch.get("name_style_until", 0)
    base = cur_until if (ch.get("name_style") == style_key and cur_until > now) else now
    ch["name_style"] = style_key
    ch["name_style_until"] = base + days * 86400
    set_charges(uid, ch)


