            call.message.chat.id,
            title=f"{sample} — Ism uslubi",
            description=f"{days} kunga '{label}' ism uslubini oling ({price} ⭐️ Stars).",
            invoice_payload=f"namestyle_{uid}_{key}",
            provider_token="",
