@bot.message_handler(commands=["ismrangi"])
def cmd_ismrangi(message):
    """🎨 Pullik ism-rangi do'koni — /ismrangi"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    user_dict(uid, message.from_user.first_name)
    text, kb = name_color_shop_text_and_kb(uid)
    bot.send_message(message.chat.id, text, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("namecolor|"))
def cb_name_color_buy(call):
    maybe_capture_owner(call.from_user)
    uid = call.from_user.id
    key = call.data.split("|", 1)[1]
    if key not in NAME_COLOR_CATALOG:
        bot.answer_callback_query(call.id, "❌ Bunday rang yo'q.", show_alert=True)
        return
    emoji, label, price, days = NAME_COLOR_CATALOG[key]
    try:
        bot.send_invoice(
            call.message.chat.id,
            title=f"{emoji} {label} — Ism rangi",
            description=f"{days} kunga '{label}' ism rangini oling ({price} ⭐️ Stars).",
            invoice_payload=f"namecolor_{uid}_{key}",
            provider_token="",
            currency="XTR",
            prices=[types.LabeledPrice(label=label, amount=price)],
        )
        bot.answer_callback_query(call.id)
    except Exception as e:
        _logger.warning("cb_name_color_buy xatolik: %s", e)
        bot.answer_callback_query(call.id, "❌ To'lov tizimida xatolik. Keyinroq urinib ko'ring.", show_alert=True)


# ================================================================================
#  👑 OYNING HOMIYSI — oyda eng ko'p ⭐️ Stars sarflagan foydalanuvchilar reytingi.
#  G'olib(lar)ga bir martalik mukofot + 1-o'ringa 7 kunlik maxsus "OYNING HOMIYSI"
#  belgisi beriladi (mention() orqali HAMMA joyda ko'rinadi). Eng katta xarid
#  qiluvchilarni ("whale") raqobatga undab, ko'proq sarflashga rag'batlantiradi.
# ================================================================================
SPONSOR_REWARDS = [  # (o'rin, diamond, elite_days, badge_days)
    (1, 40, 7, 7),
    (2, 20, 4, 0),
    (3, 10, 2, 0),
]


def _ym_now():
    return time.strftime("%Y-%m")


def _track_monthly_spend(uid, stars_amount):
    if not stars_amount:
        return
    try:
        with db_lock:
            cur.execute(
                "INSERT INTO monthly_spend (user_id, ym, stars) VALUES (?,?,?) "
                "ON CONFLICT(user_id, ym) DO UPDATE SET stars = stars + excluded.stars",
                (uid, _ym_now(), int(stars_amount)))
            conn.commit()
    except Exception as e:
        _logger.warning("_track_monthly_spend xatolik: %s", e)


def _monthly_top_spenders(ym, limit=5):
    with db_lock:
        cur.execute("SELECT user_id, stars FROM monthly_spend WHERE ym=? ORDER BY stars DESC LIMIT ?", (ym, limit))
        return cur.fetchall()


@bot.message_handler(commands=["homiylar"])
def cmd_homiylar(message):
    """👑 Shu oyning eng ko'p xarajat qilgan (Stars sarflagan) foydalanuvchilari."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    rows = _monthly_top_spenders(_ym_now(), 10)
    if not rows:
        bot.send_message(message.chat.id, "👑 Bu oy hali hech kim Stars orqali xarid qilmagan. Birinchi bo'ling!")
        return
    medals = ["🥇", "🥈", "🥉"]
    lines = []
    for i, (uid2, stars) in enumerate(rows):
        medal = medals[i] if i < 3 else f"{i + 1}."
        lines.append(f"{medal} {esc(user_dict(uid2)['name'])} — {stars} ⭐️")
    bot.send_message(message.chat.id,
        "👑✨ <b>OYNING HOMIYLARI</b> ✨👑\n"
        "━━━━━━━━━━━━━━━━━━\n\n" + "\n".join(lines) +
        "\n\n━━━━━━━━━━━━━━━━━━\n"
        "🏆 Oy oxirida TOP-3 mukofot oladi, 1-o'rin esa 7 kunlik "
        "<b>«👑 OYNING HOMIYSI»</b> unvoniga ega bo'ladi — ismi bilan HAMMA joyda ko'rinadi!")


@bot.message_handler(commands=["oy_gomiysi_yakunla"])
def cmd_oy_gomiysi_yakunla(message):
    """(faqat bot egasi) — joriy oy uchun TOP-3 xaridorni yakunlab, mukofot beradi."""
    if not is_owner(message.from_user.id):
        return
    safe_delete(message)
    ym = _ym_now()
    rows = _monthly_top_spenders(ym, 3)
    if not rows:
        bot.send_message(message.chat.id, "👑 Bu oy hech kim xarid qilmagan — yakunlashning hojati yo'q.")
        return
    summary = []
    for i, (uid2, stars) in enumerate(rows):
        if i >= len(SPONSOR_REWARDS):
            break
        rank, diamond, elite_days, badge_days = SPONSOR_REWARDS[i]
        add_balance(uid2, diamond=diamond)
        if elite_days:
            grant_elite_days(uid2, elite_days)
        if badge_days:
            ch = get_charges(uid2)
            ch["sponsor_badge_until"] = time.time() + badge_days * 86400
            set_charges(uid2, ch)
        parts = [f"{diamond} 💎"]
        if elite_days:
            parts.append(f"{elite_days} kun ELITE")
        if badge_days:
            parts.append(f"{badge_days} kun 👑 OYNING HOMIYSI unvoni")
        safe_send(uid2, f"🏆 Tabriklaymiz! Siz shu oy {rank}-o'rinni egalladingiz ({stars} ⭐️ sarfladingiz)!\n"
                         f"Mukofot: {' + '.join(parts)}")
        summary.append(f"{rank}. {esc(user_dict(uid2)['name'])} — {stars}⭐️ → {' + '.join(parts)}")
    bot.send_message(message.chat.id, "✅ <b>Oy yakunlandi, mukofotlar berildi:</b>\n\n" + "\n".join(summary))


def mention(uid, name):
    """Guruh xabarlarida o'yinchi ismini bosilganda uning profiliga o'tadigan qilib ko'rsatish uchun.
    🦁 Agar o'yinchi HUNTER ELITE bo'lsa, ismi ikki tomonidan haqiqiy PREMIUM
    SHER emojisi bilan bezaladi (CLAN_PORTRAIT_EMOJI["logo"]) — ELITE belgisi.
    🖼 Agar o'yinchida faol Mifik ramka bo'lsa, uning ismi HAMMA ko'radigan joyda
    (o'yin e'lonlari, reytinglar, o'lim xabarlari va h.k.) maxsus ramka bilan ko'rinadi.
    ❗️ MUHIM: <tg-emoji> tegi <a href="tg://user?id=..."> havolasi ICHIGA
    JOYLASHTIRILMAYDI — Telegram bunday "ichma-ich" (nested) formatni to'g'ri
    ko'rsata olmay, faqat zaxira (fallback) belgini chiqarib qo'yadi. Shuning
    uchun premium belgi havola TASHQARISIGA (oldiga/orqasiga) qo'shiladi —
    shunda u guruhda ham, shaxsiy chatda ham haqiqiy premium ko'rinishda chiqadi.
    🔒 Ism (name) va laqab (nickname) HAR DOIM esc() orqali xavfsizlashtiriladi —
    aks holda foydalanuvchi o'z Telegram ismiga "<", ">" yoki "&" kabi belgilar
    qo'yib qo'ysa, bot HTML xabarni yubora olmay qolishi yoki soxta teglar
    "in'ektsiya" qilinishi mumkin edi."""
    display = name or "O'yinchi"
    prefix = ""
    suffix = ""
    try:
        ch = get_charges(uid)
        # 🦁 HUNTER ELITE a'zosi bo'lsa va shaxsiy laqab (taxallus) o'rnatgan bo'lsa —
        # hamma joyda (o'yin e'lonlari, reytinglar, o'lim xabarlari) o'sha laqab bilan ko'rinadi.
        elite_until = ch.get("vip_until", 0)
        if elite_until and elite_until > time.time():
            nick = (ch.get("nickname") or "").strip()
            if nick:
                display = nick
            # 💎 Endi faqat "𝐄𝐋𝐈𝐓𝐄 💎" (qalin shrift + olmos) ko'rsatiladi — oldingi
            # 🦁 sher belgisi (prefiksda) olib tashlandi, orqadagi olmos saqlanib qoldi.
            prefix += "<b>𝐄𝐋𝐈𝐓𝐄</b> 💎 "
        ramka_until = ch.get("ramka_until", 0)
        if ramka_until and ramka_until > time.time():
            prefix += premium_emoji("frame", "🖼") + "✨ "
            suffix = " ✨" + premium_emoji("frame", "🖼") + suffix
        # 🎨 v13: sotib olingan "Ism uslubi" (Unicode shrift skin) — faol bo'lsa,
        # ism harflari maxsus uslubli belgilarga almashtiriladi (masalan 𝕭𝖔𝖑𝖉).
        # ESLATMA: bu esc() dan OLDIN qilinadi — aks holda "&amp;" kabi HTML
        # entity ichidagi harflar ham (noto'g'ri) o'zgartirilib qolar edi.
        style_key = ch.get("name_style") or ""
        style_until = ch.get("name_style_until", 0)
        if style_key and style_until and style_until > time.time():
            display = apply_name_style(display, style_key)
        # 🎨 v14: "Ism rangi" — Telegram bot xabarlarida harf rangini o'zgartirib
        # bo'lmaydi (Bot API buni qo'llab-quvvatlamaydi), shuning uchun buning
        # o'RNIga ismning ikki tomoniga tanlangan RANGDAGI belgi qo'yiladi —
        # natijada ism "rangli" ko'rinadi va HAMMA joyda bir xil chiqadi.
        color_key = ch.get("name_color") or ""
        color_until = ch.get("name_color_until", 0)
        if color_key and color_until and color_until > time.time():
            cemoji = NAME_COLOR_CATALOG.get(color_key, ("",))[0]
            if cemoji:
                prefix += cemoji + " "
                suffix = " " + cemoji + suffix
        # 👑 v14: oyning eng ko'p xarajat qilgan foydalanuvchisi (Oyning homiysi)
        sponsor_until = ch.get("sponsor_badge_until", 0)
        if sponsor_until and sponsor_until > time.time():
            prefix += "👑 <b>OYNING HOMIYSI</b> "
    except Exception:
        pass
    safe_name = esc(display)
    return f'{prefix}<a href="tg://user?id={uid}">{safe_name}</a>{suffix}'


