def announce_item_use(chat_id, user_id, item_label, target_id=None, effect_text=""):
    """🎒 Do'kondan olingan buyum o'yin ichida ishlatilganda guruhga — KIM ekani oshkor
    qilinmasdan (anonim), lekin QAYSI buyum ishlaganini aniq bildiruvchi tarzda e'lon
    qilinadi. Ishlatgan kishiga natija haqidagi DM chaqiruvchi joyda alohida yuboriladi,
    shu funksiya faqat guruh e'loni va (ixtiyoriy) qo'shimcha DM uchun."""
    flavor = ITEM_ANNOUNCE_FLAVORS.get(item_label, f"🎒 <i>Kimdir do'kondan olingan buyumini ishlatdi:</i> <b>{item_label}</b>")
    try:
        bot.send_message(chat_id, flavor)
    except Exception:
        pass
    if target_id is not None:
        # ba'zi chaqiruvchilar uchun qo'shimcha DM kerak bo'lishi mumkin — ixtiyoriy
        target_name = user_dict(target_id).get("name", "O'yinchi")
        extra = f"\n🎯 Qo'llanildi: {mention(target_id, target_name)}"
        if effect_text:
            extra += f"\n{effect_text}"
        safe_send(user_id, extra)


def announce_hero_ability_use(chat_id, hero_name, ability_name, uid=None, hero_key=None):
    """🏆 Geroy mahorati o'yin ichida QO'LDA ishlatilganda guruhga E'LON QILINADI —
    boshqa tungi/kunduzgi harakat e'lonlari bilan bir xil ohangda: KIM ekani
    ANONIM qoladi (o'yin sirini saqlash uchun), lekin QAYSI GEROY va QAYSI
    MAHORAT ishlatilgani ANIQ, ochiq yozib ko'rsatiladi.

    🎬 Agar `uid`/`hero_key` berilgan bo'lsa (mahoratni ishlatgan o'yinchi ma'lum
    bo'lsa) — shu safar (1) "Geroy tarixi" (/geroy_tarix) uchun yozuv qo'shiladi
    va (2) o'sha o'yinchiga qisqa animatsion "mahorat ishlatildi" effekti (🎰)
    shaxsiy xabarda yuboriladi."""
    text = f"🏆 <i>Kimningdir</i> <b>{hero_name}</b> <i>geroyi mahoratini ishga tushirdi:</i> <b>{ability_name}</b> 🔥"
    try:
        bot.send_message(chat_id, text)
    except Exception as e:
        log_hero_error("announce_hero_ability_use (e'lon)", e)
    if uid is not None:
        log_hero_ability_use(uid, hero_key, ability_name)
        _send_hero_ability_effect(uid)


# 🦊 Rol nomidagi oddiy (unicode) belgini — agar mos PREMIUM_EMOJI ID mavjud
# bo'lsa — HAQIQIY premium emojiga almashtirish uchun xarita. Bu FAQAT
# ko'rsatish (roster_breakdown_text) uchun ishlatiladi — ROLES_INFO, MAFIA_ROLES,
# team_of() va boshqa o'yin-logikasidagi asl rol nomlariga HECH QACHON tegmaydi,
# shuning uchun o'yin mexanikasi butunlay avvalgidek ishlayveradi.
_ROLE_EMOJI_PREMIUM_MAP = {
    "🎩": "top_hat",       # Don
    "🗡": "dagger",        # Qotil
    "🏹": "bow",           # Mergan
    "🪓": "axe",           # Varvar
    "🥷": "ninja",         # O'g'ri
    "🧙‍♂️": "wizard_man",  # Sehrgar
    "👻": "ghost",         # Arvoh
    "💣": "bomb",          # Terrorist
    "🤪": "crazy",         # Telba
    "📐": "ruler",         # Arxitektor
    "👮‍♂️": "police",      # Serjant
    "⚖️": "scale",         # Advokat
    "🎖": "medal",         # General
    "👨‍⚖️": "scale_2",     # Sudya
    "🕵️‍♂️": "detective",  # Komissar
}


def premium_role_label(role_name):
    """Rolni ko'rsatish uchun ENG YAXSHI variantni qaytaradi — FAQAT matnni
    chiroyli ko'rsatish uchun, o'yin logikasidagi asl qiymatga (masalan
    game["players"][uid]["role"]) hech qanday ta'sir qilmaydi.
    1) Avval ROLE_PORTRAIT_EMOJI'da shu rol uchun HAQIQIY Hanter portreti
       bor-yo'qligi tekshiriladi — bo'lsa, o'sha ishlatiladi.
    2) Bo'lmasa, eski usul — rol nomidagi oddiy emojini mos PREMIUM_EMOJI
       belgisiga almashtirish — ishlatiladi (zaxira sifatida)."""
    if role_name in ROLE_PORTRAIT_EMOJI:
        return role_portrait(role_name)
    for plain, key in _ROLE_EMOJI_PREMIUM_MAP.items():
        if plain in role_name:
            return role_name.replace(plain, premium_emoji(key, plain))
    return role_name


def roster_breakdown_text(game):
    """qoshimchakod-larda ko'rilgan boshqa botlar uslubida — tirik o'yinchilar ro'yxati
    va ular orasidagi rol tarkibi (kim qaysi rolda ekani oshkor qilinmaydi, faqat statistika)."""
    alive = alive_players(game)
    if not alive:
        return "Tirik o'yinchi qolmadi."

    lines = ["👥 <b>Tirik o'yinchilar:</b>"]
    for i, (uid, p) in enumerate(alive.items(), start=1):
        lines.append(f"{i}. {mention(uid, p['name'])}")

    mafia_roles, indep_roles, town_roles = [], [], []
    for p in alive.values():
        team = team_of(p["role"])
        if team == "mafia":
            mafia_roles.append(p["role"])
        elif team == "independent":
            indep_roles.append(p["role"])
        else:
            town_roles.append(p["role"])

    def group_counts(roles):
        counts = {}
        for r in roles:
            counts[r] = counts.get(r, 0) + 1
        parts = []
        for r, c in counts.items():
            label = premium_role_label(r)  # 🦊 faqat ko'rsatish uchun premium emoji
            parts.append(label if c == 1 else f"{label} - {c}")
        return ", ".join(parts) if parts else "—"

    lines.append("")
    lines.append(f"🏠 <b>Tinch aholilar - {len(town_roles)}:</b>\n{group_counts(town_roles)}")
    lines.append(f"👤 <b>Yakka rollar - {len(indep_roles)}:</b>\n{group_counts(indep_roles)}")
    lines.append(f"🕶 <b>Mafiyalar - {len(mafia_roles)}:</b>\n{group_counts(mafia_roles)}")
    lines.append("")
    lines.append(f"<b>Jami:</b> {len(alive)} ta")
    return "\n".join(lines)


