@bot.message_handler(commands=["start"])
def cmd_start(message):
    global BOT_USERNAME
    maybe_capture_owner(message.from_user)
    if BOT_USERNAME is None:
        BOT_USERNAME = bot.get_me().username

    if message.chat.type != "private":
        safe_delete(message)
        if message.chat.type in ("group", "supergroup"):
            # ▶️ /start endi guruhda — qaysi rejim (asosiy/Team/Para) ochiq bo'lsa,
            # o'shani boshlaydi (avvalgi /StartGame, /start_team, /start_para o'rniga).
            game = GAMES.get(message.chat.id)
            if game and game.get("squad_mode"):
                _start_special_game(message, "squad")
            elif game and game.get("couple_mode"):
                _start_special_game(message, "couple")
            else:
                cmd_startgame(message)
        return

    with db_lock:
        cur.execute("SELECT 1 FROM users WHERE user_id=?", (message.from_user.id,))
        is_new_user = cur.fetchone() is None

    # 🎮 guruhdagi "O'yinga qo'shilish" tugmasi orqali kelingan bo'lsa (deep-link:
    # https://t.me/BOT?start=join_<chat_id>) — shu yerda avtomatik o'yinga qo'shamiz
    parts = message.text.split(maxsplit=1)
    payload = parts[1].strip() if len(parts) > 1 else ""

    # 🤝 v9: taklif (referral) havolasi orqali kelgan — FAQAT yangi foydalanuvchiga ishlaydi
    if payload.startswith("ref_") and is_new_user:
        try:
            inviter_id = int(payload[len("ref_"):])
        except ValueError:
            inviter_id = None
        user_dict(message.from_user.id, message.from_user.first_name)
        if inviter_id:
            ok, ref_msg = apply_referral(message.from_user.id, inviter_id)
            if ok:
                bot.send_message(message.chat.id, ref_msg)
        payload = ""
    else:
        user_dict(message.from_user.id, message.from_user.first_name)

    if payload.startswith("join_"):
        try:
            join_chat_id = int(payload[len("join_"):])
        except ValueError:
            join_chat_id = None

        if join_chat_id is not None:
            status = do_join(join_chat_id, message.from_user)
            game = GAMES.get(join_chat_id)
            group_title = (game.get("chat_title") if game else None) or "guruh"
            group_link = game.get("group_link") if game else None
            kb = None
            if group_link:
                kb = types.InlineKeyboardMarkup()
                kb.add(types.InlineKeyboardButton(f"🔙 {group_title} guruhiga qaytish", url=group_link))

            if status == "ok":
                bot.send_message(
                    message.chat.id,
                    f"✅ <b>Siz o'yinga muvaffaqiyatli qo'shildingiz!</b>\n\n🎮 Guruh: <b>{group_title}</b>",
                    reply_markup=kb,
                )
            elif status == "need_squad":
                bot.send_message(message.chat.id, "🐺🦅 Bu — Jamoaviy o'yin! Guruhga qaytib, 🐺 Wolf yoki 🦅 Eagle tugmasidan birini bosib qo'shiling.", reply_markup=kb)
            elif status == "need_couple":
                bot.send_message(message.chat.id, "💍 Bu — Para o'yin! Guruhga qaytib, faqat 💍 tugmasi orqali (turmush o'rtog'ingiz bilan) qo'shiling.", reply_markup=kb)
            elif status == "already":
                bot.send_message(message.chat.id, "ℹ️ Siz allaqachon bu o'yinga qo'shilgansiz.", reply_markup=kb)
            elif status == "banned":
                bot.send_message(message.chat.id, "⛔ Siz botdan foydalanishdan bloklangansiz.")
            elif status == "other_game":
                bot.send_message(message.chat.id, "⛔ Siz allaqachon boshqa guruhdagi faol o'yindasiz — bir vaqtda faqat 1 guruhda o'ynash mumkin.", reply_markup=kb)
            else:  # no_game
                bot.send_message(
                    message.chat.id,
                    "❌ Bu o'yin allaqachon boshlangan yoki topilmadi. Guruhda yangi o'yin ochilishini kuting.",
                    reply_markup=kb,
                )
                # 🔧 TUZATISH: avval bu yerda foydalanuvchida hech qanday tugma qolmasdi —
                # xato xabaridan keyin bosadigan narsa topolmay, yana /start deb urinaverar
                # (Telegram klienti ba'zan eski deep-link'ni qayta yuboradi) va xuddi shu
                # xatoni cheksiz ko'raverardi. Endi doim BOSH MENYU ham qo'shimcha
                # ko'rsatiladi — foydalanuvchida har doim bosadigan tugma bo'lishi uchun.
                bot.send_photo(
                    message.chat.id, MAIN_PHOTO,
                    caption="👇 Bu orada, bosh menyudan foydalanishingiz mumkin:",
                    reply_markup=get_main_menu(None, message.from_user.id),
                )
            return

    if payload.startswith("squadjoin_"):
        try:
            rest = payload[len("squadjoin_"):]
            chat_id_s, squad = rest.rsplit("_", 1)
            join_chat_id = int(chat_id_s)
        except (ValueError, IndexError):
            join_chat_id, squad = None, None

        if join_chat_id is not None and squad in ("wolf", "eagle"):
            status = do_join(join_chat_id, message.from_user, squad=squad)
            game = GAMES.get(join_chat_id)
            group_title = (game.get("chat_title") if game else None) or "guruh"
            group_link = game.get("group_link") if game else None
            kb = None
            if group_link:
                kb = types.InlineKeyboardMarkup()
                kb.add(types.InlineKeyboardButton(f"🔙 {group_title} guruhiga qaytish", url=group_link))
            squad_label = "🐺 Wolf jamoasi" if squad == "wolf" else "🦅 Eagle jamoasi"
            if status in ("ok", "already"):
                bot.send_message(
                    message.chat.id,
                    f"✅ Siz <b>{squad_label}</b>ga qo'shildingiz!\n\n🎮 Guruh: <b>{group_title}</b>",
                    reply_markup=kb,
                )
            elif status == "banned":
                bot.send_message(message.chat.id, "⛔ Siz botdan foydalanishdan bloklangansiz.")
            elif status == "other_game":
                bot.send_message(message.chat.id, "⛔ Siz allaqachon boshqa guruhdagi faol o'yindasiz — bir vaqtda faqat 1 guruhda o'ynash mumkin.", reply_markup=kb)
            else:  # no_game
                bot.send_message(
                    message.chat.id,
                    "❌ Bu o'yin allaqachon boshlangan yoki topilmadi. Guruhda yangi o'yin ochilishini kuting.",
                    reply_markup=kb,
                )
                bot.send_photo(
                    message.chat.id, MAIN_PHOTO,
                    caption="👇 Bu orada, bosh menyudan foydalanishingiz mumkin:",
                    reply_markup=get_main_menu(None, message.from_user.id),
                )
            return

    if payload.startswith("couplejoin_"):
        try:
            join_chat_id = int(payload[len("couplejoin_"):])
        except ValueError:
            join_chat_id = None

        if join_chat_id is not None:
            game = GAMES.get(join_chat_id)
            group_title = (game.get("chat_title") if game else None) or "guruh"
            group_link = game.get("group_link") if game else None
            kb = None
            if group_link:
                kb = types.InlineKeyboardMarkup()
                kb.add(types.InlineKeyboardButton(f"🔙 {group_title} guruhiga qaytish", url=group_link))

            if not game or game["phase"] != "waiting":
                bot.send_message(
                    message.chat.id,
                    "❌ Bu o'yin allaqachon boshlangan yoki topilmadi. Guruhda yangi o'yin ochilishini kuting.",
                    reply_markup=kb,
                )
                bot.send_photo(
                    message.chat.id, MAIN_PHOTO,
                    caption="👇 Bu orada, bosh menyudan foydalanishingiz mumkin:",
                    reply_markup=get_main_menu(None, message.from_user.id),
                )
                return
            if is_banned(message.from_user.id):
                bot.send_message(message.chat.id, "⛔ Siz botdan foydalanishdan bloklangansiz.")
                return
            u = user_dict(message.from_user.id, message.from_user.first_name)
            spouse_id = u.get("married_to")
            if not spouse_id:
                bot.send_message(
                    message.chat.id,
                    "❌ Bu — Para o'yin, FAQAT rasmiy nikohdagi juftliklar qo'shila oladi. Avval /para orqali oila quring.",
                    reply_markup=kb,
                )
                return
            status = do_join(join_chat_id, message.from_user, via_couple=True)
            if status == "banned":
                bot.send_message(message.chat.id, "⛔ Siz botdan foydalanishdan bloklangansiz.")
                return
            if status == "other_game":
                bot.send_message(message.chat.id, "⛔ Siz allaqachon boshqa guruhdagi faol o'yindasiz — bir vaqtda faqat 1 guruhda o'ynash mumkin.", reply_markup=kb)
                return
            if spouse_id in game["players"]:
                bot.send_message(
                    message.chat.id,
                    f"✅ Siz qo'shildingiz — turmush o'rtog'ingiz allaqachon o'yinda ekan!\n\n🎮 Guruh: <b>{group_title}</b>",
                    reply_markup=kb,
                )
                return
            su = user_dict(spouse_id)
            spouse_name = su.get("name") or "Sherigingiz"

            class _FakeUser:
                pass

            fake = _FakeUser()
            fake.id = spouse_id
            fake.first_name = spouse_name
            join_status = do_join(join_chat_id, fake, via_couple=True)
            if join_status in ("ok", "already"):
                bot.send_message(
                    message.chat.id,
                    f"💍 Siz va {spouse_name} birgalikda o'yinga qo'shildingiz!\n\n🎮 Guruh: <b>{group_title}</b>",
                    reply_markup=kb,
                )
                safe_send(spouse_id, f"💍 Turmush o'rtog'ingiz sizni <b>{group_title}</b> guruhidagi Hunter Mafia o'yiniga birga qo'shdi!")
            else:
                bot.send_message(message.chat.id, "✅ Siz qo'shildingiz. (Turmush o'rtog'ingizni avtomatik qo'shib bo'lmadi — ehtimol u boshqa guruhdagi faol o'yinda.)", reply_markup=kb)
            return

    # 🎴 Mini App'dan kelgan chuqur havolalar (xarid/qimor) — WebApp ichidan
    # to'g'ridan-to'g'ri pul yechish xavfli bo'lgani uchun, tugma bosilganda
    # foydalanuvchi shu yerga (o'z shaxsiy chatiga) yo'naltiriladi va amal
    # ANIQ shu foydalanuvchi nomidan, botning ishonchli kodi orqali bajariladi.
    if payload.startswith("buy_"):
        try:
            _, cat, key = payload.split("_", 2)
            ok, msg = _perform_shop_purchase(message.from_user.id, message.from_user.first_name, cat, key)
        except Exception:
            ok, msg = False, "❌ Xarid havolasi noto'g'ri."
        bot.send_message(message.chat.id, msg, reply_markup=with_back_button())
        return

    if payload.startswith("cosmetic_buy_"):
        try:
            cosmetic_id = int(payload.replace("cosmetic_buy_", ""))
            result = _perform_cosmetic_buy(message.from_user.id, message.from_user.first_name, cosmetic_id)
            if result["status"] == "need_stars":
                # 💳 Birinchi taklif — admin bilan bog'lanib karta orqali to'lash,
                # ostida esa ⭐️ Stars orqali to'lash imkoniyati (invoys) chiqadi.
                card_kb = types.InlineKeyboardMarkup()
                card_kb.add(card_payment_button())
                bot.send_message(
                    message.chat.id,
                    "💳 Karta orqali to'lashni xohlasangiz, quyidagi tugma orqali admin bilan bog'laning:",
                    reply_markup=card_kb,
                )
                bot.send_invoice(
                    message.chat.id,
                    title=f"{result['emoji']} {result['name']}",
                    description="Hunter Mafia — limitli kosmetika buyumi",
                    invoice_payload=f"cosmetic_{cosmetic_id}",
                    provider_token="",  # ⭐️ Stars uchun bo'sh qoldiriladi
                    currency="XTR",
                    prices=[types.LabeledPrice(label=result["name"], amount=result["price"])],
                )
            else:
                bot.send_message(message.chat.id, result["msg"], reply_markup=with_back_button())
        except Exception as e:
            _logger.warning("cosmetic_buy deep-link xatolik: %s", e)
            bot.send_message(message.chat.id, "❌ Xarid havolasi noto'g'ri.", reply_markup=with_back_button())
        return

    if _handle_start_payload_v8(message, payload):   # 🧩 v8: Mini App deep-link'lari
        return

    if payload == "clan_create_info":
        bot.send_message(
            message.chat.id,
            "🏛 <b>Klan yaratish</b>\n\n"
            "Avval 🏛 Klan litsenziyasini Hunter Coin do'konidan sotib oling, so'ng:\n"
            "<code>/klan Klan_nomi</code>\n\ndeb yozing.",
            reply_markup=with_back_button(),
        )
        return

    if not has_chosen_lang(message.from_user.id):
        show_first_time_lang_menu(message.chat.id, message.from_user.id)
        return

    # 🎬 v10: YANGI foydalanuvchi uchun — bosh menyudan OLDIN qisqa "kirish sahnasi"
    # (faqat 1 marta, faqat chin yangi hisob uchun — is_new_user tepada aniqlangan).
    if is_new_user:
        _send_onboarding_intro(message.chat.id, message.from_user.first_name)

    caption = (
        f"{T(message.from_user.id, 'welcome_title').format(name=esc(message.from_user.first_name))}\n\n"
        f"{T(message.from_user.id, 'welcome_body')}"
    )
    bot.send_photo(message.chat.id, MAIN_PHOTO, caption=caption, reply_markup=get_main_menu(None, message.from_user.id))

    # 🧠 Theron — bot egasi shaxsiy chatga kirganda, mehnatkash yordamchi sifatida
    # alohida (fon rejimida, asosiy /start javobini KECHIKTIRMASDAN) salomlashadi.
    if is_owner(message.from_user.id) and theron_available():
        def _owner_greet():
            try:
                greeting = theron_owner_greeting()
                if greeting:
                    bot.send_message(message.chat.id, f"🧠 <b>{THERON_NAME}:</b> {greeting}")
            except Exception as e:
                _logger.warning("Theron owner greeting xatolik: %s", e)
        threading.Thread(target=_owner_greet, daemon=True).start()


# ================================================================================
#  🐺🦅 JAMOAVIY O'YIN (/new_team) va 💍 PARA O'YIN (/new_para) — 2026 YANGI VERSIYA
#
#  🔧 TUZATILDI (katta o'zgarish): bu ikkala rejim ENDI alohida, soddalashtirilgan
#  ("faqat kim kimni tunda otadi" darajasidagi) tizim EMAS. Ular asosiy Hunter
#  Mafia o'yin dvigeniga (GAMES lug'ati, 28 TA ROL, assign_roles, start_night/
#  cb_night_action/resolve_night, start_day/open_day_voting/cb_vote/resolve_day,
#  osish-tasdiqlash bosqichi, end_game) to'g'ridan-to'g'ri ULANADI. Bu degani:
#
#    • Rollar — asosiy o'yindagi 35 ta rol xuddi shunday, tasodifiy taqsimlanadi.
#    • Har bir rol tunda xuddi asosiy o'yindagidek harakat qiladi (Don/Mafia
#      birga qurbon tanlaydi, Doktor davolaydi, Komissar tekshiradi va h.k.).
#    • Ovoz berish — HECH QANDAY ochiq/guruh ichidagi tugma yo'q. Hammasi
#      asosiy o'yindagi kabi botning shaxsiy chatida (DM) o'tadi.
#    • Yagona farq — QO'SHILISH tartibi va G'ALABA sharti:
#        🐺🦅 Jamoaviy: qo'shilishda 🐺 yoki 🦅 jamoa tanlanadi (kim qaysi
#          jamoada ekani oxirigacha MAXFIY). Bitta jamoaning BARCHA a'zosi
#          halok bo'lguncha o'yin davom etadi — tirik qolgan jamoa g'olib.
#        💍 Para: FAQAT botda rasmiy nikohdagi (/para) juftliklar qo'shiladi.
#          Juftlikning bir a'zosi (tunda yoki kunduzi) halok bo'lsa, ikkinchisi
#          ham DARHOL o'yindan chiqadi ('bog'langan taqdir'). Oxirgi BITTA
#          juftlik tirik qolguncha o'yin davom etadi — o'sha juftlik g'olib.
#    • Mukofot tizimi — g'alaba/mag'lubiyat puli, ball, faollik reytingi —
#      hammasi asosiy o'yin bilan 100% bir xil (end_game funksiyasi orqali).
#
#  Bularning barchasi allaqachon GAMES ichidagi squad_mode/couple_mode
#  maydonlari orqali to'liq ishlab turadi (join, assign_roles, night/day,
#  check_and_end_game, end_game — barchasi shu maydonlarni hisobga oladi).
#  Pastdagi kod shunchaki o'sha mexanizmni /new_team, /new_para va h.k.
#  qulay, alohida buyruqlar orqali ochib beradi.
# ================================================================================

def _special_mode_flag(mode):
    return "squad_mode" if mode == "squad" else "couple_mode"


def _special_mode_label(mode):
    return "🐺🦅 Jamoaviy o'yin" if mode == "squad" else "💍 Para o'yin"


def _open_special_lobby(message, mode):
    """💍/🐺🦅 FAQAT admin/owner — /new_team yoki /new_para: shu guruhda
    tegishli rejim (squad_mode/couple_mode) yoqilgan holda YANGI o'yin
    ro'yxatga olishni ochadi (asosiy /newgame bilan bir xil pipeline,
    faqat rejim majburiy yoqilgan bo'ladi)."""
    global BOT_USERNAME
    try:
        maybe_capture_owner(message.from_user)
        if BOT_USERNAME is None:
            try:
                BOT_USERNAME = bot.get_me().username
            except Exception:
                pass
        safe_delete(message)
        if message.chat.type not in ("group", "supergroup"):
            bot.send_message(message.chat.id, f"{_special_mode_label(mode)} bu buyruq faqat guruhda ishlaydi.")
            return
        if not is_authorized(message):
            bot.send_message(message.chat.id, "⛔ Siz admin emassiz.")
            return

        chat_id = message.chat.id
        add_known_group(chat_id, message.chat.title or "Nomsiz guruh")

        with GAME_LOCK:
            old = GAMES.get(chat_id)
            if old and old.get("join_msg_id"):
                _close_join_message(chat_id, old["join_msg_id"])

            game = new_game(chat_id, message.chat.title)
            game[_special_mode_flag(mode)] = True
            GAMES[chat_id] = game
            try:
                game["group_link"] = bot.export_chat_invite_link(chat_id)
            except Exception:
                pass

            kb = build_join_markup(chat_id, game)
            sent = bot.send_message(
                chat_id,
                f"{_special_mode_label(mode)} boshlandi!\n\n{build_join_text(game)}",
                reply_markup=kb,
            )
            game["join_msg_id"] = sent.message_id
            try:
                bot.pin_chat_message(chat_id, sent.message_id, disable_notification=True)
            except Exception:
                pass
            save_games_state()
    except Exception as e:
        _logger.warning("_open_special_lobby(%s) xatolik: %s", mode, e)
        try:
            bot.send_message(message.chat.id, "⚠️ O'yinni boshlashda xatolik yuz berdi. Qaytadan urinib ko'ring.")
        except Exception:
            pass


def _povtor_special_lobby(message, mode):
    """🔁 FAQAT admin/owner — ro'yxat xabari yo'qolib qolsa, qayta yuboradi.
    Yozilgan a'zolar hech qayerga yo'qolmaydi — faqat xabar yangidan chiqadi."""
    try:
        maybe_capture_owner(message.from_user)
        safe_delete(message)
        if message.chat.type not in ("group", "supergroup"):
            bot.send_message(message.chat.id, f"{_special_mode_label(mode)} bu buyruq faqat guruhda ishlaydi.")
            return
        if not is_authorized(message):
            bot.send_message(message.chat.id, "⛔ Siz admin emassiz.")
            return

        chat_id = message.chat.id
        game = GAMES.get(chat_id)
        flag = _special_mode_flag(mode)
        if not game or game.get("phase") != "waiting" or not game.get(flag):
            bot.send_message(
                message.chat.id,
                f"❌ Hozir {_special_mode_label(mode)} ro'yxatga olish bosqichida emas. Avval tegishli /new_... buyrug'i bilan oching.",
            )
            return
        if game.get("join_msg_id"):
            _close_join_message(chat_id, game["join_msg_id"])
        sent = bot.send_message(chat_id, build_join_text(game), reply_markup=build_join_markup(chat_id, game))
        game["join_msg_id"] = sent.message_id
        try:
            bot.pin_chat_message(chat_id, sent.message_id, disable_notification=True)
        except Exception:
            pass
    except Exception as e:
        _logger.warning("_povtor_special_lobby(%s) xatolik: %s", mode, e)
        try:
            bot.send_message(message.chat.id, "⚠️ Xabarni qayta yuborishda xatolik yuz berdi.")
        except Exception:
            pass


def _start_special_game(message, mode):
    """▶️ FAQAT admin/owner — ro'yxatni yopadi, rollarni (28 tadan) taqsimlaydi
    va birinchi tunni boshlaydi (xuddi asosiy /startgame kabi — chunki aynan
    o'sha funksiyaga o'tkaziladi)."""
    try:
        maybe_capture_owner(message.from_user)
        if message.chat.type not in ("group", "supergroup"):
            return
        if not is_authorized(message):
            safe_delete(message)
            bot.send_message(message.chat.id, "⛔ Siz admin emassiz.")
            return

        chat_id = message.chat.id
        game = GAMES.get(chat_id)
        flag = _special_mode_flag(mode)
        if not game or game.get("phase") != "waiting" or not game.get(flag):
            safe_delete(message)
            bot.send_message(message.chat.id, f"❌ Hozir faol {_special_mode_label(mode)} ro'yxati yo'q.")
            return

        if mode == "squad":
            wolf_n = sum(1 for uid in game["players"] if game["squads"].get(uid) == "wolf")
            eagle_n = sum(1 for uid in game["players"] if game["squads"].get(uid) == "eagle")
            if wolf_n < 1 or eagle_n < 1:
                safe_delete(message)
                bot.send_message(chat_id, "❌ Har ikki jamoada (🐺 va 🦅) kamida bittadan a'zo bo'lishi kerak.")
                return
        else:
            paired_n = sum(1 for uid in game["players"] if get_partner_id(uid) in game["players"])
            if paired_n < 2:
                safe_delete(message)
                bot.send_message(chat_id, "❌ Kamida bitta to'liq juftlik (ikkalasi ham ro'yxatda) kerak.")
                return

        # 🎮 Asosiy o'yin bilan bir xil pipeline: rol taqsimlash + tun boshlash
        cmd_startgame(message)
    except Exception as e:
        _logger.warning("_start_special_game(%s) xatolik: %s", mode, e)
        try:
            bot.send_message(message.chat.id, "⚠️ O'yinni boshlashda xatolik yuz berdi.")
        except Exception:
            pass


def _stop_special_game(message, mode):
    """🛑 FAQAT admin/owner — mos rejimdagi faol o'yinni istalgan bosqichda
    (ro'yxat, tun, kun) darhol butunlay bekor qiladi."""
    try:
        maybe_capture_owner(message.from_user)
        safe_delete(message)
        if not is_authorized(message):
            bot.send_message(message.chat.id, "⛔ Siz admin emassiz.")
            return
        chat_id = message.chat.id
        flag = _special_mode_flag(mode)
        game = GAMES.get(chat_id)
        if game and game.get(flag):
            del GAMES[chat_id]
            save_games_state()
            bot.send_message(message.chat.id, f"🛑 {_special_mode_label(mode)} admin tomonidan to'xtatildi.")
        else:
            bot.send_message(message.chat.id, f"Hozir faol {_special_mode_label(mode)} yo'q.")
    except Exception as e:
        _logger.warning("_stop_special_game(%s) xatolik: %s", mode, e)


@bot.message_handler(commands=["vsgame"])
def cmd_vsgame(message):
    """🐺🦅 Jamoaviy (Team) o'yin — ochiq bo'lmasa yangisini ochadi, ochiq bo'lsa
    (hali /start berilmagan bo'lsa) o'sha ro'yxatni qayta yuboradi."""
    chat_id = message.chat.id
    game = GAMES.get(chat_id)
    if game and game.get("phase") == "waiting" and game.get("squad_mode"):
        _povtor_special_lobby(message, "squad")
    else:
        _open_special_lobby(message, "squad")


@bot.message_handler(commands=["pgame"])
def cmd_pgame(message):
    """💍 Para (Couple) o'yin — ochiq bo'lmasa yangisini ochadi, ochiq bo'lsa
    (hali /start berilmagan bo'lsa) o'sha ro'yxatni qayta yuboradi."""
    chat_id = message.chat.id
    game = GAMES.get(chat_id)
    if game and game.get("phase") == "waiting" and game.get("couple_mode"):
        _povtor_special_lobby(message, "couple")
    else:
        _open_special_lobby(message, "couple")


