@bot.message_handler(commands=["taqdir", "fortune", "gildirak", "sandiq", "kunliksandiq"])
def cmd_taqdir(message):
    """🎁 KUNLIK SANDIQ (avvalgi nomi: Taqdir G'ildiragi) — kuniga 1 marta
    ochiladigan, animatsiyali bepul sandiq. 7 xil natija bor (jumladan kam
    ehtimolli 👑 JACKPOT). Bepul va barcha foydalanuvchilar uchun ochiq.
    🔧 Endi bu yerdan HECH QACHON bepul Coin chiqmaydi, 💎 Olmos chiqish
    ehtimoli esa 5% dan past."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    user_dict(uid, message.from_user.first_name)
    today = time.strftime("%Y-%m-%d")
    key = f"taqdir_date_{uid}"
    if get_setting(key) == today:
        bot.send_message(message.chat.id, "⏳ Siz bugungi Kunlik Sandiqni allaqachon ochgansiz. Ertaga qayting!")
        return
    set_setting(key, today)

    # 🎡 Animatsiyali "ochilish" effekti — bir necha marta xabarni tahrirlab, taassurot yaratamiz
    spin_frames = ["🎁 🔒➜🔒", "🎁 🔒➜🔓", "🎁 🔓➜✨", "🎁 ✨➜🎉"]
    sent = bot.send_message(message.chat.id, f"🎁 <b>Kunlik Sandiq ochilmoqda...</b>\n{spin_frames[0]}")
    for frame in spin_frames[1:]:
        time.sleep(0.35)
        try:
            bot.edit_message_text(f"🎁 <b>Kunlik Sandiq ochilmoqda...</b>\n{frame}", message.chat.id, sent.message_id)
        except Exception:
            pass
    time.sleep(0.35)

    weights = [w for w, *_ in TAQDIR_PRIZES]
    _, ptype, amount, label = random.choices(TAQDIR_PRIZES, weights=weights, k=1)[0]
    mult = luck_mult(uid)

    if ptype == "jackpot":
        # 🔧 TUZATILDI: Coin mukofoti olib tashlandi (endi faqat 💵 + 💎)
        j_dollar, j_diamond = int(200 * mult), 5
        add_balance(uid, dollar=j_dollar, diamond=j_diamond)
        result_text = (
            f"👑 <b>JACKPOT!!!</b> 👑\n"
            f"Naqadar omad! Siz olib qoldingiz:\n"
            f"💵 +{j_dollar}$  💎 +{j_diamond}"
        )
    else:
        amount = int(amount * mult) if ptype == "dollar" else amount
        add_balance(uid, **{ptype: amount})
        unit = {"dollar": "$", "diamond": "💎"}[ptype]
        result_text = f"{label}\n\nSiz yutdingiz: <b>+{amount}{unit}</b>"

    try:
        bot.edit_message_text(f"🎁 <b>Kunlik Sandiq ochildi!</b>\n\n{result_text}\n\n⏳ Ertaga yana urinib ko'ring!", message.chat.id, sent.message_id)
    except Exception:
        bot.send_message(message.chat.id, f"🎁 {result_text}")


