# ================================================================================
#  ⚙️ v8 — HAR BIR GURUH UCHUN ALOHIDA SOZLAMALAR (/settings)
# ================================================================================
# Guruh adminlari (va bot egasi) guruhning o'zida /settings yozib, tugmali menyu
# orqali shu guruhga xos qoidalarni o'zgartiradi. Sozlamalar `group_settings`
# jadvalida saqlanadi (bot qayta ishga tushsa ham yo'qolmaydi). Standart qiymatlar
# avvalgi (v7) xatti-harakatning AYNAN o'zi — ya'ni mavjud guruhlarda, admin
# hech narsani o'zgartirmaguncha, hech narsa o'zgarmaydi.
#
# Mavjud eski /setting va /mode buyruqlari ham shu menyuni ochadi; Jamoaviy va
# Para rejimlari (faqat bot egasiga tegishli) menyuda faqat ega uchun ko'rinadi.

with db_lock:
    cur.execute(
        "CREATE TABLE IF NOT EXISTS group_settings ("
        "chat_id INTEGER NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, "
        "PRIMARY KEY (chat_id, key))"
    )
    conn.commit()

GS_DEFS = [
    {"key": "speed", "title": "⏱ O'yin tezligi", "default": "normal",
     "choices": [("normal", "Oddiy"), ("fast", "⚡ Tez"), ("slow", "🐢 Sekin")]},
    {"key": "min_players", "title": "👥 Minimal o'yinchi", "default": "auto",
     "choices": [("auto", "Standart"), ("3", "3 ta"), ("4", "4 ta"), ("5", "5 ta"),
                 ("6", "6 ta"), ("8", "8 ta"), ("10", "10 ta")]},
    {"key": "who_starts", "title": "🚀 O'yinni kim boshlaydi", "default": "admins",
     "choices": [("admins", "👑 Faqat adminlar"), ("all", "👥 Har bir ishtirokchi")]},
    {"key": "night_chat", "title": "🌙 Tunda guruh chati", "default": "closed",
     "choices": [("closed", "🔒 Yopiq"), ("open", "🔓 Ochiq")]},
    {"key": "elite_chat", "title": "👑 Elite a'zolar yozishi", "default": "1",
     "choices": [("1", "✅ Yoqilgan"), ("0", "❌ O'chirilgan")]},
    {"key": "dead_chat", "title": "💀 O'lganlar (kunduzi)", "default": "open",
     "choices": [("open", "✅ Yoza oladi"), ("closed", "❌ Jim turadi")]},
    {"key": "confirm_vote", "title": "🗳 Osishni tasdiqlash (👍/👎)", "default": "1",
     "choices": [("1", "✅ Yoqilgan"), ("0", "❌ O'chirilgan")]},
    {"key": "afk_nights", "title": "😴 AFK limiti", "default": "2",
     "choices": [("1", "1 tun"), ("2", "2 tun"), ("3", "3 tun"), ("4", "4 tun")]},
    {"key": "scene_photo", "title": "🖼 Tun/kun rasmlari", "default": "1",
     "choices": [("1", "✅ Yoqilgan"), ("0", "❌ O'chirilgan")]},
    {"key": "vote_public", "title": "🗳 Ovoz berish (kim kimga)", "default": "1",
     "choices": [("1", "✅ Ochiq"), ("0", "❌ Yashirin")]},
    {"key": "world_events", "title": "🎲 Tasodifiy Hunter World voqealari", "default": "1",
     "choices": [("1", "✅ Yoqilgan"), ("0", "❌ O'chirilgan")]},
]
GS_BY_KEY = {d["key"]: d for d in GS_DEFS}

# ⏱ Tezlik andozalari (soniya). "normal" — botning global sozlamalari (bot egasi
# o'zgartirgan qiymatlar ham shu yerda ishlaydi).
GS_SPEED_PRESETS = {
    "fast": {"night": 30, "discuss": 15, "vote": 20, "confirm": 15},
    "slow": {"night": 60, "discuss": 40, "vote": 40, "confirm": 30},
}

_GS_CACHE = {}
_GS_LOCK = threading.RLock()


def _gs_row(chat_id):
    with _GS_LOCK:
        row = _GS_CACHE.get(chat_id)
        if row is None:
            row = {}
            try:
                with db_lock:
                    cur.execute("SELECT key, value FROM group_settings WHERE chat_id=?", (chat_id,))
                    for k, v in cur.fetchall():
                        row[k] = v
            except Exception:
                row = {}
            _GS_CACHE[chat_id] = row
        return row


def gs_get(chat_id, key):
    """Guruhning bitta sozlamasi (yaroqsiz/yo'q bo'lsa — standart qiymat)."""
    d = GS_BY_KEY.get(key)
    if d is None:
        return None
    val = _gs_row(chat_id).get(key, d["default"])
    if val not in [c[0] for c in d["choices"]]:
        return d["default"]
    return val


def gs_set(chat_id, key, value):
    d = GS_BY_KEY.get(key)
    if d is None or str(value) not in [c[0] for c in d["choices"]]:
        return False
    with _GS_LOCK:
        with db_lock:
            cur.execute("INSERT OR REPLACE INTO group_settings (chat_id, key, value) VALUES (?,?,?)",
                        (chat_id, key, str(value)))
            conn.commit()
        _gs_row(chat_id)[key] = str(value)
    return True


def gs_cycle(chat_id, key):
    """Sozlamani keyingi qiymatga o'tkazadi va yangi qiymatni qaytaradi."""
    d = GS_BY_KEY.get(key)
    if d is None:
        return None
    values = [c[0] for c in d["choices"]]
    cur_v = gs_get(chat_id, key)
    nxt = values[(values.index(cur_v) + 1) % len(values)]
    gs_set(chat_id, key, nxt)
    return nxt


def gs_reset(chat_id):
    with _GS_LOCK:
        with db_lock:
            cur.execute("DELETE FROM group_settings WHERE chat_id=?", (chat_id,))
            conn.commit()
        _GS_CACHE[chat_id] = {}


def gsv(game_or_chat, key):
    """Sozlamani o'yin (dict) yoki chat_id (int) bo'yicha o'qiydi."""
    if isinstance(game_or_chat, dict):
        chat_id = game_or_chat.get("chat_id")
    else:
        chat_id = game_or_chat
    if chat_id is None:
        d = GS_BY_KEY.get(key)
        return d["default"] if d else None
    return gs_get(chat_id, key)


def game_times(game_or_chat):
    """Shu guruhning tun / muhokama / ovoz berish / tasdiqlash vaqtlari (soniya)."""
    preset = GS_SPEED_PRESETS.get(gsv(game_or_chat, "speed"))
    if preset:
        return dict(preset)
    return {"night": NIGHT_SECONDS, "discuss": DAY_DISCUSSION_SECONDS,
            "vote": DAY_VOTE_SECONDS, "confirm": CONFIRM_VOTE_SECONDS}


def game_min_players(game_or_chat):
    v = gsv(game_or_chat, "min_players")
    return MIN_PLAYERS if v == "auto" else int(v)


def game_afk_limit(game_or_chat):
    try:
        return max(1, int(gsv(game_or_chat, "afk_nights")))
    except Exception:
        return 2


def _gs_panel(chat_id, title, owner_view=False):
    lines = [
        f"⚙️ <b>{esc(title)} — guruh sozlamalari</b>",
        "",
        "Tugmani bossangiz, qiymat keyingisiga o'tadi. O'zgarish shu guruhning "
        "keyingi bosqichlaridan boshlab kuchga kiradi.",
    ]
    kb = types.InlineKeyboardMarkup(row_width=1)
    for d in GS_DEFS:
        cur_v = gs_get(chat_id, d["key"])
        label = next((l for v, l in d["choices"] if v == cur_v), cur_v)
        if d["key"] == "min_players" and cur_v == "auto":
            label = f"Standart ({MIN_PLAYERS})"
        kb.add(types.InlineKeyboardButton(f"{d['title']}: {label}", callback_data=f"gs|{chat_id}|{d['key']}"))
    if owner_view:
        squad_on = get_setting(f"squad_mode_{chat_id}") == "1"
        couple_on = get_setting(f"couple_mode_{chat_id}") == "1"
        off_txt = "❌ O'chirilgan"
        kb.add(types.InlineKeyboardButton(
            f"🐺🦅 Jamoaviy o'yin: {'✅ Yoqilgan' if squad_on else off_txt}",
            callback_data=f"ownersetting|squad|{chat_id}"))
        kb.add(types.InlineKeyboardButton(
            f"💍 Para o'yin: {'✅ Yoqilgan' if couple_on else off_txt}",
            callback_data=f"ownersetting|couple|{chat_id}"))
    kb.row(
        types.InlineKeyboardButton("♻️ Standart holatga", callback_data=f"gs|{chat_id}|reset"),
        types.InlineKeyboardButton("❌ Yopish", callback_data=f"gs|{chat_id}|close"),
    )
    return "\n".join(lines), kb


@bot.message_handler(commands=["setting", "mode", "settings", "sozlamalar"])
def cmd_setting_mode(message):
    """⚙️ Guruh sozlamalari paneli: guruh adminlari va bot egasi uchun. Jamoaviy va Para
    rejimlari tugmalari (eski /setting'dagidek) FAQAT bot egasiga ko'rinadi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if message.chat.type not in ("group", "supergroup"):
        bot.send_message(
            message.chat.id,
            "⚙️ <code>/settings</code> ni sozlamoqchi bo'lgan guruhingizda yozing — "
            "o'sha guruh uchun sozlamalar paneli ochiladi.",
        )
        return
    if not is_authorized(message):
        bot.send_message(message.chat.id, "⛔ Guruh sozlamalarini faqat guruh adminlari o'zgartira oladi.")
        return
    text, kb = _gs_panel(message.chat.id, message.chat.title or "Bu guruh",
                         owner_view=is_owner(message.from_user.id))
    bot.send_message(message.chat.id, text, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("gs|"))
def cb_group_setting(call):
    maybe_capture_owner(call.from_user)
    try:
        _, chat_id_s, key = call.data.split("|", 2)
        chat_id = int(chat_id_s)
    except Exception:
        bot.answer_callback_query(call.id)
        return
    uid = call.from_user.id
    if call.message is None or call.message.chat.id != chat_id:
        bot.answer_callback_query(call.id, "Bu menyu eskirgan.", show_alert=True)
        return
    if not (is_owner(uid) or is_group_admin(chat_id, uid)):
        bot.answer_callback_query(call.id, "⛔ Faqat guruh adminlari uchun.", show_alert=True)
        return
    note = "✅ Yangilandi!"
    if key == "close":
        try:
            bot.delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if key == "reset":
        gs_reset(chat_id)
        note = "♻️ Standart holatga qaytarildi."
    elif key in GS_BY_KEY:
        gs_cycle(chat_id, key)
    else:
        bot.answer_callback_query(call.id)
        return
    text, kb = _gs_panel(chat_id, call.message.chat.title or "Bu guruh", owner_view=is_owner(uid))
    try:
        bot.edit_message_text(text, chat_id, call.message.message_id, reply_markup=kb)
    except Exception:
        pass
    bot.answer_callback_query(call.id, note)


@bot.callback_query_handler(func=lambda c: c.data.startswith("ownersetting|"))
def cb_owner_setting_toggle(call):
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Faqat bot egasi uchun.", show_alert=True)
        return
    _, which, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    key = f"squad_mode_{chat_id}" if which == "squad" else f"couple_mode_{chat_id}"
    new_val = not (get_setting(key) == "1")
    set_setting(key, "1" if new_val else "0")
    text, kb = _gs_panel(chat_id, call.message.chat.title or "Bu guruh", owner_view=True)
    try:
        bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
    except Exception:
        pass
    bot.answer_callback_query(call.id, "✅ Yangilandi!")


def do_join(chat_id, tg_user, squad=None, via_couple=False):
    """O'yinga qo'shilishga urinadi va holatni qaytaradi:
    'ok' — muvaffaqiyatli qo'shildi, 'already' — allaqachon qo'shilgan,
    'banned' — bloklangan, 'no_game' — hozir qo'shilsa bo'ladigan o'yin yo'q,
    'other_game' — foydalanuvchi boshqa guruhdagi faol o'yinda allaqachon
    ishtirokchi (bir vaqtda faqat 1 guruhda o'ynash mumkin),
    'need_squad' — 🐺🦅 Jamoaviy rejimda oddiy tugma orqali qo'shilishga urinildi
    (aniq 🐺/🦅 tanlash SHART), 'need_couple' — 💍 Para rejimida oddiy tugma
    orqali qo'shilishga urinildi (FAQAT 💍 tugmasi orqali, juftlik bilan
    qo'shilish SHART — bu rejimda yakka o'yinchi bo'lishi mumkin emas, aks
    holda 'juftlik oxirigacha qolsa g'olib' qoidasi buzilib qoladi).
    squad — agar berilsa ('wolf' yoki 'eagle'), 🐺🦅 jamoaviy rejimda o'yinchi
    shu jamoaga yoziladi (faqat game['squad_mode'] yoqilgan bo'lsa)."""
    game = GAMES.get(chat_id)
    if not game or game["phase"] != "waiting":
        return "no_game"
    if game.get("squad_mode") and squad not in ("wolf", "eagle"):
        return "need_squad"
    if game.get("couple_mode") and not via_couple:
        return "need_couple"
    uid = tg_user.id
    # 🔁 O'ZGARTIRILDI: avval bir vaqtning o'zida faqat BITTA guruhda o'ynash
    # mumkin edi — boshqa guruhdagi faol o'yinda ishtirokchi bo'lgan odam bu
    # yerga qo'shila olmas, "allaqachon boshqa guruhdagi o'yindasiz" taqig'i
    # chiqardi. Endi bu taqiq OLIB TASHLANDI: agar odam boshqa guruhdagi
    # o'yinda (lobbyda yoki allaqachon boshlangan o'yinda) bo'lsa, u yerdan
    # jimgina chiqarilib, shu guruhdagi o'yinga o'tkaziladi (guruh almashadi).
    _leave_other_group_games(uid, chat_id)
    name = tg_user.first_name or "O'yinchi"
    user_dict(uid, name)
    track_group_member(chat_id, uid)  # 👥 shu guruhda faol deb belgilaymiz (top-reyting uchun)
    if is_banned(uid):
        return "banned"
    already = uid in game["players"]
    if not already:
        game["players"][uid] = {"name": name, "role": None, "alive": True, "team": None}
    if squad in ("wolf", "eagle") and game.get("squad_mode"):
        game["squads"][uid] = squad
    if not already:
        _apply_role_ticket_on_join(uid, chat_id)   # 🎭 v8: sotib olingan rol chiptasi bo'lsa, shu o'yinga bog'lanadi
    if game.get("join_msg_id"):
        try:
            bot.edit_message_text(build_join_text(game), chat_id, game["join_msg_id"], reply_markup=build_join_markup(chat_id, game))
        except Exception:
            pass
    return "already" if already else "ok"


def _leave_other_group_games(uid, current_chat_id):
    """🔁 Foydalanuvchi boshqa guruh(lar)dagi o'yin(lar)da ishtirokchi bo'lsa,
    undan jimgina chiqarib tashlaydi — bir vaqtda bir nechta guruhda
    "qolib ketmasligi" uchun, lekin ENDI taqiq yo'q: shunchaki guruh
    almashtiriladi. Hali lobbyda (waiting) bo'lsa — jarimasiz olib tashlanadi.
    O'yin allaqachon boshlangan bo'lsa — /tark_et bilan bir xil mantiqda
    (o'lik deb belgilanadi, o'lim effektlari va g'alaba tekshiruvi ishga
    tushadi), lekin -10 ball JARIMASI QO'LLANILMAYDI (bu haqiqiy tark etish
    emas, shunchaki guruh o'zgartirish)."""
    for other_chat_id, other_game in list(GAMES.items()):
        if other_chat_id == current_chat_id:
            continue
        player = other_game.get("players", {}).get(uid)
        if not player:
            continue
        if other_game.get("phase") == "waiting":
            del other_game["players"][uid]
            other_game.get("squads", {}).pop(uid, None)
            if other_game.get("join_msg_id"):
                try:
                    bot.edit_message_text(
                        build_join_text(other_game), other_chat_id, other_game["join_msg_id"],
                        reply_markup=build_join_markup(other_chat_id, other_game),
                    )
                except Exception:
                    pass
        elif player.get("alive"):
            player["alive"] = False
            player["left_game"] = True
            try:
                handle_death_side_effects(other_game, other_chat_id, uid)
            except Exception:
                pass
            try:
                check_and_end_game(other_chat_id)
            except Exception:
                pass


@bot.callback_query_handler(func=lambda c: c.data.startswith("join|"))
def cb_join(call):
    maybe_capture_owner(call.from_user)
    _, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    status = do_join(chat_id, call.from_user)
    if status == "need_squad":
        bot.answer_callback_query(call.id, "🐺🦅 Bu — Jamoaviy o'yin! 🐺 Wolf yoki 🦅 Eagle tugmasidan birini bosing.", show_alert=True)
    elif status == "need_couple":
        bot.answer_callback_query(call.id, "💍 Bu — Para o'yin! Faqat 💍 tugmasi orqali (turmush o'rtog'ingiz bilan) qo'shilishingiz mumkin.", show_alert=True)
    elif status == "other_game":
        bot.answer_callback_query(call.id, "⛔ Siz allaqachon boshqa guruhdagi faol o'yindasiz — bir vaqtda faqat 1 guruhda o'ynash mumkin.", show_alert=True)
    else:
        bot.answer_callback_query(call.id, f"{call.from_user.first_name} o'yinga qo'shildi!")


@bot.callback_query_handler(func=lambda c: c.data.startswith("squadjoin|"))
def cb_squad_join(call):
    """🐺🦅 Jamoaviy o'yin rejimida — o'yinchi bir tugma bosishi bilan HAM o'yinga
    qo'shiladi, HAM o'zi xohlagan jamoaga (Bo'ri yoki Burgut) yoziladi."""
    maybe_capture_owner(call.from_user)
    _, chat_id_s, squad = call.data.split("|")
    chat_id = int(chat_id_s)
    status = do_join(chat_id, call.from_user, squad=squad)
    squad_label = "🐺 Wolf jamoasi" if squad == "wolf" else "🦅 Eagle jamoasi"
    if status == "banned":
        bot.answer_callback_query(call.id, "⛔ Siz bloklangansiz.", show_alert=True)
    elif status == "no_game":
        bot.answer_callback_query(call.id, "❌ Hozir qo'shilsa bo'ladigan o'yin yo'q.", show_alert=True)
    elif status == "other_game":
        bot.answer_callback_query(call.id, "⛔ Siz allaqachon boshqa guruhdagi faol o'yindasiz — bir vaqtda faqat 1 guruhda o'ynash mumkin.", show_alert=True)
    else:
        bot.answer_callback_query(call.id, f"✅ {squad_label}ga qo'shildingiz!")


@bot.callback_query_handler(func=lambda c: c.data.startswith("couplejoin|"))
def cb_couple_join(call):
    """💍 Para o'yin rejimida — turmush qurgan foydalanuvchi BITTA tugma bosib,
    o'zini VA turmush o'rtog'ini birgalikda o'yinga qo'shadi. Turmush QURMAGAN
    foydalanuvchi bu rejimga umuman qo'shila OLMAYDI (FAQAT rasmiy nikohdagi
    juftliklar — aks holda 'oxirgi juftlik g'olib' qoidasi ishonchli
    ishlamay qolardi)."""
    maybe_capture_owner(call.from_user)
    _, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    game = GAMES.get(chat_id)
    if not game or game["phase"] != "waiting":
        bot.answer_callback_query(call.id, "❌ Hozir qo'shilsa bo'ladigan o'yin yo'q.", show_alert=True)
        return

    uid = call.from_user.id
    if is_banned(uid):
        bot.answer_callback_query(call.id, "⛔ Siz bloklangansiz.", show_alert=True)
        return

    # 🔧 XATOLIK TUZATILDI: avval turmush qurmagan foydalanuvchi ham shu
    # tugma orqali "yakka" qo'shilib ketaverar edi — bu Para rejimida
    # juftliksiz o'yinchi paydo bo'lishiga (va g'alaba qoidasi buzilishiga)
    # sabab bo'lardi. Endi nikohsiz odam bu rejimga umuman qo'shilolmaydi.
    u = user_dict(uid, call.from_user.first_name)
    spouse_id = u.get("married_to")
    if not spouse_id:
        bot.answer_callback_query(call.id, "❌ Bu — Para o'yin, FAQAT rasmiy nikohdagi juftliklar qo'shila oladi. Avval /para orqali oila quring.", show_alert=True)
        return

    status = do_join(chat_id, call.from_user, via_couple=True)
    if status == "banned":
        bot.answer_callback_query(call.id, "⛔ Siz bloklangansiz.", show_alert=True)
        return
    if status == "other_game":
        bot.answer_callback_query(call.id, "⛔ Siz allaqachon boshqa guruhdagi faol o'yindasiz — bir vaqtda faqat 1 guruhda o'ynash mumkin.", show_alert=True)
        return

    if spouse_id in game["players"]:
        bot.answer_callback_query(call.id, "✅ Siz qo'shildingiz — turmush o'rtog'ingiz allaqachon o'yinda ekan!")
        return

    # 💍 Turmush o'rtog'ini ham shaxsiy chatida bot bilan gaplashgan bo'lsa avtomatik qo'shamiz
    su = user_dict(spouse_id)
    spouse_name = su.get("name") or "Sherigingiz"

    class _FakeUser:
        pass

    fake = _FakeUser()
    fake.id = spouse_id
    fake.first_name = spouse_name
    join_status = do_join(chat_id, fake, via_couple=True)
    if join_status in ("ok", "already"):
        bot.answer_callback_query(call.id, f"💍 Siz va {spouse_name} birgalikda o'yinga qo'shildingiz!")
        safe_send(spouse_id, f"💍 Turmush o'rtog'ingiz sizni <b>{game['chat_title']}</b> guruhidagi Hunter Mafia o'yiniga birga qo'shdi!")
    else:
        bot.answer_callback_query(call.id, "✅ Siz qo'shildingiz. (Turmush o'rtog'ingizni avtomatik qo'shib bo'lmadi — ehtimol u boshqa guruhdagi faol o'yinda.)")


# ================================================================================
#  📋 GURUHGA A'ZOLIK SO'ROVLARI (ZAYAVKALAR) — avtomatik qabul qilish
#  Eslatma: bu faqat guruh havolasi "Administrator tasdig'i talab qilinsin"
#  (request to join) rejimida yaratilgan bo'lsa ishlaydi — aks holda odamlar
#  havola orqali to'g'ridan-to'g'ri kirib ketaveradi va navbat hosil bo'lmaydi.
# ================================================================================

@bot.chat_join_request_handler()
def handle_chat_join_request(update):
    """Guruhga kirish uchun yangi so'rov kelganda navbatga qo'shib boradi."""
    chat_id = update.chat.id
    user = update.from_user
    with JOIN_REQ_LOCK:
        lst = PENDING_JOIN_REQUESTS.setdefault(chat_id, [])
        if not any(r["user_id"] == user.id for r in lst):
            lst.append({
                "user_id": user.id,
                "name": user.first_name or "Foydalanuvchi",
                "username": user.username,
                "ts": time.time(),
            })
    try:
        add_known_group(chat_id, update.chat.title or "Nomsiz guruh")
    except Exception:
        pass


ZAYAFKA_MENU_ACTIONS = {
    "zayafka_soni": "🔢 Nechta so'rov bor",
    "zayafka_qabul": "✅ Qabul qilish",
    "zayafka_rad": "❌ Rad etish",
    "zayafka_hammasi": "📋 Barchasini ko'rish",
}
_ZAYAFKA_ACTION_FUNCS = {}


def _zayafka_menu_kb():
    kb = types.InlineKeyboardMarkup(row_width=2)
    buttons = [types.InlineKeyboardButton(label, callback_data=f"zayafkamenu|{key}") for key, label in ZAYAFKA_MENU_ACTIONS.items()]
