@bot.message_handler(commands=["Sotop", "sotop"])
def cmd_sotop(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_authorized(message):
        bot.send_message(message.chat.id, "⛔ Bu buyruqni faqat guruh admini yoki bot egasi ishlatishi mumkin.")
        return
    chat_id = message.chat.id
    if chat_id in GAMES:
        del GAMES[chat_id]
        save_games_state()
        bot.send_message(chat_id, "🛑 O'yin admin tomonidan to'xtatildi.")
    else:
        bot.send_message(chat_id, "Hozir faol o'yin yo'q.")


# ================================================================================
#  TUNGI BOSQICH
# ================================================================================

def alive_role_holders(game, predicate):
    return [uid for uid, p in game["players"].items() if p["alive"] and predicate(p["role"])]


def _bot_dm_button():
    """qoshimchakod-larda ko'rilgan uslub — guruhdagi xabarlarda botning shaxsiy chatiga
    o'tish uchun havola tugmasi (ovoz berish/tungi harakatlar shu yerda amalga oshiriladi)."""
    global BOT_USERNAME
    if BOT_USERNAME is None:
        try:
            BOT_USERNAME = bot.get_me().username
        except Exception:
            return None
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("🤖 Botga o'tish", url=f"https://t.me/{BOT_USERNAME}"))
    return kb


def _send_night_time_reminder(chat_id, night_no):
    """⏰ Tun tugashiga NIGHT_REMINDER_LEAD_SECONDS soniya qolganda chaqiriladi —
    hali harakat qilmagan (tanlov tugmasi bosilmagan) o'yinchilarga shaxsiy
    chatda eslatma yuboradi, shunda ular tasodifan AFK bo'lib qolmaydi."""
    game = GAMES.get(chat_id)
    if not game or game.get("phase") != "night" or game.get("night_count") != night_no:
        return
    prompted = game.get("prompted_tonight", set())
    responded = game.get("responded_tonight", set())
    for uid in prompted - responded:
        p = game["players"].get(uid)
        if p and p.get("alive"):
            safe_send(uid, f"⏰ Vaqtingiz tugayapti! Tanlov qilish uchun ~{NIGHT_REMINDER_LEAD_SECONDS} soniya qoldi.")


def start_night(chat_id):
    game = GAMES.get(chat_id)
    if not game:
        return

    # 🐺 Tun raqami — Bo'ri kabi "faqat juft tunlarda" ishlaydigan rollar uchun
    game["night_count"] = game.get("night_count", 0) + 1

    # 🏆 Geroy — har tun yangidan qo'lda faollashtiriladigan himoya holatini tozalaymiz
    game["hero_armed_defense"] = set()

    # ============================================================================
    #  🚨 AFK NAZORATI — o'tgan tunda taklif olib, javob bermagan o'yinchilarni
    #  belgilaymiz. 2 tun ketma-ket harakat qilmasa, shu tunda avtomatik chiqariladi.
    # ============================================================================
    prev_prompted = game.get("prompted_tonight", set())
    prev_responded = game.get("responded_tonight", set())
    afk_streak = game.setdefault("afk_streak", {})
    kicked_afk = []
    for uid in prev_prompted:
        p = game["players"].get(uid)
        if not p or not p["alive"]:
            continue
        if uid in prev_responded:
            afk_streak[uid] = 0
        else:
            afk_streak[uid] = afk_streak.get(uid, 0) + 1
            if afk_streak[uid] >= game_afk_limit(game):  # ⚙️ v8: guruh sozlamasi (standart 2)
                p["alive"] = False
                kicked_afk.append(uid)
                afk_streak[uid] = 0
    for uid in kicked_afk:
        p = game["players"][uid]
        p["left_game"] = True  # 🚪 o'yin oxirida avtomatik mag'lub sifatida hisoblanadi
        joke = random.choice(AFK_KICK_JOKES).format(who=mention(uid, p["name"]), role=f"<b>{p['role']}</b>")
        bot.send_message(chat_id, joke)
        safe_send(uid, f"😴 Siz {game_afk_limit(game)} tun ketma-ket harakatsiz qolganingiz uchun o'yindan avtomatik chiqarildingiz.")
        add_points(uid, -10, "afk_kick")
        # 🔧 TUZATILDI: avval bu yerda chaqirilmas edi — natijada AFK bilan
        # chiqarilgan o'yinchining 💍 Para sherigi/👑 Don vorisligi/👻 Arvoh
        # ishlamay qolardi (Para o'yinda "yolg'iz qolgan" xato holatiga sabab bo'lgan edi).
        handle_death_side_effects(game, chat_id, uid)
    if kicked_afk and check_and_end_game(chat_id):
        return

    game["phase"] = "night"
    game["mafia_votes"] = {}
    game["doctor_target"] = None
    game["komissar_action"] = None
    game["komissar_target"] = None
    game["night_announced"] = set()
    game["prompted_tonight"] = set()
    game["responded_tonight"] = set()
    # o'tgan kunning bir martalik grantlari (Advokat himoyasi, Provokator, Sudya)
    # yangi tunda qayta tanlanadi, shuning uchun bu yerda tozalanadi
    game["advocate_protect"] = None
    game["advocate_actor"] = None
    game["forced_day_votes"] = {}
    game["judge_double_vote"] = None

    # 🌙 Tungi atmosfera matnlari — faol (tirik) o'yinchilarning rollariga qarab
    flavor_lines = alive_role_flavor_lines(game)
    flavor_block = ("\n\n" + "\n".join(flavor_lines)) if flavor_lines else ""
    send_scene_photo(
        chat_id, NIGHT_PHOTO_LOCAL, NIGHT_PHOTO,
        caption=f"🌙 <b>{game['day_number']}-tun.</b> Shahar uxlamoqda... Guruhda yozish taqiqlangan.\n"
                "Rolga ega o'yinchilar — botning shaxsiy chatida tanlov kutmoqda. 🤖" + flavor_block,
        reply_markup=_bot_dm_button(),
    )

    # 🐺🦅 Jamoaviy rejimda — tungi harakatlar boshlanishidan OLDIN, har bir
    # o'yinchiga o'z jamodoshlari ro'yxati eslatma qilib yuboriladi.
    send_squad_reminders(game)

    alive = alive_players(game)

    mafia_uids = alive_role_holders(game, lambda r: team_of(r) == "mafia")
    for uid in mafia_uids:
        kb = types.InlineKeyboardMarkup()
        for target_id, p in alive.items():
            if team_of(p["role"]) == "mafia":
                continue
            tag = squad_tag(game, uid, target_id)
            kb.add(types.InlineKeyboardButton(f"{tag}{p['name']}", callback_data=f"na|{chat_id}|mafia|{target_id}"))
        kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|mafia|skip"))
        safe_send(uid, "🔪 <b>Kimni yo'q qilamiz?</b> Sheriklaringiz bilan kelishilgan holda tanlang:", kb)
        game["prompted_tonight"].add(uid)

    kom_uids = alive_role_holders(game, lambda r: r == "Komissar 🕵️‍♂️")
    for uid in kom_uids:
        kb = types.InlineKeyboardMarkup()
        kb.add(
            types.InlineKeyboardButton("🔍 Tekshirish", callback_data=f"na|{chat_id}|komaction|check"),
            types.InlineKeyboardButton("🎯 O'ldirish", callback_data=f"na|{chat_id}|komaction|kill"),
        )
        kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|komaction|skip"))
        safe_send(uid, "🕵️‍♂️ <b>Bu tun nima qilamiz?</b>", kb)
        game["prompted_tonight"].add(uid)

    doc_uids = alive_role_holders(game, lambda r: r == "Doktor 👨‍⚕️")
    for uid in doc_uids:
        kb = types.InlineKeyboardMarkup()
        for target_id, p in alive.items():
            tag = squad_tag(game, uid, target_id)
            kb.add(types.InlineKeyboardButton(f"{tag}{p['name']}", callback_data=f"na|{chat_id}|doctor|{target_id}"))
        kb.add(types.InlineKeyboardButton("🚫 Hech kimni davolamaslik", callback_data=f"na|{chat_id}|doctor|skip"))
        safe_send(uid, "👨‍⚕️ <b>Kimni davolaysiz?</b>", kb)
        game["prompted_tonight"].add(uid)

    # ============================================================================
    #  QO'SHIMCHA 25 ROL — hech biri chetda qolmasin, barchasi tunda o'z
    #  qobiliyatini ishlata oladi (asosiy rollar kabi shaxsiy DM orqali).
    # ============================================================================
    game["extra_actions"] = {}
    komissar_alive = bool(alive_role_holders(game, lambda r: r == "Komissar 🕵️‍♂️"))
    doktor_alive = bool(alive_role_holders(game, lambda r: r == "Doktor 👨‍⚕️"))
    for uid, p in alive.items():
        role = p["role"]
        slug = EXTRA_ROLE_SLUGS.get(role)
        if not slug or slug == "arvoh":
            continue
        if slug == "serjant" and komissar_alive:
            continue  # Serjant faqat Komissar halok bo'lganda faollashadi
        if slug == "hamshira" and doktor_alive:
            continue  # Hamshira faqat Doktor halok bo'lganda faollashadi
        if slug == "snayper" and uid in game.get("snayper_used", set()):
            continue  # Snayper qobiliyati butun o'yin davomida faqat 1 marta ishlaydi
        if slug == "bori" and game.get("night_count", 1) % 2 != 0:
            # 🐺 Bo'ri faqat JUFT tunlarda yirtqichga aylanadi — toq tunda oddiy fuqaro
            safe_send(uid, "🐺 Bu kecha oy to'lmagan — siz oddiy fuqarodek tinch uxlaysiz. (Faqat juft tunlarda yirtqichga aylanasiz.)")
            continue
        if slug == "jurnalist":
            # 🎙 Jurnalist — ODDIY bitta nishon o'rniga IKKITA o'yinchini solishtiradi.
            # Interfeys soddaligi uchun: avval 1-kishini, keyin 2-kishini ketma-ket tanlaydi.
            kb = types.InlineKeyboardMarkup()
            for target_id, tp in alive.items():
                if target_id == uid:
                    continue
                kb.add(types.InlineKeyboardButton(tp["name"], callback_data=f"na|{chat_id}|jrn1|{target_id}"))
            kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|jrn1|skip"))
            safe_send(uid, f"{ROLES_INFO.get(role, '')}\n\n{JOURNALIST_PROMPT}\n\n1️⃣ Birinchi kishini tanlang:", kb)
            game["prompted_tonight"].add(uid)
            continue
        prompt_text, _flavor = EXTRA_ROLE_PROMPTS[slug]
        kb = types.InlineKeyboardMarkup()
        if slug in EXTRA_ROLE_YESNO:
            kb.add(
                types.InlineKeyboardButton("✅ Ha", callback_data=f"na|{chat_id}|ex|{slug}:yes"),
                types.InlineKeyboardButton("🚫 Yo'q", callback_data=f"na|{chat_id}|ex|{slug}:no"),
            )
        else:
            for target_id, tp in alive.items():
                if target_id == uid and slug not in EXTRA_ROLE_SELF_TARGET_OK:
                    continue
                tag = squad_tag(game, uid, target_id)
                kb.add(types.InlineKeyboardButton(f"{tag}{tp['name']}", callback_data=f"na|{chat_id}|ex|{slug}:{target_id}"))
            kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|ex|{slug}:skip"))
        safe_send(uid, f"{ROLES_INFO.get(role, '')}\n\n{prompt_text}", kb)
        game["prompted_tonight"].add(uid)

    # 👻 Arvoh — faqat o'lgandan keyin faollashadi, tirik o'yinchiga sirli imo-ishora beradi
    if alive:
        for uid, p in game["players"].items():
            if p["alive"] or p["role"] != "Arvoh 👻":
                continue
            kb = types.InlineKeyboardMarkup()
            for target_id, tp in alive.items():
                tag = squad_tag(game, uid, target_id)
                kb.add(types.InlineKeyboardButton(f"{tag}{tp['name']}", callback_data=f"na|{chat_id}|ex|arvoh:{target_id}"))
            kb.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|ex|arvoh:skip"))
            safe_send(uid, EXTRA_ROLE_PROMPTS["arvoh"][0], kb)

    # 🏆 Geroy — himoyaga ega (Draven/Zephyrion) o'yinchilarga har tun eslatma + tugma
    for uid, p in alive.items():
        if hero_has_ability(uid, "survive") or hero_has_ability(uid, "revive_once"):
            if hero_auto_enabled(uid):
                # 🤖 v8: Avto-rejim — himoya har tun o'zi faollashadi (tugma bosish shart emas)
                game.setdefault("hero_armed_defense", set()).add(uid)
                continue
            kb = types.InlineKeyboardMarkup()
            kb.add(types.InlineKeyboardButton("🛡 Geroy himoyasini faollashtirish", callback_data=f"heroarm|defense|{chat_id}"))
            safe_send(uid, "🏆 Geroyingiz bu tun himoya taklif qilmoqda. Faollashtirmasangiz, u sizni himoya QILMAYDI:", kb)

    _night_s = game_times(game)["night"]  # ⚙️ v8: guruh tezligi sozlamasi
    t = threading.Timer(_night_s, lambda: resolve_night(chat_id))
    t.daemon = True
    t.start()
    game["timers"].append(t)

    if _night_s > NIGHT_REMINDER_LEAD_SECONDS:
        night_no = game["night_count"]
        rt = threading.Timer(_night_s - NIGHT_REMINDER_LEAD_SECONDS,
                              lambda: _send_night_time_reminder(chat_id, night_no))
        rt.daemon = True
        rt.start()
        game["timers"].append(rt)

    # 🔄 checkpoint — bot qayta ishga tushsa, shu tundan qolgan vaqtni hisoblab davom etadi
    game["day_sub_phase"] = None
    game["phase_deadline"] = time.time() + _night_s
    save_games_state()


@bot.callback_query_handler(func=lambda c: c.data.startswith("na|"))
def cb_night_action(call):
    maybe_capture_owner(call.from_user)
    parts = call.data.split("|")
    chat_id = int(parts[1])
    kind, value = parts[2], parts[3]
    game = GAMES.get(chat_id)
    uid = call.from_user.id

    if not game or game["phase"] != "night" or uid not in game["players"] or not game["players"][uid]["alive"]:
        bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
        return

    # 🚨 AFK nazorati — foydalanuvchi shu tunda javob berdi, streak nolga tushadi
    game.setdefault("responded_tonight", set()).add(uid)
    # 🏅 Faollik balli — har bir tungi harakat uchun +1 (o'yin oxirida eng faol o'yinchi aniqlanadi)
    game.setdefault("activity_score", {})
    game["activity_score"][uid] = game["activity_score"].get(uid, 0) + 1

    if kind == "mafia":
        target = value if value == "skip" else int(value)
        game["mafia_votes"][uid] = target
        if "mafia" not in game["night_announced"]:
            game["night_announced"].add("mafia")
            bot.send_message(chat_id, "🕶 <i>Mafiya soyada birlashib, o'ljasini muhokama qilmoqda...</i>")
        try:
            bot.edit_message_text("✅ Tanlandi! Sheriklaringiz ovozini kutamiz.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id, "Qabul qilindi!")

        # 🕶👉 Mafiya jamoasi ichida ovoz berishlarni bir-biriga ANIQ ko'rsatish —
        # buyruqsiz, avtomatik. Har bir sherikga: "(rol) (ism) 👉 (nishon) ovoz berdi".
        voter_role = game["players"][uid]["role"]
        voter_name = game["players"][uid]["name"]
        target_name = "🚫 o'tkazib yuborish" if target == "skip" else game["players"].get(target, {}).get("name", "?")
        vote_line = f"{voter_role} {mention(uid, voter_name)} 👉 {target_name} ovoz berdi"
        teammates = [u2 for u2, pp in game["players"].items()
                     if u2 != uid and pp["alive"] and team_of(pp["role"]) == "mafia"]
        for tm in teammates:
            safe_send(tm, f"🕶 <i>{vote_line}</i>")

    elif kind == "komaction":
        if value == "skip":
            game["komissar_action"] = "skip"
            try:
                bot.edit_message_text("🚫 Siz bu tun harakat qilmaslikni tanladingiz.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id)
            return
        game["komissar_action"] = value
        if "komissar" not in game["night_announced"]:
            game["night_announced"].add("komissar")
            if value == "check":
                bot.send_message(chat_id, "🕵️ <i>Komissar biror kishining hujjatlarini tekshirishga tayyorlanmoqda...</i>")
            else:
                bot.send_message(chat_id, "🎯 <i>Komissar hukm chiqarishga qaror qildi — kimdir bu tundan tirik chiqmasligi mumkin...</i>")
        kb = types.InlineKeyboardMarkup()
        for target_id, p in alive_players(game).items():
            if target_id == uid:
                continue
            tag = squad_tag(game, uid, target_id)
            kb.add(types.InlineKeyboardButton(f"{tag}{p['name']}", callback_data=f"na|{chat_id}|komtarget|{target_id}"))
        try:
            bot.edit_message_text("Kimni tanlaysiz?", call.message.chat.id, call.message.message_id, reply_markup=kb)
        except Exception:
            pass
        bot.answer_callback_query(call.id)

    elif kind == "komtarget":
        target_id = int(value)
        game["komissar_target"] = target_id
        notify_target_touched(game, target_id, "Komissar 🕵️‍♂️")
        if game["komissar_action"] == "check":
            target_charges = get_charges(target_id)
            name = game["players"].get(target_id, {}).get("name", "?")
            target_role = game["players"].get(target_id, {}).get("role")
            xaker_acted = bool(game.get("extra_actions", {}).get("xaker"))
            if target_charges.get("fake_doc", 0) > 0 and is_item_active(target_id, "fake_doc"):
                use_charge(target_id, "fake_doc")
                role_shown = "Tinch aholi 👨‍👩‍👧‍👦"
                # 🔧 TUZATILDI: avval bu yerda hech qanday DM yuborilmas edi
                safe_send(target_id, "📁 Sizning <b>Soxta hujjat</b> buyumingiz ishladi — Komissar sizni tekshirganda haqiqiy rolingiz yashirin qoldi!")
            elif target_role == "Sotqin 🕵️‍♀️":
                # 🕵️‍♀️ Sotqin — mafiyaga tegishli, lekin tekshiruvda DOIM "Tinch aholi" bo'lib ko'rinadi
                role_shown = "Tinch aholi 👨‍👩‍👧‍👦"
            elif xaker_acted:
                # 🧑‍💻 Xaker shu tun harakat qilgan bo'lsa — Komissarga SOXTA natija ko'rsatiladi
                role_shown = random.choice([r for r in ALL_ROLES if r != target_role])
                game["xaker_fooled_this_night"] = True
            else:
                role_shown = target_role or "Noma'lum"
            try:
                bot.edit_message_text(f"🔍 Tekshiruv natijasi: <b>{name}</b> — <b>{role_portrait(role_shown)}</b>", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            game["komissar_action"] = "checked_done"
        else:
            try:
                bot.edit_message_text("🎯 O'ldirish buyrug'i qabul qilindi.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
        bot.answer_callback_query(call.id)

    elif kind == "doctor":
        target = value if value == "skip" else int(value)
        game["doctor_target"] = target
        if target != "skip":
            notify_target_touched(game, target, "Doktor 👨‍⚕️")
        if target != "skip" and "doctor" not in game["night_announced"]:
            game["night_announced"].add("doctor")
            bot.send_message(chat_id, "🩺 <i>Doktor navbatchilikka chiqdi, kimnidir davolashga shay turibdi...</i>")
        try:
            bot.edit_message_text("✅ Davolash tanlovi qabul qilindi.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id, "Qabul qilindi!")

    elif kind == "jrn1":
        # 🎙 Jurnalist — 1-kishi tanlandi, endi 2-kishini so'raymiz
        if value == "skip":
            try:
                bot.edit_message_text("🚫 Siz bu tun harakat qilmaslikni tanladingiz.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id)
            return
        first_id = int(value)
        kb = types.InlineKeyboardMarkup()
        for target_id, p in alive_players(game).items():
            if target_id in (uid, first_id):
                continue
            kb.add(types.InlineKeyboardButton(p["name"], callback_data=f"na|{chat_id}|jrn2|{first_id}:{target_id}"))
        try:
            bot.edit_message_text("2️⃣ Ikkinchi kishini tanlang:", call.message.chat.id, call.message.message_id, reply_markup=kb)
        except Exception:
            pass
        bot.answer_callback_query(call.id)

    elif kind == "qrk2":
        # 🥷 Qaroqchi — o'g'irlangan qobiliyatni qo'llash bosqichi
        stolen_slug, target_s2 = value.split(":")
        target_id2 = None if target_s2 == "skip" else int(target_s2)
        if stolen_slug == "doctor":
            if target_id2 is not None:
                game["doctor_target"] = target_id2
                game["extra_actions"]["ogri_steal"] = {"actor": uid, "kind": "doctor", "target": target_id2}
            fb = "✅ O'g'irlangan davolash qobiliyati ishlatildi!" if target_id2 else "🚫 Tanlov bekor qilindi."
        else:
            if target_id2 is not None:
                game.setdefault("extra_actions", {})[stolen_slug] = {"actor": uid, "target": target_id2}
            fb = "✅ O'g'irlangan qobiliyat ishlatildi!" if target_id2 else "🚫 Tanlov bekor qilindi."
        try:
            bot.edit_message_text(fb, call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id, "Qabul qilindi!")

    elif kind == "jrn2":
        # 🎙 Jurnalist — ikkala kishi ham tanlandi, natijani DARHOL beramiz
        first_s, second_s = value.split(":")
        first_id, second_id = int(first_s), int(second_s)
        game.setdefault("extra_actions", {})["jurnalist"] = {"actor": uid, "target": (first_id, second_id)}
        if "jurnalist" not in game["night_announced"]:
            game["night_announced"].add("jurnalist")
            bot.send_message(chat_id, JOURNALIST_FLAVOR)
        n1 = game["players"].get(first_id, {}).get("name", "?")
        n2 = game["players"].get(second_id, {}).get("name", "?")
        t1 = team_of(game["players"].get(first_id, {}).get("role"))
        t2 = team_of(game["players"].get(second_id, {}).get("role"))
        same = "BIR XIL tarafda" if t1 == t2 else "ALOHIDA tarafda"
        try:
            bot.edit_message_text(f"🎙 Natija: <b>{n1}</b> va <b>{n2}</b> — {same}!", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id, "Qabul qilindi!")

    elif kind == "ex":
        # qo'shimcha 25 rolning tungi harakatlari — value = "{slug}:{target_yoki_skip/yes/no}"
        if ":" not in value:
            bot.answer_callback_query(call.id, "Xatolik yuz berdi.")
            return
        slug, target_s = value.split(":", 1)
        role_name = SLUG_TO_ROLE.get(slug)
        if not role_name or game["players"].get(uid, {}).get("role") != role_name:
            bot.answer_callback_query(call.id, "Bu tanlov endi amal qilmaydi.")
            return

        def _announce_once():
            if slug not in game["night_announced"]:
                game["night_announced"].add(slug)
                bot.send_message(chat_id, EXTRA_ROLE_PROMPTS[slug][1])

        # --- darhol natija beradigan (tekshiruv) rollar: Josus, Bomj, Serjant ---
        if slug in EXTRA_ROLE_INSTANT_INFO:
            if target_s == "skip":
                result = "🚫 Siz bu tun harakat qilmaslikni tanladingiz."
            else:
                target_id = int(target_s)
                tname = game["players"].get(target_id, {}).get("name", "?")
                trole = game["players"].get(target_id, {}).get("role", "Noma'lum")
                notify_target_touched(game, target_id, role_name)
                if slug == "josus":
                    result = f"🕵️ Tekshiruv natijasi: <b>{tname}</b> — taraf: <b>{team_of(trole)}</b>"
                elif slug == "serjant":
                    result = f"👮‍♂️ Tekshiruv natijasi: <b>{tname}</b> — <b>{trole}</b>"
                else:  # bomj — tasodifiy ehtimol bilan aniqlaydi
                    if random.random() < 0.5:
                        result = f"🧟‍♂️ Siz tasodifan bilib oldingiz: <b>{tname}</b> — <b>{trole}</b>"
                    else:
                        result = "🧟‍♂️ Afsuski, bu tun hech narsani aniq bila olmadingiz."
                _announce_once()
            try:
                bot.edit_message_text(result, call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Advokat: ertangi kunduzgi osishdan himoya belgilanadi ---
        if slug == "advokat":
            if target_s != "skip":
                game["advocate_protect"] = int(target_s)
                game["advocate_actor"] = uid
                notify_target_touched(game, int(target_s), role_name)
                _announce_once()
            try:
                bot.edit_message_text("✅ Himoya tanlovingiz qabul qilindi.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Provokator: tanlangan o'yinchining ertangi ovozi majburan boshqaga burib yuboriladi ---
        if slug == "provokator":
            if target_s != "skip":
                target_id = int(target_s)
                notify_target_touched(game, target_id, role_name)
                alive_others = [pid for pid in alive_players(game) if pid not in (uid, target_id)]
                if alive_others:
                    game.setdefault("forced_day_votes", {})[target_id] = random.choice(alive_others)
                    _announce_once()
                    fb = "✅ Tanlovingiz qabul qilindi — ertaga uning ovozi majburan burib yuboriladi."
                else:
                    # 🔧 TUZATILDI: juda kam tirik o'yinchi qolganda jim-jit "hech narsa bo'lmadi"
                    # taassurotini beruvchi eski xatolik — endi sabab ANIQ tushuntiriladi.
                    fb = "⚠️ Hozir yetarli boshqa tirik o'yinchi yo'q — bu safar ovozni burib bo'lmadi."
            else:
                fb = "🚫 Siz bu tun harakat qilmaslikni tanladingiz."
            try:
                bot.edit_message_text(fb, call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Sudya: ertangi kun ovozini 2x kuchga ega qiladi ---
        if slug == "sudya":
            if target_s == "yes":
                game["judge_double_vote"] = uid
                _announce_once()
            try:
                bot.edit_message_text("✅ Tanlovingiz qabul qilindi.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Rais: ertangi kun ovozini og'irroq qiladi (Sudya bilan bir xil mexanika, mafiya tarafida) ---
        if slug == "rais":
            if target_s == "yes":
                game["rais_double_vote"] = uid
                _announce_once()
            try:
                bot.edit_message_text("✅ Tanlovingiz qabul qilindi.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Yollanma qotil: FAQAT o'ziga berilgan qat'iy nishonga hujum qiladi ---
        if slug == "yollanma":
            if target_s == "yes":
                game.setdefault("extra_actions", {})["yollanma"] = {"actor": uid, "target": game.get("hitman_target", {}).get(uid, "skip")}
                _announce_once()
                fb = "✅ Bu kecha nishoningizga hujum qilishga qaror qildingiz."
            else:
                fb = "🚫 Bu kecha kutib turishga qaror qildingiz."
            try:
                bot.edit_message_text(fb, call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- O'g'ri: tanlangan o'yinchidan darhol pul o'g'irlaydi ---
        if slug == "ogri":
            # 🥷 Qaroqchi — YANGI mexanika: pul o'g'irlamaydi, balki tanlagan
            # odamning TUNGI QOBILIYATINI o'g'irlab, o'sha kechasi o'zi ishlatadi.
            if target_s == "skip":
                try:
                    bot.edit_message_text("🚫 Siz bu tun harakat qilmaslikni tanladingiz.", call.message.chat.id, call.message.message_id)
                except Exception:
                    pass
                bot.answer_callback_query(call.id, "Qabul qilindi!")
                return
            victim_id = int(target_s)
            notify_target_touched(game, victim_id, role_name)
            victim_role = game["players"].get(victim_id, {}).get("role")
            victim_slug = EXTRA_ROLE_SLUGS.get(victim_role)
            if victim_role == "Doktor 👨‍⚕️":
                game["extra_actions"]["ogri_steal"] = {"actor": uid, "kind": "doctor"}
                alive2 = alive_players(game)
                kb2 = types.InlineKeyboardMarkup()
                for t2, tp2 in alive2.items():
                    kb2.add(types.InlineKeyboardButton(tp2["name"], callback_data=f"na|{chat_id}|qrk2|doctor:{t2}"))
                kb2.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|qrk2|doctor:skip"))
                try:
                    bot.edit_message_text(
                        "🥷 Siz Doktorning DAVOLASH qobiliyatini o'g'irladingiz! Kimni davolaymiz?",
                        call.message.chat.id, call.message.message_id, reply_markup=kb2,
                    )
                except Exception:
                    pass
            elif victim_slug and victim_slug in EXTRA_ROLE_DEFERRED and victim_slug not in ("ogri",):
                # Qurbonning bugungi o'z harakatini bekor qilamiz (o'g'irlab olinganligi uchun)
                game.setdefault("extra_actions", {}).pop(victim_slug, None)
                alive2 = alive_players(game)
                kb2 = types.InlineKeyboardMarkup()
                for t2, tp2 in alive2.items():
                    kb2.add(types.InlineKeyboardButton(tp2["name"], callback_data=f"na|{chat_id}|qrk2|{victim_slug}:{t2}"))
                kb2.add(types.InlineKeyboardButton("🚫 O'tkazib yuborish", callback_data=f"na|{chat_id}|qrk2|{victim_slug}:skip"))
                v_label = SLUG_TO_ROLE.get(victim_slug, victim_slug)
                try:
                    bot.edit_message_text(
                        f"🥷 Siz {v_label}ning qobiliyatini o'g'irladingiz! Kimga qarshi ishlatamiz?",
                        call.message.chat.id, call.message.message_id, reply_markup=kb2,
                    )
                except Exception:
                    pass
            else:
                try:
                    bot.edit_message_text(
                        "🥷 Afsuski, bu odamda o'g'irlab bo'ladigan aniq tungi qobiliyat yo'q edi — bu kecha behuda urindingiz.",
                        call.message.chat.id, call.message.message_id,
                    )
                except Exception:
                    pass
            _announce_once()
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Arvoh (o'lgandan keyin): tirik o'yinchiga sirli imo-ishora yuboradi ---
        if slug == "arvoh":
            if target_s != "skip":
                target_id = int(target_s)
                game["players"][uid]["ghost_hint_given"] = True
                safe_send(target_id, "👻 <i>G'ayrioddiy sovuq shabada his qildingiz... kimdir sizga nimadir "
                                      "aytmoqchidek bo'ldi, lekin so'zlar tushunarsiz bo'lib qoldi.</i>")
                _announce_once()
            try:
                bot.edit_message_text("✅ Qabul qilindi.", call.message.chat.id, call.message.message_id)
            except Exception:
                pass
            bot.answer_callback_query(call.id, "Qabul qilindi!")
            return

        # --- Qolganlari (Qotil/Manyak/Mergan/Snayper/Telba/Kezuvchi/Sehrgar/
        #     General/Arxitektor/Qorovul/Sadoqatli yordamchi) — tun yakunida
        #     resolve_night() ichida birgalikda hisoblanadi ---
        target = target_s if target_s == "skip" else int(target_s)
        game.setdefault("extra_actions", {})[slug] = {"actor": uid, "target": target}
        if target != "skip":
            _announce_once()
        try:
            bot.edit_message_text("✅ Tanlovingiz qabul qilindi.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id, "Qabul qilindi!")


def apply_kill(game, uid, killed_set, bypass_protection=False, attacker_uids=None):
    """Bitta o'yinchini o'ldirish urinishi — shield/revive/doktor davolashi hisobga olinadi.
    attacker_uids — (ixtiyoriy) shu hujumni amalga oshirgan o'yinchi(lar) ID'lari; agar
    geroy qobiliyati himoya qilib qolsa, ularga ANONIM tarzda DM yuboriladi."""
    if uid is None or uid == "skip" or uid not in game["players"]:
        return
    p = game["players"][uid]
    if not p["alive"] or uid in killed_set:
        return
    if not bypass_protection:
        if game.get("doctor_target") == uid:
            return
        if uid in game.get("night_protected", set()):
            return
        # 👶 Beshikdagi bola — o'yinning birinchi tunida hech kim unga tega olmaydi
        if p["role"] == "Beshikdagi bola 👶" and game.get("day_number", 0) <= 1:
            return
        # 🪓 Varvar — baquvvat jangchi, ayrim hujumlarga qarshilik ko'rsatadi (30% ehtimol)
        if p["role"] == "Varvar 🪓" and random.random() < 0.3:
            bot.send_message(game["chat_id"], "🪓 <i>Kimningdir baquvvat gavdasi hujumga bardosh berdi...</i>")
            safe_send(uid, "🪓 Bu kecha sizga hujum qilishdi, lekin Varvarning jismoniy bardoshi tufayli omon qoldingiz!")
            for a_uid in (attacker_uids or []):
                safe_send(a_uid, "🪓 <i>Nishoningiz g'ayrioddiy bardoshli chiqib, hujumdan omon qoldi...</i>")
            return
        # 🏆 Geroy (Draven / Zephyrion) — FAQAT o'zi /geroy_qalqon bilan shu tunga QO'LDA
        # faollashtirgan bo'lsa ishlaydi (avtomatik EMAS). Avval kafolatlangan "revive_once"
        # (agar hali sarflanmagan bo'lsa), aks holda oddiy % ehtimolli "survive" tekshiriladi.
        if uid in game.get("hero_armed_defense", set()):
            if hero_has_ability(uid, "revive_once") and uid not in game.setdefault("hero_revive_used", set()):
                game["hero_revive_used"].add(uid)
                _hero_ab = next((a for a in hero_unlocked_abilities(uid) if a["key"] == "revive_once"), None)
                _hero = get_hero(uid)
                announce_hero_ability_use(game["chat_id"], _hero["name"], _hero_ab["name"] if _hero_ab else "⚰️ O'lmas ruh", uid=uid, hero_key=_hero["key"])
                safe_send(uid, "🔥 Geroyingizning bir martalik qobiliyati ishga tushdi — bu safar o'limdan qutuldingiz! (Endi sarflandi.)")
                for a_uid in (attacker_uids or []):
                    safe_send(a_uid, "🏆 <i>Nishoningiz kimningdir geroy qobiliyati tufayli o'limdan qutulib qoldi...</i>")
                return
            h_chance = hero_survive_chance(uid)
            if h_chance > 0 and random.random() < h_chance:
                _hero_ab = next((a for a in hero_unlocked_abilities(uid) if a["key"] == "survive"), None)
                _hero = get_hero(uid)
                announce_hero_ability_use(game["chat_id"], _hero["name"], _hero_ab["name"] if _hero_ab else "🛡 Tungi chidamlilik", uid=uid, hero_key=_hero["key"])
                safe_send(uid, "🏆 Geroyingiz faollashtirilgan edi — bu kecha sizga hujum qilishdi, lekin geroyingiz sizni qutqardi!")
                for a_uid in (attacker_uids or []):
                    safe_send(a_uid, "🏆 <i>Nishoningiz kimningdir geroy qobiliyati tufayli hujumdan omon qoldi...</i>")
                return
        if consume_shield(uid):
            bot.send_message(game["chat_id"], "🛡 <i>Kimningdir maxsus buyumi uni tunda hujumdan asrab qoldi!</i>")
            safe_send(uid, "🛡 Bu kecha sizga hujum qilishdi, lekin buyumingiz sizni himoya qildi!")
            return
        if is_item_active(uid, "revive") and use_charge(uid, "revive"):
            bot.send_message(game["chat_id"], "⚡️ <i>Kimningdir tezkor jonlanish tumori uni o'limdan qutqarib qoldi!</i>")
            safe_send(uid, "⚡️ Bu kecha sizga hujum qilishdi, lekin Tezkor jonlanish tumoringiz sizni qutqardi!")
            return
    # 🏆 Geroy (Draven, 15-daraja "🩸 Qasos nafasi") — halok bo'lish muqarrar bo'lganda,
    # o'yin davomida BIR MARTA, o'zini o'ldirgan kishining ANIQ rolini shaxsiy bilib oladi.
    if (hero_has_ability(uid, "death_reveal_once") and attacker_uids
            and uid not in game.setdefault("hero_death_reveal_used", set())):
        game["hero_death_reveal_used"].add(uid)
        _hero = get_hero(uid)
        _killer_role = game["players"].get(attacker_uids[0], {}).get("role", "Noma'lum")
        safe_send(uid, f"🩸 So'nggi nafasingizda geroyingiz sizga pichirladi — sizni halok qilgan kishining roli: <b>{_killer_role}</b>!")
        announce_hero_ability_use(game["chat_id"], _hero["name"], "🩸 Qasos nafasi", uid=uid, hero_key=_hero["key"])
    killed_set.add(uid)


def resolve_night(chat_id):
    with GAME_LOCK:
        game = GAMES.get(chat_id)
        if not game or game["phase"] != "night":
            return

        # ========================================================================
        #  QO'SHIMCHA ROLLAR — 1-bosqich: bloklash va himoya (kimlar bloklandi/
        #  himoyalandi, boshqa harakatlardan OLDIN aniqlanishi kerak)
        # ========================================================================
        # 👁 v8: Seraphine "Tungi nazar" — Avto-rejimda har tun oxirida o'zi xabar beradi
        for _hv_uid in list(alive_players(game).keys()):
            try:
                if hero_has_ability(_hv_uid, "night_vision_auto") and hero_auto_enabled(_hv_uid):
                    do_geroy_koz(_hv_uid)
            except Exception:
                _logger.exception("Avto-tungi nazar xatoligi (uid=%s)", _hv_uid)

        extra = game.get("extra_actions", {})
        roleblocked = set()
        night_protected = set()

        # 👩‍⚕️ Hamshira — Doktor halok bo'lgandan keyin uning vazifasini bajaradi.
        # Eng sodda va ishonchli yo'l: uning tanlovini xuddi Doktornikidek game["doctor_target"]
        # sifatida belgilaymiz — shu bilan mavjud apply_kill() himoyasi avtomatik ishlaydi.
        hamshira_act = extra.get("hamshira")
        if hamshira_act and hamshira_act["target"] != "skip" and not game.get("doctor_target"):
            game["doctor_target"] = hamshira_act["target"]

        fohisha_act = extra.get("fohisha")
        # 💋➜😴 Kezuvchi tashrif buyurgan o'yinchi endi FAQAT tungi mahoratdan emas —
        # ERTANGI KUNDUZGI OVOZ BERISHDAN ham mahrum bo'ladi (butun kun "uxlab qoladi").
        # Har kecha qayta hisoblanadi (avvalgi kun mahsuli keyingi kunlarga o'tmaydi).
        game["day_silenced"] = set()
        if fohisha_act and fohisha_act["target"] != "skip":
            roleblocked.add(fohisha_act["target"])
            game["day_silenced"].add(fohisha_act["target"])

        # 🧙‍♂️ Sehrgar — bashorat qilib bo'lmaydigan sehr: yo himoya, yoki bloklash
        sehrgar_act = extra.get("sehrgar")
        if sehrgar_act and sehrgar_act["target"] != "skip":
            t = sehrgar_act["target"]
            if random.random() < 0.5:
                night_protected.add(t)
            else:
                roleblocked.add(t)

        for slug in ("general", "arxitektor", "qorovul", "sadoqat", "sehryor"):
            act = extra.get(slug)
            if act and act["target"] != "skip":
                night_protected.add(act["target"])
                actor_role = game["players"].get(act["actor"], {}).get("role")
                notify_target_touched(game, act["target"], actor_role)
        game["night_protected"] = night_protected

        if fohisha_act and fohisha_act["target"] != "skip":
            notify_target_touched(game, fohisha_act["target"], "Mashuqa 💋")
        if sehrgar_act and sehrgar_act["target"] != "skip":
            notify_target_touched(game, sehrgar_act["target"], "Sehrgar 🧙‍♂️")

        if roleblocked:
            doctor_uid = next(iter(alive_role_holders(game, lambda r: r == "Doktor 👨‍⚕️")), None)
            komissar_uid = next(iter(alive_role_holders(game, lambda r: r == "Komissar 🕵️‍♂️")), None)
            for voter in list(game["mafia_votes"].keys()):
                if voter in roleblocked:
                    game["mafia_votes"][voter] = "skip"
            if doctor_uid in roleblocked:
                game["doctor_target"] = "skip"
            if komissar_uid in roleblocked:
                game["komissar_action"] = "skip"
            for act in extra.values():
                if act["actor"] in roleblocked:
                    act["target"] = "skip"

        # --- mafiya ko'pchilik ovozi ---
        tally = {}
        for voter, target in game["mafia_votes"].items():
            if target != "skip":
                tally[target] = tally.get(target, 0) + 1
        mafia_kill_target = None
        bypass_for_mafia = False
        if tally:
            max_v = max(tally.values())
            top = [t for t, v in tally.items() if v == max_v]
            mafia_kill_target = random.choice(top)

            # ✉️ Tushunarsiz xat — nishonda "confuse" bo'lsa hujum boshqasiga buriladi
            target_charges = get_charges(mafia_kill_target)
            if target_charges.get("confuse", 0) > 0 and is_item_active(mafia_kill_target, "confuse"):
                use_charge(mafia_kill_target, "confuse")
                # 🔧 TUZATILDI: avval bu yerda hech qanday DM yuborilmas edi — endi
                # o'zining "Tushunarsiz xat" buyumi ishlaganini albatta biladi.
                safe_send(mafia_kill_target, "✉️ Sizning <b>Tushunarsiz xat</b> buyumingiz ishladi — mafiyaning hujumi sizdan chalg'itib yuborildi!")
                alt = [uid for uid, p in alive_players(game).items()
                       if uid != mafia_kill_target and team_of(p["role"]) != "mafia"]
                if alt:
                    mafia_kill_target = random.choice(alt)

            # 🟡 Oltin o'q — mafiyalardan birortasida bo'lsa himoyani chetlab o'tadi
            for voter_uid, target in game["mafia_votes"].items():
                if target == mafia_kill_target and get_charges(voter_uid).get("golden_bullet", 0) > 0 and is_item_active(voter_uid, "golden_bullet"):
                    use_charge(voter_uid, "golden_bullet")
                    bypass_for_mafia = True
                    safe_send(voter_uid, "🟡 Bu kecha 🟡 Oltin o'qingiz ishlatildi — bu safar hujumingiz barcha himoyalarni chetlab o'tadi!")
                    break

        # 🕵️ Missiya kuzatuvi — ertangi kunduzgi ovoz berish uchun "bugungi tunda
        # mafiya kimni nishonga oldi" ma'lumotini saqlaymiz
        game["last_night_mafia_target"] = mafia_kill_target

        # kim kimning "uyiga bordi" — o'lim xabarida oshkor qilish uchun (qoshimchakod uslubi)
        visitor_role_of = {}
        if mafia_kill_target is not None:
            voter_roles = [game["players"][v]["role"] for v, t in game["mafia_votes"].items()
                           if t == mafia_kill_target and v in game["players"]]
            if voter_roles:
                visitor_role_of[mafia_kill_target] = random.choice(voter_roles)
        if game.get("komissar_action") == "kill" and game.get("komissar_target"):
            visitor_role_of[game["komissar_target"]] = "Komissar 🕵️‍♂️"

        killed = set()
        attempted_targets = set()
        if mafia_kill_target is not None:
            attempted_targets.add(mafia_kill_target)
            notify_target_touched(game, mafia_kill_target, visitor_role_of.get(mafia_kill_target, "Mafia 🕶"))
        apply_kill(game, mafia_kill_target, killed, bypass_protection=bypass_for_mafia,
                   attacker_uids=[v for v, t in game["mafia_votes"].items() if t == mafia_kill_target])

        if game.get("komissar_action") == "kill" and game.get("komissar_target"):
            attempted_targets.add(game["komissar_target"])
            _kom_uid = next(iter(alive_role_holders(game, lambda r: r == "Komissar 🕵️‍♂️")), None)
            apply_kill(game, game["komissar_target"], killed, attacker_uids=[_kom_uid] if _kom_uid else None)

        # 🧪 Zaharli flakon — /zahar orqali belgilanganlar
        # 🐛 TUZATILDI: endi dict {target_id: [zaharlovchi_id, ...]} — attacker_uids
        # apply_kill'ga to'g'ri uzatiladi, shu bilan geroy himoyasi ishlaganda
        # zaharlovchiga ham to'g'ri (anonim) bildirishnoma boradi, boshqa hujum
        # turlari (mafiya, qotil va h.k.) bilan bir xil ishlaydi.
        poison_marks = game.pop("poison_marks", {})
        if isinstance(poison_marks, set):  # eski formatdagi saqlangan o'yin bilan moslik uchun
            poison_marks = {pt: [] for pt in poison_marks}
        for pt, poisoners in poison_marks.items():
            if pt not in game["players"] or not game["players"][pt]["alive"] or pt in killed:
                continue
            attempted_targets.add(pt)
            # 🩹 Kichik Aptechka — zaharga qarshi 1 martalik avtomatik davo
            if get_charges(pt).get("antidote", 0) > 0 and is_item_active(pt, "antidote"):
                use_charge(pt, "antidote")
                safe_send(pt, "🩹 Sizni kimdir zaharlamoqchi bo'ldi, lekin Aptechkangiz avtomatik davoladi!")
                continue
            apply_kill(game, pt, killed, attacker_uids=poisoners)
        game["poison_marks"] = {}

        # ========================================================================
        #  QO'SHIMCHA ROLLAR — 2-bosqich: mustaqil qotillar (Qotil/Manyak/Mergan/Snayper)
        #  va Telba ning tasodifiy harakati
        # ========================================================================
        for slug in ("qotil", "manyak", "mergan"):
            act = extra.get(slug)
            if act and act["target"] != "skip":
                actor_role = game["players"].get(act["actor"], {}).get("role")
                notify_target_touched(game, act["target"], actor_role)
                attempted_targets.add(act["target"])
                if actor_role and act["target"] not in visitor_role_of:
                    visitor_role_of[act["target"]] = actor_role
                apply_kill(game, act["target"], killed, attacker_uids=[act["actor"]])

        snayper_act = extra.get("snayper")
        if snayper_act and snayper_act["target"] != "skip":
            actor_role = game["players"].get(snayper_act["actor"], {}).get("role")
            notify_target_touched(game, snayper_act["target"], actor_role)
            attempted_targets.add(snayper_act["target"])
            if actor_role and snayper_act["target"] not in visitor_role_of:
                visitor_role_of[snayper_act["target"]] = actor_role
            apply_kill(game, snayper_act["target"], killed, attacker_uids=[snayper_act["actor"]])
            game.setdefault("snayper_used", set()).add(snayper_act["actor"])

        # 🐺 Bo'ri — faqat JUFT tunlarda yirtqichga aylanib 1 kishini yutadi
        bori_act = extra.get("bori")
        if bori_act and bori_act["target"] != "skip":
            notify_target_touched(game, bori_act["target"], "Bo'ri 🐺")
            attempted_targets.add(bori_act["target"])
            if bori_act["target"] not in visitor_role_of:
                visitor_role_of[bori_act["target"]] = "Bo'ri 🐺"
            apply_kill(game, bori_act["target"], killed, attacker_uids=[bori_act["actor"]])

        # 🔫 Yollanma qotil — FAQAT o'ziga berilgan qat'iy nishonga hujum qiladi
        yollanma_act = extra.get("yollanma")
        if yollanma_act and yollanma_act["target"] not in (None, "skip"):
            notify_target_touched(game, yollanma_act["target"], "Yollanma qotil 🔫")
            attempted_targets.add(yollanma_act["target"])
            if yollanma_act["target"] not in visitor_role_of:
                visitor_role_of[yollanma_act["target"]] = "Yollanma qotil 🔫"
            apply_kill(game, yollanma_act["target"], killed, attacker_uids=[yollanma_act["actor"]])

        # 🤬 G'azabkor — kunduzi unga qarshi ovoz berganlardan BIRINI, shu kecha
        # avtomatik (tugma bosmasdan) otib tashlaydi
        for gz_uid, voters in list(game.get("gazabkor_voters", {}).items()):
            if voters and gz_uid in game["players"] and game["players"][gz_uid]["alive"]:
                victim = random.choice(voters)
                notify_target_touched(game, victim, "G'azabkor 🤬")
                attempted_targets.add(victim)
                if victim not in visitor_role_of:
                    visitor_role_of[victim] = "G'azabkor 🤬"
                apply_kill(game, victim, killed, attacker_uids=[gz_uid])
                v_name = game["players"].get(victim, {}).get("name", "?")
                safe_send(gz_uid, f"🤬 G'azabingiz {mention(victim, v_name)}ni nishonga oldi!")
        game["gazabkor_voters"] = {}

        # 🧟 Zombi — tishlagan o'yinchi omon qolsa, o'zi ham Zombiga aylanadi
        zombi_act = extra.get("zombi")
        zombi_infected = None
        if zombi_act and zombi_act["target"] != "skip":
            notify_target_touched(game, zombi_act["target"], "Zombi 🧟")
            attempted_targets.add(zombi_act["target"])
            t_id = zombi_act["target"]
            pre_alive = game["players"][t_id]["alive"] if t_id in game["players"] else False
            fake_killed = set()
            apply_kill(game, t_id, fake_killed, attacker_uids=[zombi_act["actor"]])
            if t_id not in fake_killed and pre_alive:
                # 🧟 Himoyalanmagan — o'lmadi, lekin ZOMBIGA AYLANDI
                game["players"][t_id]["role"] = "Zombi 🧟"
                game["players"][t_id]["team"] = "independent"
                zombi_infected = t_id
            else:
                killed |= fake_killed

        # 🧪 Kimyogar — sekin ta'sir qiluvchi zahar: keyingi tun OXIRIDA o'ldiradi (hozir emas)
        kimyogar_act = extra.get("kimyogar")
        if kimyogar_act and kimyogar_act["target"] != "skip":
            notify_target_touched(game, kimyogar_act["target"], "Kimyogar 🧪")
            game.setdefault("delayed_poison", {})[kimyogar_act["target"]] = {
                "due_night": game.get("night_count", 1) + 1, "actor": kimyogar_act["actor"],
            }
            kg_name = game["players"].get(kimyogar_act["target"], {}).get("name", "?")
            safe_send(kimyogar_act["actor"], f"🧪 Zaharni {mention(kimyogar_act['target'], kg_name)}ga berdingiz — u keyingi tun oxirida ta'sir qiladi.")
        # ☠️ Kechiktirilgan zahar muddati kelganlarni shu tun yakunida o'ldiramiz
        due_now = {pt: info for pt, info in game.get("delayed_poison", {}).items() if info["due_night"] <= game.get("night_count", 1)}
        for pt, info in due_now.items():
            pt_name = game["players"].get(pt, {}).get("name", "?")
            if pt in game["players"] and game["players"][pt]["alive"] and pt not in killed:
                attempted_targets.add(pt)
                apply_kill(game, pt, killed, attacker_uids=[info["actor"]])
                if pt in killed:
                    safe_send(info["actor"], f"🧪 Zahar ishladi — {mention(pt, pt_name)} halok bo'ldi!")
                else:
                    safe_send(info["actor"], f"🛡 {mention(pt, pt_name)}ga bergan zaharingiz kimningdir himoyasi tufayli ishlamadi.")
            game["delayed_poison"].pop(pt, None)

        # 🔮 Afsungar — nishonlangan o'yinchi ertangi kuni guruh chatida yoza olmaydi
        afsungar_act = extra.get("afsungar")
        if afsungar_act and afsungar_act["target"] != "skip":
            notify_target_touched(game, afsungar_act["target"], "Afsungar 🔮")
            muted_id = afsungar_act["target"]
            try:
                bot.restrict_chat_member(
                    chat_id, muted_id,
                    permissions=types.ChatPermissions(can_send_messages=False),
                    until_date=int(time.time()) + DAY_TOTAL_SECONDS + 30,
                )
                game.setdefault("afsungar_muted", set()).add(muted_id)
            except Exception as e:
                _logger.warning("Afsungar mute qila olmadi: %s", e)

        # 🎭 Aferist — kimningdir qiyofasiga kiradi; agar shu kun O'ZI o'lsa, o'rniga
        # tanlangan odam o'ladi (pastda "killed" ro'yxati yakunlanayotganda qo'llanadi)
        aferist_act = extra.get("aferist")
        if aferist_act and aferist_act["target"] != "skip":
            notify_target_touched(game, aferist_act["target"], "Aferist 🎭")
            game["aferist_disguise"] = {"actor": aferist_act["actor"], "target": aferist_act["target"]}
        else:
            game["aferist_disguise"] = None
        disg = game.get("aferist_disguise")
        if disg and disg["actor"] in killed and disg["target"] not in killed and disg["target"] in game["players"] and game["players"][disg["target"]]["alive"]:
            killed.discard(disg["actor"])
            killed.add(disg["target"])
            visitor_role_of[disg["target"]] = visitor_role_of.get(disg["actor"], visitor_role_of.get(disg["target"]))
            safe_send(disg["actor"], "🎭 Qiyofa almashtirish qobiliyatingiz sizni o'limdan qutqardi — o'rningizga boshqa odam halok bo'ldi!")

        telba_triggered = False
        telba_act = extra.get("telba")
        if telba_act and telba_act["target"] != "skip":
            notify_target_touched(game, telba_act["target"], "Telba 🤪")
            if random.random() < 0.5:
                telba_triggered = True
                attempted_targets.add(telba_act["target"])
                if telba_act["target"] not in visitor_role_of:
                    visitor_role_of[telba_act["target"]] = "Telba 🤪"
                apply_kill(game, telba_act["target"], killed, attacker_uids=[telba_act["actor"]])

        # ========================================================================
        #  QO'SHIMCHA ROLLAR — 3-bosqich: har bir rolga o'z harakati natijasi
        #  haqida shaxsiy (DM) hisobot — foydali/foydasiz bo'lganini bildiradi
        # ========================================================================
        doctor_uid = next(iter(alive_role_holders(game, lambda r: r == "Doktor 👨‍⚕️")), None)
        if doctor_uid and game.get("doctor_target") not in (None, "skip"):
            d_target = game["doctor_target"]
            t_name = game["players"].get(d_target, {}).get("name", "?")
            if d_target in attempted_targets:
                safe_send(doctor_uid, f"🩺 Bu kecha {mention(d_target, t_name)}ga yordam berdingiz — hujumdan qutqardingiz!")
            else:
                safe_send(doctor_uid, f"🩺 Hech kim {mention(d_target, t_name)}ga hujum qilishga urinmadi — bu safar yordamingiz kerak bo'lmadi.")

        # 👩‍⚕️ Hamshira — Doktor o'rniga davolagan bo'lsa, o'ziga alohida hisobot
        if hamshira_act and hamshira_act["target"] != "skip" and not doctor_uid:
            h_target = hamshira_act["target"]
            t_name = game["players"].get(h_target, {}).get("name", "?")
            if h_target in attempted_targets:
                safe_send(hamshira_act["actor"], f"👩‍⚕️ Bu kecha {mention(h_target, t_name)}ga yordam berdingiz — hujumdan qutqardingiz!")
            else:
                safe_send(hamshira_act["actor"], f"👩‍⚕️ Hech kim {mention(h_target, t_name)}ga hujum qilishga urinmadi — bu safar yordamingiz kerak bo'lmadi.")

        # 🧟‍♂️ Daydi / 🦅 Ayg'oqchi — kim kimnikiga borgan/kelganini kuzatish natijasi
        for slug, icon in (("bomj", "🧟‍♂️"), ("aygochi", "🦅")):
            act = extra.get(slug)
            if not act or act["target"] == "skip":
                continue
            watched_id = act["target"]
            t_name = game["players"].get(watched_id, {}).get("name", "?")
            visited_by = watched_id in attempted_targets  # kimdir uning oldiga keldimi
            if visited_by:
                safe_send(act["actor"], f"{icon} Kuzatuv natijasi: <b>{t_name}</b>ning oldiga bu kecha kimdir keldi!")
            else:
                safe_send(act["actor"], f"{icon} Kuzatuv natijasi: <b>{t_name}</b> bu kecha uyidan chiqmadi, hech kim ham kelmadi.")

        # 🔮 Afsungar — natija hisoboti
        if afsungar_act and afsungar_act["target"] != "skip":
            t_name = game["players"].get(afsungar_act["target"], {}).get("name", "?")
            if afsungar_act["target"] in game.get("afsungar_muted", set()):
                safe_send(afsungar_act["actor"], f"🔮 Afsuningiz ishladi — {mention(afsungar_act['target'], t_name)} ertaga chatda yoza olmaydi!")
            else:
                safe_send(afsungar_act["actor"], "🔮 Afsuningiz kutilganidek ishlamadi (bot guruhda admin huquqiga ega emasligi mumkin).")

        for slug in ("general", "arxitektor", "qorovul", "sadoqat", "sehryor"):
            act = extra.get(slug)
            if act and act["target"] != "skip":
                t_name = game["players"].get(act["target"], {}).get("name", "?")
                if act["target"] in attempted_targets:
                    safe_send(act["actor"], f"🛡 Himoyangiz ishladi! {mention(act['target'], t_name)} tunni omon o'tkazdi.")
                else:
                    safe_send(act["actor"], "😌 Hech kim hujum qilmagani uchun bu kecha himoyangiz kerak bo'lmadi.")

        for slug, ic in (("qotil", "🗡"), ("manyak", "🔪"), ("mergan", "🏹"), ("bori", "🐺"), ("yollanma", "🔫")):
            act = extra.get(slug)
            if act and act.get("target") not in (None, "skip"):
                t_name = game["players"].get(act["target"], {}).get("name", "?")
                if act["target"] in killed:
                    safe_send(act["actor"], f"{ic} Nishoningiz {mention(act['target'], t_name)} halok bo'ldi.")
                else:
                    safe_send(act["actor"], f"🛡 {mention(act['target'], t_name)}ni maqsad qilgan edingiz, lekin kimningdir himoyasi tufayli u omon qoldi.")
            elif slug == "yollanma" and act and act.get("target") in (None, "skip"):
                safe_send(act["actor"], "🔫 Bu kecha nishoningizga hujum qilmadingiz.")

        # 🔧 TUZATILDI: Telba roliga avval HECH QANDAY natija xabari yuborilmas
        # edi (boshqa barcha rollarga yuboriladi) — endi u ham o'z tasodifiy
        # harakati natijasi haqida ANIQ shaxsiy xabar oladi.
        if telba_act and telba_act["target"] != "skip":
            t_name = game["players"].get(telba_act["target"], {}).get("name", "?")
            if telba_triggered and telba_act["target"] in killed:
                safe_send(
                    telba_act["actor"],
                    f"🤪 Tasodifiy taqdir kulib boqdi... {mention(telba_act['target'], t_name)} sizning "
                    f"g'ayrioddiy harakatingiz qurboni bo'ldi!",
                )
            elif telba_triggered:
                safe_send(
                    telba_act["actor"],
                    f"🤪 {mention(telba_act['target'], t_name)}ga hujum qildingiz, lekin himoya tufayli omon qoldi.",
                )
            else:
                safe_send(
                    telba_act["actor"],
                    f"🤪 Bu safar {mention(telba_act['target'], t_name)}ga hech narsa bo'lmadi — Telba harakati har doim natija bermaydi!",
                )

        if snayper_act and snayper_act["target"] != "skip":
            t_name = game["players"].get(snayper_act["target"], {}).get("name", "?")
            if snayper_act["target"] in killed:
                safe_send(snayper_act["actor"], f"🎯 Otganingiz aniq tegdi — {mention(snayper_act['target'], t_name)} halok bo'ldi.")
            else:
                safe_send(snayper_act["actor"], f"🛡 {mention(snayper_act['target'], t_name)}ni nishonga oldingiz, lekin himoyasi uni qutqardi.")

        if fohisha_act and fohisha_act["target"] != "skip":
            t_name = game["players"].get(fohisha_act["target"], {}).get("name", "?")
            safe_send(fohisha_act["actor"], f"💋 {mention(fohisha_act['target'], t_name)}ni band qildingiz — u bu kecha qobiliyatini ishlata olmadi.")

        # 🧟 Zombi — natija hisoboti: tishlash Zombiga aylantirdimi, o'ldirdimi yoki ta'sir qilmadimi
        if zombi_act and zombi_act["target"] != "skip":
            zt_name = game["players"].get(zombi_act["target"], {}).get("name", "?")
            if zombi_infected:
                safe_send(zombi_act["actor"], f"🧟 Tishlashingiz ishladi — {mention(zombi_act['target'], zt_name)} endi Zombiga aylandi!")
            elif zombi_act["target"] in killed:
                safe_send(zombi_act["actor"], f"🧟 {mention(zombi_act['target'], zt_name)} halok bo'ldi (Zombiga aylanolmadi).")
            else:
                safe_send(zombi_act["actor"], f"🛡 {mention(zombi_act['target'], zt_name)}ni tishlamoqchi bo'ldingiz, lekin kimningdir himoyasi tufayli ta'sir qilmadi.")

        if sehrgar_act and sehrgar_act["target"] != "skip":
            t_name = game["players"].get(sehrgar_act["target"], {}).get("name", "?")
            if sehrgar_act["target"] in night_protected:
                safe_send(sehrgar_act["actor"], f"🧙‍♂️ Sehringiz {mention(sehrgar_act['target'], t_name)}ni himoyaladi!")
            else:
                safe_send(sehrgar_act["actor"], f"🧙‍♂️ Sehringiz {mention(sehrgar_act['target'], t_name)}ning qobiliyatini bloklab qo'ydi!")

        # 🧑‍💻 Xaker — natija hisoboti: Komissar shu tun haqiqatan ham tekshiruv
        # o'tkazib, soxta natija ko'rgan bo'lsa ishladi, aks holda behuda urinish bo'ldi
        xaker_act = extra.get("xaker")
        if xaker_act and xaker_act.get("target") not in (None, "skip"):
            if game.get("xaker_fooled_this_night"):
                safe_send(xaker_act["actor"], "🧑‍💻 Hujumingiz ishladi — Komissar bu kecha soxta tekshiruv natijasini ko'rdi!")
            else:
                safe_send(xaker_act["actor"], "🧑‍💻 Bu kecha Komissar tekshiruv o'tkazmadi (yoki boshqa himoya ustunlik qildi) — hujumingiz behuda ketdi.")
        game["xaker_fooled_this_night"] = False

        if killed:
            killed_names_for_ai = []
            for uid in killed:
                game["players"][uid]["alive"] = False
                name = game["players"][uid]["name"]
                role = game["players"][uid]["role"]
                killed_names_for_ai.append(name)
                visitor = visitor_role_of.get(uid)
                text = f"☠️ Tunda {mention(uid, name)} vahshiylarcha o'ldirildi!\nFosh qilingan roli: <b>{role}</b>"
                if visitor:
                    text += f"\n<i>{VISIT_PHRASE.get(visitor, f'Aytishlaricha unikiga {visitor} kelgan...')}</i>"
                bot.send_message(chat_id, text)
                handle_death_side_effects(game, chat_id, uid)  # 👑 Don vorisligi / 👻 Arvoh faollashuvi
            for uid in killed:
                wait_last_words(chat_id, uid)
            # 🧠 AI qisqa hikoyasi — endi alohida xabar EMAS, keyingi "tirik o'yinchilar"
            # xabariga qo'shib yuboriladi (pastda) — guruhga xabar sonini kamaytiradi
            narration = theron_night_narration_text(killed_names_for_ai, no_death=False)
        else:
            bot.send_message(chat_id, "🌤 Bu tunda hech kim halok bo'lmadi.")
            narration = theron_night_narration_text([], no_death=True)

        # 🥽 Tungi ko'zoynak — DM orqali "kim faol bo'lganini" ko'rsatish
        acted_roles = []
        if any(v != "skip" for v in game["mafia_votes"].values()):
            acted_roles.append("🕶 Mafiya")
        if game.get("komissar_action") not in (None, "skip"):
            acted_roles.append("🕵️‍♂️ Komissar")
        if game.get("doctor_target") not in (None, "skip"):
            acted_roles.append("👨‍⚕️ Doktor")
        for uid, p in list(game["players"].items()):
            ch = get_charges(uid)
            if p["alive"] and ch.get("night_vision", 0) > 0 and is_item_active(uid, "night_vision"):
                use_charge(uid, "night_vision")
                text = "🥽 Bu tun faol bo'lgan rollar: " + (", ".join(acted_roles) if acted_roles else "hech kim")
                safe_send(uid, text)

        # 🏆 Geroy (Seraphine/Zephyrion "Tungi nazar") — har tun avtomatik, bepul,
        # nechta o'yinchi faol harakat qilganini (kimligini emas) DM orqali bildiradi
        active_count = len(game.get("responded_tonight", set()))
        for uid, p in list(game["players"].items()):
            if p["alive"] and hero_has_ability(uid, "night_vision_auto"):
                safe_send(uid, f"👁 Geroyingiz sizga pichirlaydi: bu tun <b>{active_count}</b> ta o'yinchi faol harakat qildi.")

        if check_and_end_game(chat_id):
            return

        bot.send_message(chat_id, (narration + "\n\n" if narration else "") + roster_breakdown_text(game))
        start_day(chat_id)


def handle_death_side_effects(game, chat_id, uid):
    """💀 Bir o'yinchi (istalgan sabab bilan — tunda o'ldirilgan, kunduzi osilgan
    yoki o'zi tark etgan) halok bo'lgach chaqiriladi. Uchta muhim narsani bajaradi:

      1) 👑 DON VORISLIGI — agar halok bo'lgan DON bo'lsa, tirik qolgan
         Mafia 🕶 a'zolaridan biri tasodifiy tarzda yangi DON etib
         ko'tariladi (Almex Black Bot uslubi: "Siz endi DON bo'ldingiz!").
      2) 👻 ARVOH FAOLLASHUVI — agar halok bo'lgan Arvoh bo'lsa, unga o'zining
         yangi (o'limdan keyingi) qobiliyati haqida aniq tushuntirish yuboriladi
         (aks holda o'yinchi "hech narsa bo'lmadi" deb o'ylashi mumkin edi).
      3) 💍 PARA (couple) REJIMI — 'bog'langan taqdir': agar halok bo'lgan
         o'yinchining MAXFIY sherigi hali tirik bo'lsa, u ham DARHOL halok
         bo'ladi va juftlik guruhga endi (birinchi marta) FOSH qilinadi."""
    p = game["players"].get(uid)
    if not p:
        return
    role = p.get("role")

    if role == "Don 🎩":
        candidates = [c_uid for c_uid, cp in alive_players(game).items() if cp["role"] == "Mafia 🕶"]
        if candidates:
            new_don = random.choice(candidates)
            game["players"][new_don]["role"] = "Don 🎩"
            safe_send(
                new_don,
                "👑 <b>Siz endi DON bo'ldingiz!</b>\n"
                "Mafiya guruhining yangi rahbari — endi qurbon tanlash huquqi (mafiya ovozi) sizda.",
            )
            bot.send_message(chat_id, "👑 <i>Mafiya safida yangi DON ko'tarildi...</i>")

    if role == "Arvoh 👻":
        safe_send(
            uid,
            "👻 <b>Siz Arvohga aylandingiz!</b>\n"
            "Tanangiz halok bo'ldi, ammo ruhingiz qoladi. Har tun tirik o'yinchilardan biriga "
            "shaxsiy chatda sirli imo-ishora yubora olasiz (tunning boshida xabar keladi).",
        )

    if game.get("couple_mode"):
        partner_id = game.get("couple_of", {}).get(uid)
        if partner_id:
            pp = game["players"].get(partner_id)
            couple_key = tuple(sorted((uid, partner_id)))
            if couple_key not in game.setdefault("revealed_couples", set()):
                game["revealed_couples"].add(couple_key)
                bot.send_message(
                    chat_id,
                    f"💍 <b>Maxfiy juftlik fosh bo'ldi!</b> {mention(uid, p['name'])} va "
                    f"{mention(partner_id, pp['name']) if pp else 'sherigi'} — "
                    f"{p['role']} va {pp['role'] if pp else '?'}.",
                )
            if pp and pp.get("alive"):
                pp["alive"] = False
                bot.send_message(
                    chat_id,
                    f"💔 Sherigi {mention(uid, p['name'])} halok bo'lgani sababli, "
                    f"{mention(partner_id, pp['name'])} ham darhol o'yindan chiqdi!",
                )
                handle_death_side_effects(game, chat_id, partner_id)


def get_faction_teammates(game, uid):
    """Foydalanuvchining joriy o'yindagi yashirin 'jamoasi' a'zolarini qaytaradi:
      • ("mafia", [...]) — Don 🎩 + Mafia 🕶 (tirik bo'lganlari)
      • ("qonun", [...]) — Komissar 🕵️‍♂️ + Serjant 👮‍♂️ (tirik bo'lganlari)
      • (None, []) — jamoasi yo'q (yakka rol yoki Tinch aholi)"""
    p = game["players"].get(uid)
    if not p or not p["alive"]:
        return None, []
    role = p["role"]
    if team_of(role) == "mafia":
        mates = [u2 for u2, pp in game["players"].items()
                 if u2 != uid and pp["alive"] and team_of(pp["role"]) == "mafia"]
        return "mafia", mates
    if role in ("Komissar 🕵️‍♂️", "Serjant 👮‍♂️"):
        mates = [u2 for u2, pp in game["players"].items()
                 if u2 != uid and pp["alive"] and pp["role"] in ("Komissar 🕵️‍♂️", "Serjant 👮‍♂️")]
        return "qonun", mates
    return None, []


@bot.message_handler(commands=["jamoa", "adolat"])
def cmd_faction_chat(message):
    """💬 FAQAT shaxsiy chatda va faol o'yin ichida ishlaydi. Guruh buni
    KO'RMAYDI — o'z jamoadoshlaringizga (Mafiya: Don+Mafia — /jamoa, yoki
    Qonun: Komissar+Serjant — /adolat) bot orqali yashirin xabar yuboradi.
    Foydalanish: /jamoa xabar matni  yoki  /adolat xabar matni"""
    maybe_capture_owner(message.from_user)
    if message.chat.type != "private":
        return
    uid = message.from_user.id
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2 or not parts[1].strip():
        bot.send_message(
            message.chat.id,
            "Foydalanish:\n<code>/jamoa xabar matni</code> — Mafiya jamoasiga\n"
            "<code>/adolat xabar matni</code> — Qonun (Komissar+Serjant) jamoasiga",
        )
        return
    text = parts[1].strip()

    game = None
    for g in GAMES.values():
        if uid in g["players"] and g["players"][uid]["alive"]:
            game = g
            break
    if not game:
        bot.send_message(message.chat.id, "❌ Siz hozir hech qanday faol o'yinda emassiz.")
        return

    kind, mates = get_faction_teammates(game, uid)
    if kind is None or not mates:
        bot.send_message(message.chat.id, "❌ Sizda hozir bu jamoaviy chatdan foydalanish imkoni yo'q (jamoadoshingiz yo'q yoki rolingiz mos kelmaydi).")
        return

    label = "🕶 Mafiya jamoasi" if kind == "mafia" else "🕵️‍♂️👮‍♂️ Qonun jamoasi"
    sender_name = game["players"][uid]["name"]
    sent = sum(1 for mate_uid in mates if safe_send(mate_uid, f"{label} 💬 <b>{sender_name}:</b> {text}"))
    bot.send_message(
        message.chat.id,
        f"✅ Xabaringiz {sent} ta jamoadoshingizga yetkazildi." if sent else "❌ Hech kimga yetkazib bo'lmadi.",
    )


def wait_last_words(chat_id, uid):
    game = GAMES.get(chat_id)
    if not game:
        return
    game["last_words_wait"].add(uid)
    safe_send(uid, f"💀 Siz o'yindan chiqarildingiz. So'nggi so'zingizni aytish uchun sizda {LAST_WORDS_SECONDS} soniya vaqt bor. Shu yerga (DM'ga) yozing.")

    def timeout_check():
        g = GAMES.get(chat_id)
        if not g:
            return
        if uid in g.get("last_words_wait", set()):
            g["last_words_wait"].discard(uid)
            name = g["players"].get(uid, {}).get("name", "O'yinchi")
            bot.send_message(chat_id, f"🗣 <b>{mention(uid, name)}</b>ning so'nggi so'zi:\n{random.choice(DEAD_FUNNY_WORDS)}")

    t = threading.Timer(LAST_WORDS_SECONDS, timeout_check)
    t.daemon = True
    t.start()
    game["timers"].append(t)


@bot.message_handler(func=lambda m: m.chat.type == "private" and not (m.text or "").startswith("/"))
def private_message_router(message):
    maybe_capture_owner(message.from_user)
    # 💰 ELITE narx-tahrirlash kutilayotgan bo'lsa — BU yerda ushlanadi (pastdagi
    # boshqa @bot.message_handler emas, chunki bitta xabarga faqat BIRINCHI mos
    # kelgan handler ishlaydi — shu handler ro'yxatga birinchi olingan).
    if message.from_user.id in _ELITE_PRICE_EDIT_STATE:
        _handle_elite_price_input(message)
        return
    if message.from_user.id in _TUNE_EDIT_STATE:
        _handle_tune_setting_input(message)
        return
    for chat_id, game in list(GAMES.items()):
        if message.from_user.id in game.get("last_words_wait", set()):
            game["last_words_wait"].discard(message.from_user.id)
            uid = message.from_user.id
            name = game["players"][uid]["name"]
            bot.send_message(chat_id, f"🗣 <b>{mention(uid, name)}</b>ning so'nggi so'zi:\n«{message.text}»")
            return

    # 🐺🦅💍🕶 JAMODOSHLAR CHATI — o'yin davomida (tunda yoki kunduzi) bot orqali
    # HECH QANDAY buyruqsiz yozilgan oddiy matnli xabar, agar yuboruvchining
    # jamodoshi (jamoadoshi / turmush o'rtog'i / mafiya sherigi) bo'lsa, FAQAT
    # o'sha jamodoshlariga bot orqali yetkaziladi — boshqa hech kimga (guruhga
    # ham) ko'rinmaydi. Jamodoshi yo'q o'yinchilar uchun bu bo'lim hech narsa
    # qilmaydi (mavjud xatti-harakat o'zgarishsiz qoladi).
    if message.content_type == "text" and message.text:
        uid = message.from_user.id
        for chat_id, game in list(GAMES.items()):
            if game.get("phase") not in ("night", "day"):
                continue
            p = game["players"].get(uid)
            if not p or not p.get("alive"):
                continue
            _label, emblem, mates = ally_roster(game, uid)
            if not mates:
                continue
            sender_name = p["name"]
            for mate_uid, _mate_name in mates:
                safe_send(mate_uid, f"{emblem} <i>{sender_name} (jamodoshingiz):</i>\n{message.text}")
            return


@bot.message_handler(func=lambda m: m.chat.type in ("group", "supergroup") and not (m.text or "").startswith("/"))
def group_chat_moderation(message):
    """🔇 O'yin davomida guruh chatini nazorat qiladi — 3 ta rejimning
    HAMMASIDA (oddiy, 🐺🦅 Jamoaviy, 💍 Para) bir xilda ishlaydi, chunki
    bularning barchasi bitta o'yin motorida ishlaydi:
      • 🌙 Tunda — HECH KIM guruhda yoza olmaydi, yozgan xabar DARHOL,
        hech qanday kechikmasdan o'chiriladi.
      • ☀️ Kunduzi (va umuman o'yin davom etayotgan paytda) — o'yindan
        chiqib ketgan yoki hech qachon qo'shilmagan (o'ynamayotgan)
        foydalanuvchilarning xabarlari ham darhol o'chiriladi; faqat
        HOZIR tirik ishtirok etayotgan o'yinchilar kunduzi erkin yoza oladi.
    O'yin hali boshlanmagan yoki tugagan bo'lsa (phase == "waiting" yoki
    umuman o'yin yo'q) — guruh butunlay erkin, hech narsa o'chirilmaydi."""
    game = GAMES.get(message.chat.id)
    if not game or game.get("phase") not in ("night", "day"):
        return
    if not message.from_user:
        return
    if game["phase"] == "night":
        safe_delete(message)
        return
    p = game["players"].get(message.from_user.id)
    if not p or not p.get("alive"):
        safe_delete(message)


