# ================================================================================
#  📜 /geroy_tarix — "Geroy tarixi": foydalanuvchi (yoki reply qilingan boshqa
#  o'yinchi, FAQAT owner uchun) qaysi mahoratni necha marta ishlatgani haqida
#  statistik jamlanma. hero_ability_log jadvaliga asoslangan.
# ================================================================================

def build_hero_history_text(uid, display_name):
    with db_lock:
        cur.execute(
            "SELECT ability_name, COUNT(*), MAX(used_at) FROM hero_ability_log "
            "WHERE user_id=? GROUP BY ability_name ORDER BY COUNT(*) DESC",
            (uid,),
        )
        rows = cur.fetchall()
        cur.execute("SELECT COUNT(*) FROM hero_ability_log WHERE user_id=?", (uid,))
        total = cur.fetchone()[0]
    if not rows:
        return f"📜 <b>{esc(display_name)}</b> hali birorta geroy mahoratini ishlatmagan."
    lines = [f"📜 <b>{esc(display_name)} — Geroy tarixi</b>", f"Jami ishlatilgan: <b>{total}</b> marta\n"]
    for ability_name, count, last_used in rows:
        last_str = time.strftime("%d.%m.%Y %H:%M", time.localtime(last_used)) if last_used else "—"
        lines.append(f"• <b>{ability_name}</b> — {count} marta (oxirgi: {last_str})")
    return "\n".join(lines)


