def hero_game_start_reminder_text(uid):
    """🎮 O'yin boshida geroy egasiga yuboriladigan, aniq va tushunarli
    ko'rsatma matnini quradi — hozirgi darajada OCHIQ bo'lgan har bir mahorat
    uchun aniq "qanday ishlatiladi" ko'rsatkichi bilan."""
    hero = get_hero(uid)
    if not hero:
        return None
    unlocked = [a for a in hero_unlocked_abilities(uid) if a["unlocked"]]
    locked = [a for a in hero_unlocked_abilities(uid) if not a["unlocked"]]
    lines = [
        f"🦸 <b>Bu o'yinda sizda geroy bor: {hero['name']}!</b> (Daraja: {hero['level']}/{HERO_MAX_LEVEL})",
        "",
        "✅ <b>Shu o'yinda ishlatishingiz mumkin bo'lgan mahoratlar:</b>",
    ]
    if not unlocked:
        lines.append("<i>(hozircha hech qanday mahorat ochilmagan — /geroyim orqali darajangizni oshiring)</i>")
    for ab in unlocked:
        hint = HERO_ABILITY_USAGE_HINT.get(ab["key"], "/geroyim orqali ko'ring.")
        lines.append(f"• <b>{ab['name']}</b> — {hint}")
    if locked:
        lines.append("")
        lines.append("🔒 <b>Hali ochilmagan:</b> " + ", ".join(f"{a['name']} ({a['unlock']}-daraja)" for a in locked))
    lines.append("")
    lines.append("💡 To'liq boshqarish paneli: /geroyim")
    return "\n".join(lines)


def build_hero_panel(uid):
    """Geroy kartochkasi uchun (matn, tugmalar, rasm_yoli) qaytaradi — /geroyim, asosiy
    menyu tugmasi va darajani oshirishdan keyingi yangilanish uchun umumiy funksiya.
    SODDA VA TUSHUNARLI: har bir mahorat holati (✅ ochiq / 🔒 yopiq) BIR JOYDA — nomi,
    tavsifi va "qanday ishlatiladi" ko'rsatmasi birga — ko'rsatiladi (avvalgi versiyada
    bu ikki alohida ro'yxatga bo'linib, takrorlanib ketardi). Qo'lda ishlatiladigan
    mahoratlar uchun to'g'ridan-to'g'ri tugma beriladi, va tugma faqat ishlashi mumkin
    bo'lgan holatda (faol o'yin, kerakli bosqich, hali ishlatilmagan bo'lsa) ko'rsatiladi
    — shu bilan foydalanuvchi "bosdim-ishlamadi" holatiga kamroq duch keladi."""
    hero = get_hero(uid)
    if not hero:
        lines = [
            "🏆 <b>Sizda hali geroy yo'q</b>",
            "",
            "Geroy — o'yinda sizga haqiqiy ustunlik beradi. Tanlang va darhol sotib oling "
            "(💎 Olmos yoki ⭐ Stars bilan):",
            "",
        ]
        kb = types.InlineKeyboardMarkup()
        for hkey, h in HEROES.items():
            lines.append(f"<b>{h['name']}</b> — {h.get('rarity', 'Nodir')}")
            lines.append(f"<i>{h.get('desc', '')}</i>")
            for ab in h["abilities"]:
                lines.append(f"   {ab['unlock']}-daraja: {ab['name']}")
            lines.append("")
            kb.add(
                types.InlineKeyboardButton(f"Sotib olish — {hero_price(hkey, 'buy_diamond')} 💎", callback_data=f"herobuy|{hkey}|d"),
                types.InlineKeyboardButton(f"{hero_price(hkey, 'buy_stars')} ⭐", callback_data=f"herobuy|{hkey}|s"),
            )
        lines.append("🎁 Yoki 💎 Olmos do'konidan <b>🏆 Afsonaviy Sandiq</b> (110 💎) oling — "
                     "ichidan tasodifiy geroy chiqadi (juda kamdan-kam ✨ Afsonaviy ham).")
        return "\n".join(lines), kb, None

    level = hero["level"]
    chat_id_ig, game_ig = _find_active_game_for(uid)
    in_game = bool(game_ig and uid in game_ig["players"] and game_ig["players"][uid]["alive"])

    lines = [
        f"🏆 <b>{hero['name']}</b>  •  {HEROES.get(hero['key'], {}).get('rarity', 'Nodir')}",
        f"📅 Faol: <b>{hero['days_active']}</b> kundan beri",
        f"📊 Daraja: <code>{text_progress_bar(level, HERO_MAX_LEVEL)}</code>  ({level}/{HERO_MAX_LEVEL})",
    ]
    if hero.get("temp_until"):
        qolgan_soat = max(0, int((hero["temp_until"] - time.time()) // 3600))
        lines.append(f"⏳ <b>Vaqtinchalik geroy</b> — taxminan {qolgan_soat} soatdan keyin tugaydi")

    # 🎮 Holat — foydalanuvchi darhol tushunishi uchun: qo'lda ishlatiladigan
    # mahoratlar FAQAT faol o'yin ichida ishlaydi, shuni oldindan aniq aytib qo'yamiz.
    if in_game:
        phase_name = {"night": "🌙 Tun", "day": "☀️ Kun"}.get(game_ig["phase"], game_ig["phase"])
        lines.append(f"🎮 Holat: <b>faol o'yindasiz</b> (hozirgi bosqich: {phase_name})")
    else:
        lines.append("🎮 Holat: hozir faol o'yinda emassiz — qo'lda ishlatiladigan mahoratlar "
                      "faqat o'yin DAVOMIDA ishlaydi.")

    lines.append("")
    lines.append("✨ <b>Mahoratlar:</b>")
    kb = types.InlineKeyboardMarkup()
    unlocked_abilities = hero_unlocked_abilities(uid)  # 🔁 almashtirish holatini ham hisobga oladi
    for ab in unlocked_abilities:
        if ab["unlocked"]:
            if ab["value"] is not None:
                val = ab["value"]
                val_txt = f"{val*100:.0f}%" if val < 1 else f"{int(val)}"
                lines.append(f"\n✅ <b>{ab['name']}</b> — hozirgi kuchi: {val_txt}")
            else:
                lines.append(f"\n✅ <b>{ab['name']}</b>")
            lines.append(f"<i>{ab['desc']}</i>")
            hint = HERO_ABILITY_USAGE_HINT.get(ab["key"])
            if hint:
                lines.append(f"👉 {hint}")
        else:
            lines.append(f"\n🔒 <b>{ab['name']}</b> — {ab['unlock']}-darajada ochiladi")
            lines.append(f"<i>{ab['desc']}</i>")

    # 🕹 Qo'lda ishlatiladigan mahoratlar uchun tugmalar — faqat HAQIQATDA
    # ishlashi mumkin bo'lgan holatda ko'rsatiladi (bekorga bosilib, xato
    # chiqarib yubormasligi uchun).
    if in_game and any(a["key"] == "role_reveal_once" and a["unlocked"] for a in unlocked_abilities) \
            and uid not in game_ig.setdefault("hero_role_reveal_used", set()):
        kb.add(types.InlineKeyboardButton("🔍 Bashorat qilish", callback_data=f"herotarget|bashorat|{uid}"))
    if in_game and any(a["key"] == "compass_free" and a["unlocked"] for a in unlocked_abilities):
        kb.add(types.InlineKeyboardButton("🧭 Kompasni ishlatish", callback_data=f"herotarget|kompas|{uid}"))
    if in_game and any(a["key"] == "night_vision_auto" and a["unlocked"] for a in unlocked_abilities) \
            and game_ig["phase"] == "night":
        kb.add(types.InlineKeyboardButton("👁 Tungi nazarni ishlatish", callback_data=f"herouse|koz|{uid}"))
    if in_game and any(a["key"] == "diamond_trickle" and a["unlocked"] for a in unlocked_abilities) \
            and uid not in game_ig.setdefault("hero_income_claimed", set()):
        kb.add(types.InlineKeyboardButton("💎 Boylikni undirish", callback_data=f"herouse|daromad|{uid}"))
    if in_game and any(a["key"] == "guard_once" and a["unlocked"] for a in unlocked_abilities) \
            and game_ig["phase"] == "night" and uid not in game_ig.setdefault("hero_guard_used", set()):
        kb.add(types.InlineKeyboardButton("🕊 Himoya qilish", callback_data=f"herotarget|guard|{uid}"))
    if in_game and any(a["key"] == "gift_once" and a["unlocked"] for a in unlocked_abilities) \
            and uid not in game_ig.setdefault("hero_gift_used", set()):
        kb.add(types.InlineKeyboardButton("🎁 Sovg'a qilish", callback_data=f"herotarget|gift|{uid}"))

    # 🔁 Qobiliyatni almashtirish — o'yin davomida FAQAT 1 marta: hozir ochiq bo'lgan
    # bitta mahoratdan voz kechib, o'rniga o'z geroyingizning (hatto hali ochilmagan)
    # boshqa mahoratlaridan birini shu o'yin uchun vaqtincha ishlatishingiz mumkin.
    if HERO_SWAP_ENABLED and in_game and len(hero["abilities"]) >= 2:
        existing_swap = game_ig.setdefault("hero_ability_swap", {}).get(uid)
        if existing_swap:
            lines.append(f"\n🔁 Bu o'yin uchun almashtirilgan: <b>{existing_swap['from_name']}</b> → "
                          f"<b>{existing_swap['to_name']}</b> (vaqtincha)")
        else:
            lines.append("\n🔁 <b>O'yin davomida 1 marta</b> — bitta mahoratingizdan voz kechib, "
                          "o'rniga boshqasini vaqtincha ishlatishingiz mumkin.")
            kb.add(types.InlineKeyboardButton("🔁 Qobiliyatni almashtirish", callback_data=f"heroswap|start|{uid}"))

    _auto_on = hero_auto_enabled(uid)
    lines.append("\n🤖 <b>Avto-rejim:</b> " + ("✅ yoqilgan — himoya, tungi nazar va daromad o'zi ishlaydi."
                                              if _auto_on else "❌ o'chirilgan — qo'lda faollashtirasiz."))
    kb.add(types.InlineKeyboardButton(
        f"🤖 Avto-rejim: {'✅ Yoqilgan' if _auto_on else '❌ O‘chirilgan'}", callback_data=f"herotoggle|auto|{uid}"))

    cost = hero_level_up_cost(level, hero["key"])
    if cost is not None:
        stars_cost = hero_price(hero["key"], f"lv{level + 1}_stars")
        lines.append(f"\n⬆️ Keyingi darajaga: <b>{cost} 💎</b> yoki <b>{stars_cost} ⭐</b>")
        kb.add(
            types.InlineKeyboardButton(f"⬆️ Oshirish ({cost} 💎)", callback_data=f"herolvl|{uid}"),
            types.InlineKeyboardButton(f"{stars_cost} ⭐", callback_data=f"herolvlstars|{uid}"),
        )
    else:
        lines.append("\n🌟 Geroyingiz ENG YUQORI darajada!")

    kb.add(types.InlineKeyboardButton("📜 Mahorat tarixi", callback_data=f"herotarix|view|{uid}"))

    return "\n".join(lines), kb, hero_image_path(hero["key"])


def show_hero_panel(chat_id, uid, call=None):
    text, kb, image_path = build_hero_panel(uid)
    kb = with_back_button(kb)
    if image_path:
        try:
            with open(image_path, "rb") as photo:
                if call:
                    try:
                        bot.delete_message(call.message.chat.id, call.message.message_id)
                    except Exception:
                        pass
                bot.send_photo(chat_id, photo, caption=text, reply_markup=kb)
            return
        except Exception:
            pass
    if call:
        smart_render(call, text, kb)
    else:
        bot.send_message(chat_id, text, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("herouse|"))
@hero_safe("cb_hero_use (herouse|)")
def cb_hero_use(call):
    """🕹 Geroyim panelidagi tugmalar orqali qo'lda ishlatiladigan mahoratlar (👁 Tungi
    nazar, 💎 Boylik) — bosilganda darhol ishlaydi va natija shu yerda ko'rsatiladi."""
    maybe_capture_owner(call.from_user)
    _, kind, owner_id_s = call.data.split("|")
    owner_id = int(owner_id_s)
    uid = call.from_user.id
    if uid != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning geroyingiz emas.", show_alert=True)
        return
    if kind == "koz":
        ok, msg = do_geroy_koz(uid)
    elif kind == "daromad":
        ok, msg = do_geroy_daromad(uid)
    else:
        return
    bot.answer_callback_query(call.id, msg, show_alert=True)


@bot.callback_query_handler(func=lambda c: c.data.startswith("heroarm|"))
@hero_safe("cb_hero_arm (heroarm|)")
def cb_hero_arm(call):
    """🏆 O'yinchi geroy qobiliyatini (himoya/xalq himoyasi) QO'LDA faollashtiradi.
    Faollashtirilmasa, ushbu tur/kun uchun geroy hech qanday avtomatik ta'sir qilmaydi."""
    maybe_capture_owner(call.from_user)
    _, kind, chat_id_s = call.data.split("|")
    chat_id = int(chat_id_s)
    uid = call.from_user.id
    game = GAMES.get(chat_id)
    if not game or uid not in game["players"] or not game["players"][uid]["alive"]:
        bot.answer_callback_query(call.id, "❌ Bu tanlov endi amal qilmaydi.", show_alert=True)
        return
    if kind == "defense":
        if game["phase"] != "night":
            bot.answer_callback_query(call.id, "❌ Bu faqat tun davomida faollashtiriladi.", show_alert=True)
            return
        game.setdefault("hero_armed_defense", set()).add(uid)
        bot.answer_callback_query(call.id, "🛡 Geroy himoyasi shu tunga faollashtirildi!", show_alert=True)
        try:
            bot.edit_message_text("🛡✅ Geroy himoyasi shu tunga FAOLLASHTIRILDI.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
    elif kind == "voteshield":
        if game["phase"] != "day":
            bot.answer_callback_query(call.id, "❌ Bu faqat kunduzi faollashtiriladi.", show_alert=True)
            return
        game.setdefault("hero_armed_vote_shield", set()).add(uid)
        bot.answer_callback_query(call.id, "🗳 Xalq himoyasi shu kunga faollashtirildi!", show_alert=True)
        try:
            bot.edit_message_text("🗳✅ Xalq himoyasi shu kunga FAOLLASHTIRILDI.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass


# ================================================================================
#  🎯 Nishonga qaratilgan geroy mahoratlari (🔍 Bashorat, 🧭 Bepul kompas) —
#  "🦸 Geroyim" panelidagi tugma bosilganda, foydalanuvchiga SHAXSIY xabarda
#  (DM) tirik o'yinchilar ro'yxati chiqadi; birini tanlash orqali mahorat
#  darhol ishga tushadi.
# ================================================================================

@bot.callback_query_handler(func=lambda c: c.data.startswith("herotarget|"))
@hero_safe("cb_hero_target_start (herotarget|)")
def cb_hero_target_start(call):
    maybe_capture_owner(call.from_user)
    _, kind, owner_id_s = call.data.split("|")
    owner_id = int(owner_id_s)
    uid = call.from_user.id
    if uid != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning geroyingiz emas.", show_alert=True)
        return
    chat_id, game = find_active_game_for(uid)
    if not game:
        bot.answer_callback_query(call.id, "❌ Bu qobiliyat faqat faol o'yin davomida ishlaydi.", show_alert=True)
        return
    if kind == "bashorat":
        if not hero_has_ability(uid, "role_reveal_once"):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyat sizda yo'q.", show_alert=True)
            return
        if uid in game.setdefault("hero_role_reveal_used", set()):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyatingizni shu o'yin davomida allaqachon ishlatib bo'lgansiz.", show_alert=True)
            return
    elif kind == "kompas":
        if not hero_has_free_compass(uid):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyat sizda yo'q.", show_alert=True)
            return
    elif kind == "guard":
        if not hero_has_ability(uid, "guard_once"):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyat sizda yo'q.", show_alert=True)
            return
        if game["phase"] != "night":
            bot.answer_callback_query(call.id, "❌ Bu qobiliyat faqat TUN davomida ishlaydi.", show_alert=True)
            return
        if uid in game.setdefault("hero_guard_used", set()):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyatingizni shu o'yin davomida allaqachon ishlatib bo'lgansiz.", show_alert=True)
            return
    elif kind == "gift":
        if not hero_has_ability(uid, "gift_once"):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyat sizda yo'q.", show_alert=True)
            return
        if uid in game.setdefault("hero_gift_used", set()):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyatingizni shu o'yin davomida allaqachon ishlatib bo'lgansiz.", show_alert=True)
            return
    else:
        return
    # 🕊/🎁 — bu 2 mahorat o'zini ham nishon qilib tanlashga ruxsat beradi
    if kind in ("guard", "gift"):
        targets = [(pid, p["name"]) for pid, p in alive_players(game).items()]
    else:
        targets = [(pid, p["name"]) for pid, p in alive_players(game).items() if pid != uid]
    if not targets:
        bot.answer_callback_query(call.id, "❌ Tanlash uchun boshqa tirik o'yinchi yo'q.", show_alert=True)
        return
    kb = types.InlineKeyboardMarkup()
    for pid, name in targets:
        label_name = f"{name} (o'zim)" if pid == uid else name
        kb.add(types.InlineKeyboardButton(label_name, callback_data=f"herotargetpick|{kind}|{uid}|{pid}"))
    labels = {
        "bashorat": "🔍 Bashorat qilmoqchi bo'lgan o'yinchini tanlang:",
        "kompas": "🧭 Kompasni kimga qaratamiz?",
        "guard": "🕊 Bu tunga kimni himoya qilamiz?",
        "gift": "🎁 Sovg'ani kimga beramiz?",
    }
    label = labels.get(kind, "Tanlang:")
    ok = safe_send(uid, label, reply_markup=kb)
    if ok:
        bot.answer_callback_query(call.id, "📩 Tanlov shaxsiy xabaringizga yuborildi.", show_alert=True)
    else:
        bot.answer_callback_query(call.id, "❌ Sizga shaxsiy xabar yubora olmadim — botni DM'da /start bilan oching.", show_alert=True)


@bot.callback_query_handler(func=lambda c: c.data.startswith("herotargetpick|"))
@hero_safe("cb_hero_target_pick (herotargetpick|)")
def cb_hero_target_pick(call):
    maybe_capture_owner(call.from_user)
    _, kind, owner_id_s, target_id_s = call.data.split("|")
    owner_id, target_id = int(owner_id_s), int(target_id_s)
    uid = call.from_user.id
    if uid != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning tanlovingiz emas.", show_alert=True)
        return
    chat_id, game = find_active_game_for(uid)
    if not game or target_id not in game["players"] or not game["players"][target_id]["alive"]:
        bot.answer_callback_query(call.id, "❌ Bu tanlov endi amal qilmaydi.", show_alert=True)
        try:
            bot.edit_message_text("❌ Bu tanlov muddati o'tdi.", call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        return
    hero = get_hero(uid)
    target_name = game["players"][target_id]["name"]
    if kind == "bashorat":
        if uid in game.setdefault("hero_role_reveal_used", set()):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyatingizni allaqachon ishlatib bo'lgansiz.", show_alert=True)
            return
        game["hero_role_reveal_used"].add(uid)
        target_role = game["players"][target_id]["role"]
        result_text = f"🔍 Geroyingiz bashorat qildi: <b>{esc(target_name)}</b>ning aniq roli — <b>{target_role}</b>!\n(Bu qobiliyat endi sarflandi.)"
        ability_name = "🔍 Chuqur bashorat"
    elif kind == "kompas":
        ok, msg = do_kompas(chat_id, game, uid, target_id, target_name)
        if not ok:
            bot.answer_callback_query(call.id, msg, show_alert=True)
            return
        result_text = msg
        ability_name = "🧭 Cheksiz kompas"
    elif kind == "guard":
        if game["phase"] != "night":
            bot.answer_callback_query(call.id, "❌ Bu qobiliyat faqat TUN davomida ishlaydi.", show_alert=True)
            return
        if uid in game.setdefault("hero_guard_used", set()):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyatingizni allaqachon ishlatib bo'lgansiz.", show_alert=True)
            return
        game["hero_guard_used"].add(uid)
        game.setdefault("night_protected", set()).add(target_id)
        self_note = " (o'zingizni tanladingiz)" if target_id == uid else ""
        result_text = f"🕊 <b>{esc(target_name)}</b>{self_note} shu tunga to'liq himoyaga olindi!\n(Bu qobiliyat endi sarflandi.)"
        ability_name = "🕊 Himoyachi tumor"
        safe_send(target_id, "🕊 Kimningdir geroy mahorati bu tunga sizni himoya qilmoqda — tinch uxlashingiz mumkin!") if target_id != uid else None
    elif kind == "gift":
        if uid in game.setdefault("hero_gift_used", set()):
            bot.answer_callback_query(call.id, "❌ Bu qobiliyatingizni allaqachon ishlatib bo'lgansiz.", show_alert=True)
            return
        game["hero_gift_used"].add(uid)
        if random.random() < 0.5:
            amount = random.randint(1, 2)
            add_balance(target_id, diamond=amount)
            gift_text = f"{amount} 💎 Olmos"
        else:
            amount = random.randint(10, 40)
            add_balance(target_id, dollar=amount)
            gift_text = f"${amount}"
        self_note = " (o'zingizga)" if target_id == uid else ""
        result_text = f"🎁 <b>{esc(target_name)}</b>{self_note}ga <b>{gift_text}</b> sovg'a qildingiz!\n(Bu qobiliyat endi sarflandi.)"
        ability_name = "🎁 Sehrli sovg'a"
        if target_id != uid:
            safe_send(target_id, f"🎁 Kimningdir geroy mahorati sizga sovg'a yubordi: <b>{gift_text}</b>!")
    else:
        return
    bot.answer_callback_query(call.id, "✅ Bajarildi!")
    try:
        bot.edit_message_text(result_text, call.message.chat.id, call.message.message_id)
    except Exception:
        safe_send(uid, result_text)
    announce_hero_ability_use(chat_id, hero["name"], ability_name, uid=uid, hero_key=hero["key"])


# ================================================================================
#  🔁 QOBILIYATNI ALMASHTIRISH — o'yin davomida BIR MARTA, o'z geroyingizning
#  hozir OCHIQ bo'lgan bitta mahoratidan voz kechib, o'rniga (hali ochilmagan
#  bo'lsa ham) boshqa mahoratlardan birini SHU O'YIN uchun vaqtincha olasiz.
# ================================================================================

@bot.callback_query_handler(func=lambda c: c.data.startswith("heroswap|"))
@hero_safe("cb_hero_swap (heroswap|)")
def cb_hero_swap(call):
    maybe_capture_owner(call.from_user)
    parts = call.data.split("|")
    action = parts[1]
    owner_id = int(parts[2])
    uid = call.from_user.id
    if uid != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning geroyingiz emas.", show_alert=True)
        return
    chat_id, game = find_active_game_for(uid)
    if not game:
        bot.answer_callback_query(call.id, "❌ Bu faqat faol o'yin davomida ishlatiladi.", show_alert=True)
        return
    hero = get_hero(uid)
    if not hero:
        bot.answer_callback_query(call.id, "❌ Sizda geroy yo'q.", show_alert=True)
        return
    if uid in game.setdefault("hero_ability_swap", {}):
        bot.answer_callback_query(call.id, "❌ Bu huquqni shu o'yin uchun allaqachon ishlatib bo'lgansiz.", show_alert=True)
        return

    if action == "start":
        unlocked_now = [a for a in hero_unlocked_abilities(uid) if a["unlocked"]]
        if not unlocked_now:
            bot.answer_callback_query(call.id, "❌ Hozircha voz kechadigan ochiq mahoratingiz yo'q.", show_alert=True)
            return
        kb = types.InlineKeyboardMarkup()
        for ab in unlocked_now:
            kb.add(types.InlineKeyboardButton(ab["name"], callback_data=f"heroswap|from|{uid}|{ab['key']}"))
        bot.answer_callback_query(call.id)
        safe_send(uid, "🔁 Qaysi mahoratingizdan voz kechmoqchisiz?", reply_markup=kb)

    elif action == "from":
        from_key = parts[3]
        others = [a for a in hero["abilities"] if a["key"] != from_key]
        if not others:
            bot.answer_callback_query(call.id, "❌ Almashtirish uchun boshqa mahorat yo'q.", show_alert=True)
            return
        kb = types.InlineKeyboardMarkup()
        for ab in others:
            kb.add(types.InlineKeyboardButton(ab["name"], callback_data=f"heroswap|to|{uid}|{from_key}|{ab['key']}"))
        bot.answer_callback_query(call.id)
        safe_send(uid, "🔁 O'rniga (shu o'yin uchun vaqtincha) qaysi mahoratni olmoqchisiz?", reply_markup=kb)

    elif action == "to":
        from_key, to_key = parts[3], parts[4]
        from_ab = next((a for a in hero["abilities"] if a["key"] == from_key), None)
        to_ab = next((a for a in hero["abilities"] if a["key"] == to_key), None)
        if not from_ab or not to_ab:
            bot.answer_callback_query(call.id, "❌ Xatolik yuz berdi, qayta urinib ko'ring.", show_alert=True)
            return
        game["hero_ability_swap"][uid] = {
            "from": from_key, "to": to_key,
            "from_name": from_ab["name"], "to_name": to_ab["name"],
        }
        bot.answer_callback_query(call.id, "✅ Almashtirildi!", show_alert=True)
        safe_send(uid, f"🔁 <b>{from_ab['name']}</b> mahoratingizdan shu o'yin uchun voz kechdingiz, "
                        f"o'rniga <b>{to_ab['name']}</b> vaqtincha faollashtirildi!")
        announce_hero_ability_use(chat_id, hero["name"], f"🔁 Qobiliyat almashtirildi ({to_ab['name']})", uid=uid, hero_key=hero["key"])


