def _refresh_hero_panel_message(call):
    try:
        text, kb, _ = build_hero_panel(call.from_user.id)
        kb = with_back_button(kb)
        if call.message.photo:
            bot.edit_message_caption(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
        else:
            bot.edit_message_text(text, call.message.chat.id, call.message.message_id, reply_markup=kb)
    except Exception:
        pass


@bot.callback_query_handler(func=lambda c: c.data.startswith("herobuy|"))
@hero_safe("cb_hero_buy (herobuy|)")
def cb_hero_buy(call):
    maybe_capture_owner(call.from_user)
    try:
        _, hkey, how = call.data.split("|")
    except Exception:
        bot.answer_callback_query(call.id)
        return
    uid = call.from_user.id
    if hkey not in HEROES or how not in ("d", "s"):
        bot.answer_callback_query(call.id, "❌ Noto'g'ri tanlov.", show_alert=True)
        return
    if get_hero(uid):
        bot.answer_callback_query(call.id, "❌ Sizda allaqachon geroy bor.", show_alert=True)
        return
    if how == "d":
        price = hero_price(hkey, "buy_diamond")
        with db_lock:
            cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (price, uid, price))
            paid = cur.rowcount > 0
            conn.commit()
        if not paid:
            bot.answer_callback_query(call.id, f"❌ Yetarli olmos yo'q ({price} 💎 kerak).", show_alert=True)
            return
        if not _grant_hero(uid, hkey):
            add_balance(uid, diamond=price)  # geroy shu orada berilgan — pul qaytariladi
            bot.answer_callback_query(call.id, "❌ Sizda allaqachon geroy bor.", show_alert=True)
            return
        bot.answer_callback_query(call.id, f"🎉 {HEROES[hkey]['name']} endi sizniki!", show_alert=True)
        _refresh_hero_panel_message(call)
    else:
        stars = hero_price(hkey, "buy_stars")
        try:
            bot.send_invoice(
                call.message.chat.id,
                title=HEROES[hkey]["name"],
                description=f"{HEROES[hkey]['name']} geroyini sotib olish ({stars} ⭐)",
                invoice_payload=f"herobuy_{uid}_{hkey}",
                provider_token="",
                currency="XTR",
                prices=[types.LabeledPrice(label=HEROES[hkey]["name"], amount=stars)],
            )
            bot.answer_callback_query(call.id)
        except Exception:
            bot.answer_callback_query(call.id, "❌ To'lov tizimida xatolik. Keyinroq urinib ko'ring.", show_alert=True)


