@bot.message_handler(commands=["geroy_vaqtincha"])
@hero_safe("cmd_geroy_vaqtincha (/geroy_vaqtincha)")
def cmd_geroy_vaqtincha(message):
    """👑 Faqat bot egasi — istalgan foydalanuvchiga geroyni MA'LUM MUDDATGA
    (necha kunga) beradi. Muddat tugagach geroy avtomatik olib qo'yiladi.
    Foydalanish: kimningdir xabariga reply qilib /geroy_vaqtincha <kalit> <kun_soni>."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = message.text.split()
    if (not message.reply_to_message or len(parts) != 3
            or parts[1].lower() not in HEROES or not parts[2].isdigit() or int(parts[2]) <= 0):
        keys = ", ".join(HEROES.keys())
        bot.send_message(
            message.chat.id,
            "Foydalanish: kimningdir xabariga reply qilib "
            "<code>/geroy_vaqtincha &lt;kalit&gt; &lt;kun_soni&gt;</code>\n"
            f"Mavjud kalitlar: {keys}",
        )
        return
    hero_key = parts[1].lower()
    days = int(parts[2])
    until = time.time() + days * 86400
    target = message.reply_to_message.from_user
    user_dict(target.id, target.first_name)
    with db_lock:
        cur.execute(
            "INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at, temp_until) VALUES (?, ?, 1, ?, ?)",
            (target.id, hero_key, time.time(), until),
        )
        conn.commit()
    hero = HEROES[hero_key]
    tugash_sana = time.strftime("%d.%m.%Y %H:%M", time.localtime(until))
    bot.send_message(
        message.chat.id,
        f"👑 {mention(target.id, target.first_name)}ga <b>{hero['name']}</b> geroyi "
        f"<b>{days} kunga</b> (tugash: {tugash_sana}) berildi!",
    )
    safe_send(
        target.id,
        f"🏆 Bot egasi sizga <b>{hero['name']}</b> geroyini <b>{days} kunga</b> in'om qildi! "
        f"Muddat: <b>{tugash_sana}</b> gacha. /geroyim orqali ko'ring.",
    )


