@bot.callback_query_handler(func=lambda c: c.data.startswith("profrolestats|"))
def cb_profile_role_stats(call):
    maybe_capture_owner(call.from_user)
    try:
        owner_id = int(call.data.split("|")[1])
    except Exception:
        bot.answer_callback_query(call.id)
        return
    if call.from_user.id != owner_id:
        bot.answer_callback_query(call.id, "❌ Bu sizning profilingiz emas.", show_alert=True)
        return
    stats = role_stats_of(owner_id)
    if not stats:
        bot.answer_callback_query(call.id, "📊 Siz hali birorta o'yinni yakunlamagansiz.", show_alert=True)
        return
    lines = ["📊 <b>Rol bo'yicha statistika</b>", ""]
    for r in stats[:15]:
        rate = f"{r['wins'] / r['games'] * 100:.0f}%"
        lines.append(f"{r['role']} — {r['games']} o'yin, {r['wins']} g'alaba ({rate})")
    bot.answer_callback_query(call.id)
    smart_render(call, "\n".join(lines), with_back_button())


# ================================================================================
#  📦 INVENTAR (qoshimchakod10.py g'oyasi — endi haqiqiy DB "inventory" ustunidan)
# ================================================================================

def show_inventory(chat_id, uid, call=None):
    """📦 SODDA VA TUSHUNARLI inventar: har bir buyum alohida tugma, bosilganda
    tavsifi va (mavjud bo'lsa) ishlatish/yoqish-o'chirish tugmasi chiqadi."""
    u = user_dict(uid)
    try:
        items = json.loads(u["inventory"] or "[]")
    except Exception:
        items = []
    ch = get_charges(uid)
    voucher_count = len(ch.get("osh_vouchers", []))
    hero = get_hero(uid)

    if not items and voucher_count == 0 and not hero:
        empty_text = "📦 Sizning inventaringiz hozircha bo'sh.\n🛒 Do'kondan buyum sotib oling — /market"
        if call:
            smart_render(call, empty_text, with_back_button())
        else:
            bot.send_message(chat_id, empty_text, reply_markup=with_back_button())
        return

    counts = {}
    for it in items:
        counts[it] = counts.get(it, 0) + 1

    kb = types.InlineKeyboardMarkup()
    lines = ["📦 <b>SIZNING INVENTARINGIZ</b>", "", "Ishlatish/yoqish uchun buyumni bosing:", ""]

    if hero:
        lines.append(f"🏆 {hero['name']} — {hero['level']}-lvl")
        kb.add(types.InlineKeyboardButton(f"🏆 {hero['name']}", callback_data=f"menu|hero"))

    for name, n in counts.items():
        shopkey = ITEM_NAME_TO_SHOPKEY.get(name)
        count_part = f" ({n} ta)" if n > 1 else ""
        # ⚙️ AVTOMATIK YOQIB/O'CHIRIB QO'YILADIGAN buyumlar uchun — endi
        # inventar RO'YXATINING O'ZIDA ✅ FAOL / ⛔ O'CHIQ holati bir qarashda
        # ko'rinadi, va buyumga bosish DARHOL yoqadi/o'chiradi (qo'shimcha
        # "tafsilot" bosqichi kerak emas).
        charge_key = None
        charges_left = None
        if shopkey:
            _shop_cat, _shop_key = shopkey
            _, _cat_items = SHOP_CATEGORIES[_shop_cat]
            _item_def = _cat_items.get(_shop_key, {})
            charge_key = _item_def.get("charge_key")
            # ⚠️ ZAXIRASI TUGAB QOLAYOTGAN buyumlar uchun ogohlantirish —
            # faqat "charge" rejimidagi (sanoqli marta ishlatiladigan)
            # buyumlarda haqiqiy qolgan miqdorni ko'rsatamiz.
            if charge_key and _item_def.get("mode") == "charge":
                charges_left = get_charges(uid).get(charge_key, 0)
        low_stock_warn = ""
        if charges_left == 1:
            low_stock_warn = " ⚠️ (oxirgi 1 ta qoldi!)"
        if charge_key and charge_key in TOGGLABLE_ITEMS:
            state = "✅ FAOL" if is_item_active(uid, charge_key) else "⛔ O'CHIQ"
            lines.append(f"• {name}{count_part} — {state}{low_stock_warn}")
            kb.add(types.InlineKeyboardButton(f"{name}{count_part} — {state}{low_stock_warn}", callback_data=f"invtoggle|{charge_key}"))
        elif shopkey:
            label = f"{name}{count_part}{low_stock_warn}"
            lines.append(f"• {name}{count_part}{low_stock_warn}")
            kb.add(types.InlineKeyboardButton(label, callback_data=f"invitem|{shopkey[0]}|{shopkey[1]}"))
        else:
            label = f"{name}{count_part}"
            lines.append(f"• {name}{count_part}")
            kb.add(types.InlineKeyboardButton(label, callback_data="invitem_noop"))

    if voucher_count:
        lines.append(f"• 🥘 Tortiq qilinadigan osh — {voucher_count} ta")
        kb.add(types.InlineKeyboardButton(f"🥘 Osh tortiqlari ({voucher_count} ta)", callback_data="invitem_osh_info"))

    kb = with_back_button(kb)
    text = "\n".join(lines)
    if call:
        smart_render(call, text, kb)
    else:
        bot.send_message(chat_id, text, reply_markup=kb)


