def with_back_button(kb=None):
    """🔙 Istalgan inline klaviaturaga pastiga "Bosh menyu" tugmasini qo'shadi
    (kb bo'lmasa, yangisini yaratadi) — foydalanuvchi hech qachon biror
    bo'limda "qolib ketmasligi", har doim bitta bosish bilan bosh menyuga
    qaytishi uchun. Barcha menyu ekranlarida shu funksiya ishlatiladi."""
    if kb is None:
        kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("🔙 Bosh menyu", callback_data="menu|main_back"))
    return kb


def smart_render(call, text, reply_markup=None, **kwargs):
    """📱 "Jonli panel": menyu bosilganda YANGI xabar yubormaydi va eski
    xabarni o'chirib-qayta yaratmaydi — ekran JOYIDA (edit_message_text)
    silliq almashadi, xuddi referens botdagi kabi. Faqat texnik jihatdan
    tahrirlab bo'lmasa (masalan eski xabar RASM bo'lsa, yoki xabar juda
    eski/o'chirilgan bo'lsa) — chekinib, eskisini o'chirib yangisini
    yuboradi, shunda foydalanuvchi hech qachon xatolik ko'rmaydi.
    **kwargs — disable_web_page_preview kabi qo'shimcha parametrlarni
    send_message/edit_message_text'ga uzatish uchun."""
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    try:
        bot.edit_message_text(text, chat_id, msg_id, reply_markup=reply_markup, **kwargs)
        return
    except Exception as e:
        if "message is not modified" in str(e).lower():
            try:
                bot.edit_message_reply_markup(chat_id, msg_id, reply_markup=reply_markup)
            except Exception:
                pass
            return
    try:
        bot.delete_message(chat_id, msg_id)
    except Exception:
        pass
    bot.send_message(chat_id, text, reply_markup=reply_markup, **kwargs)


def smart_render_photo(call, photo, caption, reply_markup=None):
    """📱 smart_render'ning RASMLI ekranlar (masalan bosh menyu) uchun
    varianti — edit_message_media orqali joyida almashtiradi, faqat
    imkonsiz bo'lsagina o'chirib-qayta yuboradi."""
    chat_id = call.message.chat.id
    msg_id = call.message.message_id
    try:
        media = types.InputMediaPhoto(photo, caption=caption)
        bot.edit_message_media(media, chat_id, msg_id, reply_markup=reply_markup)
        return
    except Exception:
        pass
    try:
        bot.delete_message(chat_id, msg_id)
    except Exception:
        pass
    bot.send_photo(chat_id, photo, caption=caption, reply_markup=reply_markup)


@bot.callback_query_handler(func=lambda c: c.data.startswith("menu|"))
def cb_menu(call):
    maybe_capture_owner(call.from_user)
    _, action = call.data.split("|")
    uid = call.from_user.id

    # 🖼 "Jonli panel": navigatsiya endi smart_render/smart_render_photo orqali
    # ekranni JOYIDA (edit) almashtiradi — pastdagi har bir bo'lim shu funksiyalarni
    # chaqiradi. Faqat edit qilib bo'lmaydigan holatlar (masalan bir nechta
    # bo'lakka bo'lingan uzun matn) uchun alohida o'chirish qo'llaniladi.

    if action == "main_back":
        THERON_CHAT_MODE.discard(uid)  # 🔙 bosh menyuga qaytilganda Theron suhbat rejimi tugaydi
        smart_render_photo(
            call,
            MAIN_PHOTO,
            caption=(
                f"🌙 <b>Hunter Mafia</b> — bosh menyu\n\n"
                "Kerakli bo'limni tanlang 👇"
            ),
            reply_markup=get_main_menu(None, uid),
        )
        bot.answer_callback_query(call.id)
        return

    if action == "roles":
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        lines = ["🎭 <b>Hunter Mafia — 35 ta rol</b>\n"]
        for role, desc in ROLES_INFO.items():
            lines.append(f"<b>{role}</b> — {desc}")
        text = "\n".join(lines)
        chunks = [text[i:i + 3500] for i in range(0, len(text), 3500)]
        for i, chunk in enumerate(chunks):
            is_last = (i == len(chunks) - 1)
            bot.send_message(call.message.chat.id, chunk, reply_markup=with_back_button() if is_last else None)
