# ================================================================================
#  🎭 v8 — ROLLAR DO'KONI: istalgan rolni to'g'ridan-to'g'ri sotib olish
# ================================================================================
# Foydalanuvchi rolni tanlab sotib oladi → "chipta" beriladi → keyingi safar
# /join qilganda (istalgan guruhda) chipta AVTOMATIK ishlatiladi va o'sha
# o'yinda aynan shu rol beriladi (mavjud `forced_roles` mexanizmi orqali —
# o'zgartirilmadi, faqat ustiga qurildi). Bir vaqtda faqat bitta chipta bo'lishi
# mumkin; yangisini sotib olish eskisini ALMASHTIRADI (pul qaytarilmaydi —
# xarid tugmasi bosishdan oldin buni ochiq ogohlantiradi).
ROLE_SHOP_TIERS = {
    "core":  {"label": "Asosiy", "diamond": 12, "stars": 34, "desc_tail": "— o'yinning tayanch rollaridan biri."},
    "mafia": {"label": "Mafiya", "diamond": 20, "stars": 56, "desc_tail": "— qorong'u tomonda kuch va hiyla."},
    "solo":  {"label": "Mustaqil", "diamond": 25, "stars": 70, "desc_tail": "— hech kimga bog'liq bo'lmagan o'z yo'lingiz."},
}
ROLE_SHOP_PRICE_OVERRIDES = {
    "Don 🎩": 30, "Qotil 🗡": 35, "Manyak 🔪": 32, "Yollanma qotil 🔫": 32, "Joker 🤡": 30,
}  # 💎 ayniqsa mashhur/kuchli rollar — biroz qimmatroq


def _role_shop_tier(role):
    if role in MAFIA_ROLES:
        return "mafia"
    if role in INDEPENDENT_ROLES or role not in CORE_ROLES and role not in MAFIA_ROLES and role != "Tinch aholi 👨‍👩‍👧‍👦":
        return "solo"
    return "core"


def role_shop_catalog():
    """[{role, tier, diamond, stars, desc}] — 'Tinch aholi' bundan mustasno (u tasodifiy ham berilmaydi)."""
    out = []
    for role in ALL_ROLES:
        if role == "Tinch aholi 👨‍👩‍👧‍👦":
            continue
        tier = _role_shop_tier(role)
        t = ROLE_SHOP_TIERS[tier]
        diamond = ROLE_SHOP_PRICE_OVERRIDES.get(role, t["diamond"])
        stars = diamond * DIAMOND_STARS_RATE
        out.append({"role": role, "tier": tier, "tier_label": t["label"], "diamond": diamond, "stars": stars,
                    "desc": f"{ROLES_INFO.get(role, '')} {t['desc_tail']}".strip()})
    return out


def role_ticket_get(uid):
    return get_charges(uid).get("role_ticket") or None


def role_ticket_buy(uid, role):
    if role not in ALL_ROLES or role == "Tinch aholi 👨‍👩‍👧‍👦":
        return False, "Bunday rol yo'q.", 0
    price = next((r["diamond"] for r in role_shop_catalog() if r["role"] == role), None)
    if price is None:
        return False, "Bunday rol yo'q.", 0
    with db_lock:
        cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (price, uid, price))
        paid = cur.rowcount > 0
        conn.commit()
    if not paid:
        return False, f"Yetarli olmos yo'q ({price} 💎 kerak).", price
    ch = get_charges(uid)
    ch["role_ticket"] = role
    set_charges(uid, ch)
    return True, f"🎭 Chiptangiz tayyor: keyingi o'yinda <b>{role}</b> siz bo'lasiz!", price


def role_ticket_cancel(uid):
    ch = get_charges(uid)
    role = ch.pop("role_ticket", None)
    if not role:
        return False, "Sizda faol chipta yo'q."
    set_charges(uid, ch)
    add_balance(uid, diamond=next((r["diamond"] for r in role_shop_catalog() if r["role"] == role), 0))
    return True, f"↩️ Chipta bekor qilindi, {next((r['diamond'] for r in role_shop_catalog() if r['role'] == role), 0)} 💎 qaytarildi."


def _apply_role_ticket_on_join(uid, chat_id):
    """do_join muvaffaqiyatli bo'lgach chaqiriladi: chiptasi bo'lsa, shu o'yinga forced_roles orqali bog'laydi."""
    role = role_ticket_get(uid)
    if not role:
        return
    game = GAMES.get(chat_id)
    if not game:
        return
    game.setdefault("forced_roles", {})[uid] = role
    ch = get_charges(uid)
    ch.pop("role_ticket", None)
    set_charges(uid, ch)
    safe_send(uid, f"🎭 Chiptangiz ishlatildi: bu o'yinda <b>{role}</b> siz bo'lasiz!")


def _role_shop_kb(uid):
    ticket = role_ticket_get(uid)
    kb = types.InlineKeyboardMarkup(row_width=1)
    if ticket:
        kb.add(types.InlineKeyboardButton(f"↩️ Chiptani bekor qilish ({ticket})", callback_data="roleshop|cancel"))
    for key, t in ROLE_SHOP_TIERS.items():
        kb.add(types.InlineKeyboardButton(f"— {t['label']} rollar —", callback_data=f"roleshop|tier|{key}"))
    return kb


def _role_shop_text(uid):
    ticket = role_ticket_get(uid)
    lines = ["🎭✨ <b>ROLLAR DO'KONI</b> ✨🎭", "━━━━━━━━━━━━━━━━━━", "",
             "Istalgan rolni tanlang — keyingi o'yiningizda aynan o'sha rol sizga beriladi!"]
    if ticket:
        lines += ["", f"🎟 Faol chiptangiz: <b>{ticket}</b> — /join qilishingiz bilan ishga tushadi."]
    lines += ["", "Toifani tanlang:"]
    return "\n".join(lines)


@bot.message_handler(commands=["rol_dokoni", "rollar_dokoni"])
def cmd_role_shop(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    user_dict(uid, message.from_user.first_name)
    bot.send_message(message.chat.id, _role_shop_text(uid), reply_markup=_role_shop_kb(uid))


@bot.callback_query_handler(func=lambda c: c.data.startswith("roleshop|"))
def cb_role_shop(call):
    maybe_capture_owner(call.from_user)
    uid = call.from_user.id
    user_dict(uid, call.from_user.first_name)
    parts = call.data.split("|")
    action = parts[1]
    if action == "cancel":
        ok, msg = role_ticket_cancel(uid)
        bot.answer_callback_query(call.id, msg, show_alert=True)
        smart_render(call, _role_shop_text(uid), _role_shop_kb(uid))
        return
    if action == "tier" and len(parts) > 2:
        tier = parts[2]
        cat = [r for r in role_shop_catalog() if r["tier"] == tier]
        kb = types.InlineKeyboardMarkup(row_width=1)
        for r in cat:
            kb.add(types.InlineKeyboardButton(f"{r['role']} — {r['diamond']} 💎", callback_data=f"roleshop|buy|{r['role']}"))
        kb.add(types.InlineKeyboardButton("🔙 Toifalarga", callback_data="roleshop|home"))
        title = ROLE_SHOP_TIERS[tier]["label"]
        text = f"🎭 <b>{title} rollar</b>\n\nRolni tanlang — tavsifini va narxini ko'rasiz."
        bot.answer_callback_query(call.id)
        smart_render(call, text, kb)
        return
    if action == "home":
        bot.answer_callback_query(call.id)
        smart_render(call, _role_shop_text(uid), _role_shop_kb(uid))
        return
    if action == "buy" and len(parts) > 2:
        role = "|".join(parts[2:])   # rol nomida ham | belgisi bo'lmaydi, lekin xavfsizlik uchun
        info = next((r for r in role_shop_catalog() if r["role"] == role), None)
        if not info:
            bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
            return
        ticket = role_ticket_get(uid)
        if ticket == role:
            bot.answer_callback_query(call.id, "✅ Bu rol uchun chiptangiz allaqachon bor.", show_alert=True)
            return
        kb = types.InlineKeyboardMarkup(row_width=1)
        kb.add(types.InlineKeyboardButton(f"✅ Ha, {info['diamond']} 💎 ga sotib olaman", callback_data=f"roleshop|confirm|{role}"))
        kb.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data=f"roleshop|tier|{info['tier']}"))
        warn = " (eski chiptangiz almashadi, puli qaytmaydi!)" if ticket else ""
        bot.answer_callback_query(call.id)
        smart_render(call, f"🎭 <b>{role}</b>\n\n{esc(info['desc'])}\n\n💎 Narxi: <b>{info['diamond']}</b>{warn}", kb)
        return
    if action == "confirm" and len(parts) > 2:
        role = "|".join(parts[2:])
        ok, msg, _price = role_ticket_buy(uid, role)
        bot.answer_callback_query(call.id, msg if not ok else "🎉 Xarid muvaffaqiyatli!", show_alert=True)
        smart_render(call, _role_shop_text(uid), _role_shop_kb(uid))
        return
    bot.answer_callback_query(call.id)


