def _spin_coin_wheel(uid):
    """🎰 Coin Baxt G'ildiragi — sotib olingan uid HAR DOIM biror mukofot yutadi.
    Ehtimollar: kichik pul (ko'p uchraydi) → o'rtacha → nodir (kamdan-kam) → JACKPOT (juda kam)."""
    roll = random.random() * 100
    if roll < 45:
        amt = random.randint(80, 220)
        add_balance(uid, dollar=amt)
        return f"💵 Chiqdi: <b>{amt}$</b> Dollar!"
    if roll < 75:
        amt = random.randint(3, 8)
        add_balance(uid, diamond=amt)
        return f"💎 Chiqdi: <b>{amt}</b> Olmos!"
    if roll < 92:
        add_shield(uid, 1)
        return "🛡 Chiqdi: +1 Himoya (shield)!"
    if roll < 99:
        role = random.choice([r for r in ALL_ROLES if r != "Tinch aholi 👨‍👩‍👧‍👦"])
        ch = get_charges(uid)
        ch["role_ticket"] = role
        set_charges(uid, ch)
        return f"🎭 <b>JACKPOT!</b> Bepul rol chiptasi: keyingi o'yinda <b>{role}</b> bo'lasiz!"
    if get_hero(uid):
        add_balance(uid, diamond=150)
        return "🏆 <b>SUPER JACKPOT!</b> Sizda allaqachon geroy bo'lgani uchun o'rniga <b>150 💎</b> Olmos berildi!"
    hero_key = roll_hero()
    with db_lock:
        cur.execute("INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at) VALUES (?, ?, 1, ?)", (uid, hero_key, time.time()))
        conn.commit()
    hero = HEROES[hero_key]
    return f"🏆🎉 <b>SUPER JACKPOT!!!</b> Sizga bepul GEROY tushdi: <b>{hero['name']}</b>! /geroyim orqali ko'ring."


def _perform_shop_purchase(uid, first_name, cat, key):
    """🛒 Do'kondan xarid qilish — markazlashtirilgan funksiya (Telegram tugmasi VA
    Mini App'dan kelgan /start chuqur havolasi ORQALI bir xil ishlatiladi)."""
    _, items = SHOP_CATEGORIES[cat]
    item = items.get(key)
    if not item:
        return False, "❌ Bunday buyum topilmadi."
    u = user_dict(uid, first_name)
    balance = u[item["currency"]]

    if balance < item["price"]:
        return False, "❌ Balansingiz yetarli emas!"

    if item["currency"] == "dollar":
        add_balance(uid, dollar=-item["price"])
    elif item["currency"] == "diamond":
        add_balance(uid, diamond=-item["price"])
    else:
        add_balance(uid, coin=-item["price"])

    mode = item["mode"]
    result_note = ""
    if mode == "shield":
        add_shield(uid, 1)
        result_note = "🛡 Himoya (+1 shield) hisobingizga qo'shildi."
    elif mode == "gamble_ability":
        if key == "zar":
            options = [("shield", None), ("night_vision", 1)]
        else:  # "quti"
            options = [("gps", 1), ("compass", 1), ("shield", None)]
        picked_key, picked_amount = random.choice(options)
        if picked_key == "shield":
            add_shield(uid, 1)
            result_note = "🛡 Chiqdi: Himoya (+1 shield)!"
        else:
            add_charge(uid, picked_key, picked_amount)
            result_note = f"✨ Chiqdi: {TOGGLABLE_ITEMS.get(picked_key, picked_key)} ({picked_amount} ta)!"
    elif mode == "charge":
        add_charge(uid, item["charge_key"], item.get("charge_amount", 1))
        result_note = f"✅ Ishlatish uchun tayyor — {item.get('desc', '')}"
    elif mode == "multiplier":
        ch = get_charges(uid)
        mkey = item["charge_key"]
        cur_until = ch.get(mkey + "_until", 0)
        new_until = max(cur_until, time.time()) + MULTIPLIER_DURATION_SECONDS
        ch[mkey + "_val"] = item["mult_value"]
        ch[mkey + "_until"] = new_until
        set_charges(uid, ch)
        days_left = round((new_until - time.time()) / 86400, 1)
        result_note = f"✅ Multiplikator faollashtirildi: x{item['mult_value']} — {days_left} kun davomida amal qiladi."
    elif mode == "expiry":
        until = time.time() + item["duration_seconds"]
        set_charge_value(uid, item["charge_key"], until)
        result_note = f"✅ {item['duration_seconds']//3600} soatga faollashtirildi."
    elif mode == "permanent_flag":
        set_charge_value(uid, item["charge_key"], 1)
        result_note = "✅ Doimiy maqom faollashtirildi."
    elif mode == "hero_chest":
        existing = get_hero(uid)
        if existing:
            refund = item["price"] // 2
            add_balance(uid, diamond=refund)
            result_note = f"📦 Sizda allaqachon geroy bor ({existing['name']})! Sandiq {refund} 💎 ga aylantirildi."
        else:
            hero_key = roll_hero()
            with db_lock:
                cur.execute("INSERT OR REPLACE INTO heroes (user_id, hero_key, level, acquired_at) VALUES (?, ?, 1, ?)", (uid, hero_key, time.time()))
                conn.commit()
            hero = HEROES[hero_key]
            extra = "\n🎊🎊 NODIR TUSHISH! Siz eng kuchli geroyni qo'lga kiritdingiz! 🎊🎊" if hero_key == "burgut" else ""
            result_note = f"🎉 Sandiqdan chiqdi: <b>{hero['name']}</b> (1-lvl)!{extra}\n{hero['desc']}\n/geroyim orqali ko'ring va rivojlantiring."

    add_inventory_item(uid, item["name"])
    return True, f"✅ {item['name']} sotib olindi!\n{result_note}"


