@bot.message_handler(commands=["refund"])
def cmd_refund(message):
    """💸 FAQAT bot egasi — xato yoki noto'g'ri to'lovni Telegram Stars orqali
    qaytaradi (refund). Foydalanuvchining OXIRGI muvaffaqiyatli to'lovi
    avtomatik topiladi va qaytariladi.
    Foydalanish: /refund <user_id>  YOKI  kimningdir xabariga reply qilib /refund
    🔒 XAVFSIZLIK: bu funksiya kutubxona versiyasiga bog'liq (refund_star_payment) —
    agar mavjud bo'lmasa, aniq xabar bilan to'xtaydi, botni yiqitmaydi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return

    target_id = None
    parts = message.text.split()
    if message.reply_to_message and message.reply_to_message.from_user:
        target_id = message.reply_to_message.from_user.id
    elif len(parts) == 2 and parts[1].isdigit():
        target_id = int(parts[1])
    else:
        bot.send_message(message.chat.id, "Foydalanish: <code>/refund &lt;user_id&gt;</code> yoki kimningdir xabariga reply qilib <code>/refund</code>.")
        return

    charge_id = get_setting(f"last_charge_{target_id}")
    if not charge_id:
        bot.send_message(message.chat.id, f"❌ <code>{target_id}</code> uchun so'nggi Stars to'lovi topilmadi.")
        return

    try:
        bot.refund_star_payment(target_id, charge_id)
        bot.send_message(message.chat.id, f"✅ <code>{target_id}</code>ning so'nggi to'lovi muvaffaqiyatli qaytarildi (refund).")
        safe_send(target_id, "💸 So'nggi Stars to'lovingiz bot egasi tomonidan qaytarildi (refund qilindi).")
    except AttributeError:
        bot.send_message(
            message.chat.id,
            "❌ Ushbu botning pyTelegramBotAPI kutubxona versiyasida <code>refund_star_payment</code> "
            "mavjud emas. Kutubxonani yangilang: <code>pip install --upgrade pyTelegramBotAPI</code>",
        )
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ Qaytarishda xatolik: {e}")


@bot.message_handler(content_types=["successful_payment"])
def successful_payment_handler(message):
    payload = message.successful_payment.invoice_payload
    # 🔧 YANGI (#8): har bir muvaffaqiyatli to'lovning charge_id'sini saqlab qo'yamiz —
    # kerak bo'lsa /refund buyrug'i orqali bu to'lovni qaytarish (refund) mumkin bo'lsin deb.
    try:
        set_setting(f"last_charge_{message.from_user.id}", message.successful_payment.telegram_payment_charge_id)
    except Exception:
        pass
    try:
        parts = payload.split("_")
        kind = parts[0]
    except Exception:
        return

    if kind == "namestyle":
        # 🎨 v13: Ism uslubi (Unicode shrift skin) — Stars orqali sotib olinganda
        _, uid_s, style_key = parts
        uid = int(uid_s)
        if style_key in NAME_STYLE_CATALOG:
            label, price, days = NAME_STYLE_CATALOG[style_key]
            name_style_grant(uid, style_key, days)
            sample = apply_name_style("Hunter", style_key)
            bot.send_message(message.chat.id, f"🎉 To'lov muvaffaqiyatli o'tdi! Ism uslubingiz: {sample} ({days} kun faol).")
        else:
            bot.send_message(message.chat.id, "✅ To'lov qabul qilindi.")

    elif kind == "hc":
        _, uid_s, qty_s = parts
        uid, qty = int(uid_s), int(qty_s)
        add_balance(uid, coin=qty)
        bot.send_message(message.chat.id, f"✅ To'lov muvaffaqiyatli o'tdi! +{qty} 🪙 Hunter Coin hisobingizga qo'shildi.\nRahmat!")

    elif kind == "namecolor":
        # 🎨 v14: Ism rangi (rangli belgi) — Stars orqali sotib olinganda
        _, uid_s, color_key = parts
        uid = int(uid_s)
        if color_key in NAME_COLOR_CATALOG:
            emoji, label, price, days = NAME_COLOR_CATALOG[color_key]
            name_color_grant(uid, color_key, days)
            bot.send_message(message.chat.id, f"🎉 To'lov muvaffaqiyatli o'tdi! Ism rangingiz: {emoji} {label} ({days} kun faol).")
        else:
            bot.send_message(message.chat.id, "✅ To'lov qabul qilindi.")

    elif kind == "diamondbuy":
        # 💎 Yangi: Olmosni to'g'ridan-to'g'ri Stars orqali sotib olish (7⭐️ = 1💎)
        _, uid_s, qty_s = parts
        uid, qty = int(uid_s), int(qty_s)
        add_balance(uid, diamond=qty)
        bot.send_message(message.chat.id, f"✅ To'lov muvaffaqiyatli o'tdi! +{qty} 💎 Olmos hisobingizga qo'shildi.\nRahmat!")

    elif kind == "elitepay":
        # 👑 HUNTER ELITE — tarifli (1 hafta — 3 oy) obuna, Stars orqali to'langanda shu yerga tushadi
        _, uid_s, days_s = parts
        uid, days = int(uid_s), int(days_s)
        new_until = grant_elite_days(uid, days)
        bot.send_message(
            message.chat.id,
            elite_success_text(days, new_until),
        )

    elif kind == "dollarbuy":
        # 💵 v8: dollarni Stars bilan sotib olish (Mini App do'koni)
        _, uid_s, qty_s = parts
        uid, qty = int(uid_s), int(qty_s)
        add_balance(uid, dollar=qty)
        bot.send_message(message.chat.id, f"✅ To'lov muvaffaqiyatli o'tdi! +{qty} 💵 Dollar hisobingizga qo'shildi.\nRahmat!")

    elif kind == "elitegift":
        # 🎁 v8: do'stga ELITE sovg'a (Stars)
        _, buyer_s, target_s, days_s = parts
        buyer, target, days = int(buyer_s), int(target_s), int(days_s)
        new_until = grant_elite_days(target, days)
        bot.send_message(message.chat.id, f"✅ To'lov muvaffaqiyatli o'tdi! {esc(user_dict(target)['name'])} ga {days} kunlik 👑 ELITE sovg'a qilindi.")
        safe_send(target, f"🎁 {mention(buyer, user_dict(buyer)['name'])} sizga <b>{days} kunlik 👑 ELITE</b> sovg'a qildi!\n" + elite_success_text(days, new_until))

    elif kind == "herobuy":
        # 🏆 v8: geroyni to'g'ridan-to'g'ri Stars bilan sotib olish
        _, uid_s, hkey = parts
        uid = int(uid_s)
        if hkey in HEROES and _grant_hero(uid, hkey):
            bot.send_message(message.chat.id, f"🎉 To'lov muvaffaqiyatli o'tdi! {HEROES[hkey]['name']} endi sizniki!\n/geroyim orqali ko'ring.")
        else:
            # geroy allaqachon bor edi — to'lov yo'qolmasin: olmosda kompensatsiya beramiz
            comp = hero_price(hkey, "buy_diamond") if hkey in HEROES else 0
            if comp:
                add_balance(uid, diamond=comp)
            bot.send_message(message.chat.id, f"✅ To'lov qabul qilindi. Sizda allaqachon geroy borligi uchun {comp} 💎 olmos berildi.")

    elif kind == "herolv":
        # ⬆️ v8: geroy darajasini Stars bilan oshirish
        _, uid_s, lvl_s = parts
        uid, new_level = int(uid_s), int(lvl_s)
        hero = get_hero(uid)
        if hero and hero["level"] == new_level - 1 and new_level <= HERO_MAX_LEVEL:
            with db_lock:
                cur.execute("UPDATE heroes SET level=? WHERE user_id=? AND level=?", (new_level, uid, new_level - 1))
                conn.commit()
            bot.send_message(message.chat.id, f"🎉 To'lov muvaffaqiyatli o'tdi! Geroyingiz {new_level}-darajaga ko'tarildi!")
        else:
            comp = hero_price(hero["key"], f"lv{new_level}_diamond") if hero and new_level in (2, 3) else 0
            if comp:
                add_balance(uid, diamond=comp)
            bot.send_message(message.chat.id, f"✅ To'lov qabul qilindi. Daraja allaqachon o'zgargani uchun {comp} 💎 olmos berildi.")

    elif kind == "cosmetic":
        # ✨ Kosmetika (ramka/animatsiya/skin) — Stars orqali to'langanda shu yerga tushadi
        cosmetic_id = int(parts[1])
        uid = message.from_user.id
        with db_lock:
            cur.execute("SELECT name, emoji FROM cosmetics WHERE id=?", (cosmetic_id,))
            row = cur.fetchone()
            cur.execute("UPDATE cosmetics SET sold = sold + 1 WHERE id=?", (cosmetic_id,))
            cur.execute("INSERT OR IGNORE INTO user_cosmetics (user_id, cosmetic_id, purchased_at) VALUES (?,?,?)",
                        (uid, cosmetic_id, time.strftime("%Y-%m-%d %H:%M")))
            conn.commit()
        if row:
            bot.send_message(message.chat.id, f"🎉 To'lov muvaffaqiyatli o'tdi! {row[1]} <b>{row[0]}</b> endi sizniki!")
        else:
            bot.send_message(message.chat.id, "✅ To'lov muvaffaqiyatli o'tdi!")

    # 💎 v12: qaysi kind bo'lishidan qat'i nazar — har qanday muvaffaqiyatli Stars
    # to'lovi "birinchi xarid" hisoblanadi (agar to'lovchi kimningdir taklifi orqali
    # kelgan bo'lsa va bu ilk xaridi bo'lsa, taklif qilganga bonus beriladi).
    _maybe_referral_purchase_bonus(message.from_user.id)
    # 👑 v14: har qanday muvaffaqiyatli Stars to'lovi "Oyning homiysi" reytingiga qo'shiladi
    try:
        _track_monthly_spend(message.from_user.id, message.successful_payment.total_amount)
    except Exception:
        pass


