@bot.callback_query_handler(func=lambda c: c.data == "admin|groups")
def cb_admin_groups(call):
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Ruxsat yo'q.", show_alert=True)
        return
    bot.answer_callback_query(call.id)
    groups = list_known_groups()
    if not groups:
        text = "Bot hali birorta guruhga qo'shilmagan."
        smart_render(call, text, with_back_button())
        return
    lines = ["📋 <b>Guruhlar:</b>", "", "👇 Kirish uchun havolani bosing (faqat sizga, 1 martalik):", ""]
    for cid, title in groups:
        link = None
        try:
            inv = bot.create_chat_invite_link(cid, name="Owner kirish", member_limit=1)
            link = inv.invite_link
        except Exception as e:
            _logger.warning("create_chat_invite_link(%s) xatolik: %s", cid, e)
        if link:
            lines.append(f"• <a href=\"{link}\">{title}</a> (ID: <code>{cid}</code>)")
        else:
            lines.append(f"• {title} (ID: <code>{cid}</code>) — ⚠️ havola yaratilmadi (botda admin huquqi yo'q bo'lishi mumkin)")
    text = "\n".join(lines)
    smart_render(call, text, with_back_button(), disable_web_page_preview=True)


