@bot.callback_query_handler(func=lambda c: c.data == "admin|hero_history")
@hero_safe("cb_admin_hero_history (admin|hero_history)")
def cb_admin_hero_history(call):
    """📜 Admin paneldagi tugma — barcha o'yinchilar bo'yicha geroy mahoratlari
    ISHLATILISH statistikasini (eng ko'p ishlatilgan 15 tasi) ko'rsatadi."""
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Ruxsat yo'q.", show_alert=True)
        return
    bot.answer_callback_query(call.id)
    with db_lock:
        cur.execute(
            "SELECT ability_name, COUNT(*) AS cnt FROM hero_ability_log "
            "GROUP BY ability_name ORDER BY cnt DESC LIMIT 15"
        )
        rows = cur.fetchall()
        cur.execute("SELECT COUNT(*), COUNT(DISTINCT user_id) FROM hero_ability_log")
        total, distinct_users = cur.fetchone()
    if not rows:
        bot.send_message(call.message.chat.id, "📜 Hozircha hech kim geroy mahoratini ishlatmagan.")
        return
    lines = [
        "📜 <b>Geroy tarixi — umumiy statistika</b>",
        f"Jami ishlatilgan: <b>{total}</b> marta, <b>{distinct_users}</b> ta foydalanuvchi tomonidan\n",
    ]
    for ability_name, cnt in rows:
        lines.append(f"• <b>{ability_name}</b> — {cnt} marta")
    lines.append("\n💡 <i>Muayyan foydalanuvchi tarixini ko'rish uchun uning xabariga reply qilib /geroy_tarix yozing.</i>")
    bot.send_message(call.message.chat.id, "\n".join(lines))


