def _top_scope_for(chat, user_id):
    """👥 Guruhda so'ralsa — FAQAT shu guruh a'zolari (agar so'ragan bot egasi
    bo'lmasa). Bot egasi so'raganda yoki shaxsiy chatda — barcha foydalanuvchilar."""
    if chat.type in ("group", "supergroup") and user_id and not is_owner(user_id):
        return chat.id, "g"
    return None, "a"


@bot.message_handler(commands=["top", "reyting"])
@bot.channel_post_handler(commands=["top", "reyting"])
def cmd_top(message):
    chat_filter, scope = _top_scope_for(message.chat, message.from_user.id if message.from_user else None)
    text, tp = build_top_text(chat_id=chat_filter)
    kb = _top_page_markup("wins", 0, tp, scope)
    if is_owner_channel(message.chat):
        bot.send_message(message.chat.id, text, reply_markup=kb)
        return
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if is_banned(message.from_user.id):
        return
    bot.send_message(message.chat.id, text, reply_markup=kb)


