#  🚪 /chiqish — HUNTER ELITE a'zolari uchun lobbydan istalgan payt chiqish huquqi
#     (Almex Black Bot'dagi PRO-only /leave bilan bir xil mantiq)
# --------------------------------------------------------------------------------

@bot.message_handler(commands=["chiqish"])
def cmd_chiqish(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    uid = message.from_user.id
    chat_id = message.chat.id
    game = GAMES.get(chat_id)

    # 🔧 TUZATILDI: avval BARCHA holatlarda ("lobbi yo'q", "o'yin allaqachon
    # boshlangan", "ELITE emas") bitta umumiy "faol lobbyda emassiz" xabari
    # chiqar edi — ELITE a'zolar buni "ishlamayapti" deb tushunishardi,
    # chunki chinakam sabab (masalan, o'yin allaqachon boshlangan bo'lgani)
    # hech qachon ANIQ aytilmasdi. Endi har bir holat uchun ALOHIDA, aniq
    # sabab ko'rsatiladi.
    if not game or uid not in game["players"]:
        bot.send_message(chat_id, "❌ Siz hozir bu guruhdagi o'yin ro'yxatida (lobbyda) emassiz.")
        return

    if game["phase"] != "waiting":
        bot.send_message(
            chat_id,
            "❌ O'yin allaqachon boshlanib bo'lgan — 👑 ELITE huquqi bilan lobbydan chiqish "
            "FAQAT o'yin boshlanmasdan OLDIN ishlaydi.\n"
            "Boshlangan o'yindan chiqish uchun <code>/tark_et</code> dan foydalaning — "
            "bu holda avtomatik mag'lub hisoblanasiz va -10 ball olasiz.",
        )
        return

    if not is_elite(uid):
        bot.send_message(
            chat_id,
            "❌ Lobbydan chiqish faqat 👑 <b>HUNTER ELITE</b> a'zolari uchun!\n"
            "/elite orqali ELITE a'zolikni oling.",
        )
        return

    del game["players"][uid]
    if game.get("join_msg_id"):
        try:
            bot.edit_message_text(build_join_text(game), chat_id, game["join_msg_id"], reply_markup=build_join_markup(chat_id, game))
        except Exception:
            pass
    bot.send_message(chat_id, f"🚪 {mention(uid, message.from_user.first_name)} lobbydan chiqdi (👑 ELITE huquqi).")


