    maybe_capture_owner(call.from_user)
    bot.answer_callback_query(call.id, "🚫 Bu funksiya olib tashlangan: Hunter Coin endi faqat 💎 Olmosga, joriy kurs bo'yicha sotib olinadi (/olmos_coin).", show_alert=True)   # 🔧 v8: olib tashlangan
