_ELITE_PRICE_EDIT_STATE = {}  # owner_id -> tahrirlanayotgan tarifning kunlar soni


def _elite_price_panel_text_and_kb():
    kb = types.InlineKeyboardMarkup(row_width=1)
    lines = ["💰 <b>ELITE narxlarini boshqarish</b>\n", "Hozirgi narxlar:\n"]
    for plan in ELITE_PLANS:
        d = plan["days"]
        label = _elite_days_label(d)
        lines.append(f"• {label} — 💎{plan['diamond']} / ⭐️{plan['stars']}")
        kb.add(types.InlineKeyboardButton(f"✏️ {label} narxini o'zgartir", callback_data=f"admin|elite_price_edit|{d}"))
    kb.add(types.InlineKeyboardButton("🔁 Standart narxlarga qaytarish", callback_data="admin|elite_price_reset"))
    lines.append("\n✏️ tugmasini bosib, yangi narxni <code>olmos stars</code> formatida yozing (masalan: <code>50 120</code>).")
    return "\n".join(lines), kb


