    bot.answer_callback_query(call.id, "✅ Standart narxlarga qaytarildi.")
    global ELITE_PLANS
    ELITE_PLANS = [dict(p) for p in _ELITE_PLANS_DEFAULT]
    _save_elite_plans()
    text, kb = _elite_price_panel_text_and_kb()
    smart_render(call, "🔁 ELITE narxlari standart holatga qaytarildi.\n\n" + text, kb)


