@bot.callback_query_handler(func=lambda c: c.data == "admin|restart_do")
def cb_admin_restart_do(call):
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Ruxsat yo'q.", show_alert=True)
        return
    bot.answer_callback_query(call.id, "🔄 Qayta ishga tushmoqda...")
    active_chats = list(GAMES.keys())
    bot.send_message(call.message.chat.id, "🔄 Bot qayta ishga tushirilmoqda...")
    save_games_state()
    for chat_id in active_chats:
        try:
            bot.send_message(
                chat_id,
                "🔄 <b>Bot texnik ishlar tufayli bir necha soniyaga qayta ishga tushmoqda.</b>\n"
                "O'yiningiz avtomatik saqlanadi va tiklanadi — iltimos biroz kuting. ⏳",
            )
        except Exception:
            pass
    _logger.info("🔄 Admin panel orqali bot %s tomonidan qayta ishga tushirilmoqda.", call.from_user.id)
    try:
        os.execv(sys.executable, [sys.executable] + sys.argv)
    except Exception:
        _logger.exception("⚠️ os.execv orqali qayta ishga tushirib bo'lmadi.")
        os._exit(1)


