def _build_help_text(show_admin_section):
    """🔧 /yordam matnini USER_COMMANDS ichidagi tavsiflardan avtomatik yig'adi —
    shuning uchun kelajakda USER_COMMANDS'ga yangi buyruq qo'shilsa, uni bu yerga
    qo'lda qo'shish shart emas (agar u _HELP_CATEGORIES'da ham bo'lsa)."""
    desc_by_cmd = dict(USER_COMMANDS)
    lines = ["🆘 <b>Yordam — buyruqlar bo'yicha qisqa qo'llanma</b>\n"]
    for title, cmds in _HELP_CATEGORIES:
        rows = []
        for c in cmds:
            d = desc_by_cmd.get(c)
            if not d or "(admin)" in d:
                continue
            # USER_COMMANDS descriptions are dynamic/user-facing text. Escape HTML
            # so words such as <soni> cannot be interpreted as Telegram tags.
            safe_d = _html.escape(str(d), quote=False)
            rows.append(f"/{_html.escape(str(c), quote=False)} — {safe_d}")
        if rows:
            lines.append(f"\n<b>{title}</b>\n" + "\n".join(rows))
    lines.append(
        "\n💡 <i>Maslahat: buyruqni to'liq yozmasangiz ham, Telegram \"/\" belgisini "
        "bosganda barcha buyruqlar tavsifi bilan birga avtomatik chiqadi.</i>"
    )
    if show_admin_section:
        admin_rows = [
            f"/{_html.escape(str(c), quote=False)} — {_html.escape(str(d), quote=False)}"
            for c, d in USER_COMMANDS if d and "(admin)" in d
        ]
        if admin_rows:
            lines.append("\n\n⚙️ <b>Admin buyruqlari (shu guruhda)</b>\n" + "\n".join(admin_rows))
    return "\n".join(lines)


@bot.message_handler(commands=["yordam", "help"])
def cmd_yordam(message):
    """🆘 Foydalanuvchi uchun qulay, tushunarli yordam menyusi."""
    maybe_capture_owner(message.from_user)
    try:
        is_group_admin = False
        if message.chat.type in ("group", "supergroup"):
            try:
                member = bot.get_chat_member(message.chat.id, message.from_user.id)
                is_group_admin = member.status in ("administrator", "creator")
            except Exception:
                is_group_admin = False
        show_admin = is_owner(message.from_user.id) or is_group_admin
        bot.send_message(message.chat.id, _build_help_text(show_admin))
    except Exception as e:
        notify_owner_of_error("cmd_yordam (/yordam)", e)
        bot.send_message(message.chat.id, "🆘 Yordam menyusini ko'rsatishda xatolik yuz berdi, birozdan so'ng qayta urinib ko'ring.")


