# ================================================================================

AUTO_BACKUP_INTERVAL = 24 * 60 * 60  # 24 soat
AUTO_BACKUP_PATH = "/tmp/hunter_mafia_auto_backup.json"


def check_heroes_table_integrity():
    """🛡 Backup paytida heroes jadvali BUTUNLIGINI tekshiradi:
    - hero_key HEROES lug'atida mavjud bo'lgan haqiqiy kalitmi
    - level 1..HERO_MAX_LEVEL oralig'idami
    - temp_until manfiy emasmi
    Qaytaradi: (jami_qator, muammoli_qatorlar_soni, muammolar_matni_ro'yxati)."""
    problems = []
    try:
        with db_lock:
            cur.execute("SELECT user_id, hero_key, level, temp_until FROM heroes")
            rows = cur.fetchall()
        for user_id, hero_key, level, temp_until in rows:
            if hero_key not in HEROES:
                problems.append(f"user_id={user_id}: noma'lum hero_key '{hero_key}'")
                continue
            if level is None or not (1 <= level <= HERO_MAX_LEVEL):
                problems.append(f"user_id={user_id} ({hero_key}): noto'g'ri level={level}")
            if temp_until is not None and temp_until < 0:
                problems.append(f"user_id={user_id} ({hero_key}): manfiy temp_until={temp_until}")
        return len(rows), len(problems), problems
    except Exception as e:
        log_hero_error("check_heroes_table_integrity", e)
        return 0, -1, [f"Tekshiruv bajarilmadi: {e}"]


def _run_auto_backup():
    try:
        with db_lock:
            cur.execute("SELECT * FROM users")
            user_rows = cur.fetchall()
            cur.execute("SELECT user_id, hero_key, level, acquired_at, temp_until FROM heroes")
            hero_rows = cur.fetchall()
            cur.execute("SELECT user_id, hero_key, ability_name, used_at FROM hero_ability_log")
            hero_log_rows = cur.fetchall()
        users_data = [dict(zip(USER_COLS, r)) for r in user_rows]
        heroes_data = [
            {"user_id": r[0], "hero_key": r[1], "level": r[2], "acquired_at": r[3], "temp_until": r[4]}
            for r in hero_rows
        ]
        hero_log_data = [
            {"user_id": r[0], "hero_key": r[1], "ability_name": r[2], "used_at": r[3]}
            for r in hero_log_rows
        ]
        backup_payload = {
            "backup_version": 2,
            "users": users_data,
            "heroes": heroes_data,
            "hero_ability_log": hero_log_data,
        }
        with open(AUTO_BACKUP_PATH, "w", encoding="utf-8") as f:
            json.dump(backup_payload, f, ensure_ascii=False, indent=2)

        # 🛡 heroes jadvali butunligini tekshirib, muammo bo'lsa captionda ogohlantirish beramiz
        total_heroes, bad_count, problems = check_heroes_table_integrity()
        integrity_line = f"🛡 Geroy jadvali: {total_heroes} ta yozuv, muammo: {bad_count if bad_count >= 0 else 'tekshirib bo\u2019lmadi'}"

        with open(AUTO_BACKUP_PATH, "rb") as f:
            bot.send_document(
                OWNER_ID_FROM_ENV, f,
                caption=(
                    f"💾 <b>Avtomatik zaxira nusxa</b>\n"
                    f"🕐 {time.strftime('%d.%m.%Y %H:%M')}\n"
                    f"👥 {len(users_data)} ta foydalanuvchi\n"
                    f"🏆 {len(heroes_data)} ta geroy, {len(hero_log_data)} ta mahorat-tarixi yozuvi\n"
                    f"{integrity_line}\n\n"
                    f"<i>Kerak bo'lsa, bu faylni /bazani_tikla orqali tiklashingiz mumkin.</i>"
                ),
            )
        if bad_count > 0:
            bot.send_message(
                OWNER_ID_FROM_ENV,
                "⚠️ <b>Geroy jadvalida muammoli yozuvlar topildi:</b>\n" + "\n".join(problems[:20])
                + (f"\n… va yana {bad_count - 20} ta" if bad_count > 20 else ""),
            )
    except Exception as e:
        _logger.warning("Avtomatik zaxira nusxa olishda xatolik: %s", e)
        log_hero_error("_run_auto_backup", e)
    finally:
        # ⏳ har doim o'zini qayta rejalashtiradi — botning butun umri davomida davom etadi
        t = threading.Timer(AUTO_BACKUP_INTERVAL, _run_auto_backup)
        t.daemon = True
        t.start()


def start_auto_backup_loop():
    """Bot ishga tushganda bir marta chaqiriladi — birinchi zaxira nusxani DARHOL
    emas, 5 daqiqadan keyin oladi (bot to'liq ishga tushib ulgursin deb), keyin
    esa har 24 soatda o'z-o'zini qayta ishga tushiradi."""
    t = threading.Timer(300, _run_auto_backup)  # birinchi safar — 5 daqiqadan keyin
    t.daemon = True
    t.start()


# ================================================================================
#  🩺 "MUZLAB QOLISH" (FREEZE) QAROVCHISI — WATCHDOG
#  Ba'zan (juda kam hollarda) bot tashqi sabab bilan — masalan barcha ishchi
#  threadlar to'xtab qolgan yoki tarmoq darajasida "yarim ochiq" ulanish qolib
#  ketgan hollarda — hech qanday xatolik chiqarmasdan shunchaki javob berishni
#  to'xtatib qo'yishi mumkin (haqiqiy "qotib qolish"). Bu holatni tashqi log orqali
#  emas, botning O'ZI payqab, holatni saqlab, O'ZINI avtomatik qayta ishga
#  tushiradi — foydalanuvchi yoki admin qo'lda serverga kirib restart qilishi shart
#  bo'lmaydi.
# ================================================================================
_WATCHDOG_INTERVAL = 300       # har 5 daqiqada bir marta tekshiradi
_WATCHDOG_MAX_FAILS = 3        # ketma-ket 3 marta (~15 daqiqa) javobsiz bo'lsa — qayta ishga tushadi


def _freeze_watchdog():
    fails = 0
    while True:
        time.sleep(_WATCHDOG_INTERVAL)
        try:
            bot.get_me()  # Telegram API bilan eng oddiy "tirikmisan?" so'rovi
            fails = 0
        except Exception as e:
            fails += 1
            _logger.warning("🩺 Watchdog: bot javob bermadi (%s/%s): %s", fails, _WATCHDOG_MAX_FAILS, e)
        if fails >= _WATCHDOG_MAX_FAILS:
            _logger.error("🚨 Watchdog: bot %s daqiqadan beri muzlab qolgan — o'zini qayta ishga tushirmoqda!",
                           (_WATCHDOG_INTERVAL * _WATCHDOG_MAX_FAILS) // 60)
            try:
                save_games_state()  # aktiv o'yinlar yo'qolib ketmasin
            except Exception:
                pass
            try:
                conn.commit()
            except Exception:
                pass
            # os.execv — jarayonni O'ZI, tashqi supervisor/systemd/Docker'ga
            # bog'liq bo'lmagan holda, bir zumda qayta ishga tushiradi.
            os.execv(sys.executable, [sys.executable] + sys.argv)


def start_freeze_watchdog():
    t = threading.Thread(target=_freeze_watchdog, daemon=True)
    t.start()


# ================================================================================
#  🌐 RENDER.COM UCHUN "UXLAB QOLMASLIK" TIZIMI (keep-alive)
#  Render.com'ning BEPUL tarifidagi "Web Service"lar ~15 daqiqa hech qanday
#  tashqi HTTP so'rov kelmasa — avtomatik "uxlab qoladi" (sleep), keyingi
#  so'rovda qayta uyg'onishi 30-60 soniya vaqt oladi (shu payt bot javob
#  bermay qoladi). Buning oldini olish uchun ikkita narsa kerak:
#   1) Bot ICHIDA kichik HTTP server ochamiz (Render buni "xizmat tirik" deb
#      biladi, $PORT muhit o'zgaruvchisiga bog'lanadi — Render buni avtomatik beradi).
#   2) Bot O'ZI, har 10 daqiqada, o'zining tashqi (public) manziliga so'rov
#      yuboradi — bu Render nazarida "tashqi trafik" hisoblanadi va
#      uxlashning oldini oladi.
#  Eslatma: bu FAQAT Render kabi "sleep" qiladigan bepul xostinglar uchun
#  kerak — Railway'da bunday muammo yo'q, lekin bu tizim Railway'da ham
#  hech qanday zarar keltirmaydi (shunchaki ishlatilmay qoladi).
# ================================================================================
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import hmac
import hashlib


def _verify_telegram_webapp_init_data(init_data_str, max_age_seconds=86400):
    """🔐 Telegram Mini App'dan kelgan initData'ni rasmiy Telegram algoritmi
    bo'yicha tekshiradi (https://core.telegram.org/bots/webapps#validating-data-
    received-via-the-mini-app). Muvaffaqiyatli bo'lsa foydalanuvchi lug'atini,
    aks holda None qaytaradi — shu orqali boshqa birovning balansini so'rab
    ololmasligi ta'minlanadi."""
    try:
        pairs = parse_qs(init_data_str, keep_blank_values=True)
        received_hash = pairs.pop("hash", [None])[0]
        if not received_hash:
            return None
        data_check_arr = sorted(f"{k}={v[0]}" for k, v in pairs.items())
        data_check_string = "\n".join(data_check_arr)
        secret_key = hmac.new(b"WebAppData", TOKEN.encode(), hashlib.sha256).digest()
        computed_hash = hmac.new(secret_key, data_check_string.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(computed_hash, received_hash):
            return None
        auth_date = int(pairs.get("auth_date", ["0"])[0])
        if auth_date and (time.time() - auth_date) > max_age_seconds:
            return None
        user_raw = pairs.get("user", [None])[0]
        return json.loads(user_raw) if user_raw else {}
    except Exception as e:
        _logger.warning("_verify_telegram_webapp_init_data xatolik: %s", e)
        return None


