def _owner_uid():
    return OWNER_ID_FROM_ENV if OWNER_ID_FROM_ENV is not None else OWNER_ID


_RATE_BUCKETS = {}
_RATE_LOCK = threading.Lock()


def _rate_ok(uid, key, limit, window):
    """Oddiy tezlik chegarasi: `window` soniyada `limit` tadan ko'p emas."""
    now = time.time()
    with _RATE_LOCK:
        dq = _RATE_BUCKETS.setdefault((uid, key), [])
        while dq and dq[0] <= now - window:
            dq.pop(0)
        if len(dq) >= limit:
            return False
        dq.append(now)
        return True


def _date_str(ts=None):
    return time.strftime("%Y-%m-%d", time.localtime(time.time() if ts is None else ts))


def _fmt_time_ago(ts):
    diff = max(0, int(time.time() - ts))
    if diff < 60:
        return "hozir"
    if diff < 3600:
        return f"{diff // 60} daqiqa oldin"
    if diff < 86400:
        return f"{diff // 3600} soat oldin"
    return f"{diff // 86400} kun oldin"


# ------------------------------------------------------------------ 🎁 KUNLIK MUKOFOT (30 kunlik seriya)
DAILY_BASE = 115                                   # 1-kun dollar mukofoti
DAILY_STEP = 15                                    # har keyingi kunga +15$
DAILY_STREAK_DIAMONDS = {7: 3, 14: 5, 21: 8, 30: 10}   # 7/14/21/30-kunlarda dollar o'rniga 💎


def _daily_streak_now(uid):
    """(joriy seriya, bugun olinganmi) — seriya o'tgan kuni olingan bo'lsa davom etadi, aks holda 0."""
    ch = get_charges(uid)
    last = ch.get("daily_last", "")
    streak = int(ch.get("daily_streak", 0) or 0)
    if last == _date_str():
        return streak, True
    if last == _date_str(time.time() - 86400):
        return streak, False
    return 0, False


def _daily_reward_for_day(day, uid=None):
    """(dollar, olmos) — shu seriya kuni uchun mukofot. Milestone kunlarda faqat olmos."""
    if day in DAILY_STREAK_DIAMONDS:
        return 0, DAILY_STREAK_DIAMONDS[day]
    base = DAILY_BASE + DAILY_STEP * (day - 1)
    if uid is not None:
        base = int(base * bonus_mult(uid) * luck_mult(uid)) + hero_bonus_extra_dollar(uid)
    return base, 0


def daily_bonus_status(uid):
    u = user_dict(uid)
    claimed = (u.get("last_bonus_date") == _date_str())
    streak, _ = _daily_streak_now(uid)
    if claimed:
        streak = max(streak, 1)
        day_today = ((streak - 1) % 30) + 1
    else:
        day_today = (streak % 30) + 1
    days = []
    for d in range(1, 31):
        if d < day_today or (d == day_today and claimed):
            state = "claimed"
        elif d == day_today:
            state = "today"
        else:
            state = "locked"
        dollar, diamond = _daily_reward_for_day(d, uid)
        days.append({"day": d, "dollar": dollar, "diamond": diamond, "state": state})
    return {"claimed_today": claimed, "streak": streak, "day_today": day_today, "days": days}


def _perform_daily_bonus(uid, first_name=None):
    """Kunlik bonusni beradi (bot tugmasi ham, Mini App ham SHU funksiyani ishlatadi).
    Bir kunda faqat 1 marta — bazada atomik tekshiriladi."""
    user_dict(uid, first_name)
    today = _date_str()
    with db_lock:
        cur.execute("UPDATE users SET last_bonus_date=? WHERE user_id=? AND COALESCE(last_bonus_date,'') != ?",
                    (today, uid, today))
        got = cur.rowcount > 0
        conn.commit()
    if not got:
        return {"ok": False, "already": True}
    prev_streak, _ = _daily_streak_now(uid)
    streak = prev_streak + 1
    day_in_cycle = ((streak - 1) % 30) + 1
    ch = get_charges(uid)
    ch["daily_streak"] = streak
    ch["daily_last"] = today
    set_charges(uid, ch)
    dollar, diamond = _daily_reward_for_day(day_in_cycle, uid)
    if diamond:
        add_balance(uid, diamond=diamond)
        kind, amount = "diamond", diamond
    else:
        add_balance(uid, dollar=dollar)
        kind, amount = "dollar", dollar
    return {"ok": True, "already": False, "kind": kind, "amount": amount, "streak": streak,
            "day": day_in_cycle, "streak_diamond": 0}


