QUESTS = {
    "kunlik": [
        {"key": "d_play1", "icon": "🎮", "name": "1 ta o'yin o'ynang", "target": 1, "reward": 30, "metric": "games"},
        {"key": "d_win1", "icon": "🏆", "name": "1 ta o'yinda g'alaba qozoning", "target": 1, "reward": 50, "metric": "wins"},
        {"key": "d_play3", "icon": "🎯", "name": "3 ta o'yin o'ynang", "target": 3, "reward": 80, "metric": "games"},
    ],
    "haftalik": [
        {"key": "w_play10", "icon": "🔥", "name": "Haftada 10 ta o'yin", "target": 10, "reward": 250, "metric": "games"},
        {"key": "w_win5", "icon": "👑", "name": "Haftada 5 ta g'alaba", "target": 5, "reward": 400, "metric": "wins"},
    ],
}
_QUEST_LOCK = threading.Lock()


def _quest_period(scope):
    """(davr identifikatori, davr boshlanish vaqti)."""
    now = time.time()
    lt = time.localtime(now)
    midnight = time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday, 0, 0, 0, 0, 0, -1))
    if scope == "kunlik":
        return _date_str(now), midnight
    monday = midnight - lt.tm_wday * 86400
    return time.strftime("%G-W%V", lt), monday


def _quest_progress(uid, metric, since_ts):
    with db_lock:
        if metric == "wins":
            cur.execute("SELECT COUNT(*) FROM points_log WHERE user_id=? AND reason='game_result' AND points>0 AND ts>=?",
                        (uid, since_ts))
        else:
            cur.execute("SELECT COUNT(*) FROM points_log WHERE user_id=? AND reason='game_result' AND ts>=?",
                        (uid, since_ts))
        return int(cur.fetchone()[0] or 0)


def quests_state(uid):
    ch = get_charges(uid)
    claimed_map = ch.get("quests_claimed", {}) if isinstance(ch.get("quests_claimed"), dict) else {}
    out = {}
    for scope, rows in QUESTS.items():
        period_id, since = _quest_period(scope)
        items = []
        for q in rows:
            prog = min(_quest_progress(uid, q["metric"], since), q["target"])
            items.append({"key": q["key"], "icon": q["icon"], "name": q["name"], "reward": q["reward"],
                          "target": q["target"], "progress": prog,
                          "claimed": claimed_map.get(q["key"]) == period_id})
        out[scope] = items
    return out


def quest_claim(uid, key):
    """(ok, xabar, mukofot) — vazifa mukofotini beradi (bir davrda bir marta)."""
    for scope, rows in QUESTS.items():
        for q in rows:
            if q["key"] != key:
                continue
            period_id, since = _quest_period(scope)
            with _QUEST_LOCK:
                ch = get_charges(uid)
                claimed_map = ch.get("quests_claimed", {}) if isinstance(ch.get("quests_claimed"), dict) else {}
                if claimed_map.get(key) == period_id:
                    return False, "Bu vazifa mukofoti allaqachon olingan.", 0
                if _quest_progress(uid, q["metric"], since) < q["target"]:
                    return False, "Vazifa hali bajarilmagan.", 0
                claimed_map[key] = period_id
                ch["quests_claimed"] = claimed_map
                set_charges(uid, ch)
            add_balance(uid, dollar=q["reward"])
            return True, f"+{q['reward']}$ mukofot olindi!", q["reward"]
    return False, "Bunday vazifa yo'q.", 0


