# ------------------------------------------------------------------ 💎 PREMIUM GURUHLAR (pullik guruhlar)
def _parse_currency(word):
    w = (word or "").lower()
    if w in ("dollar", "$", "dollars", "usd"):
        return "dollar"
    return "diamond"


def premium_list(uid):
    with db_lock:
        cur.execute("SELECT id, title, price, currency FROM premium_groups WHERE active=1 ORDER BY id")
        rows = cur.fetchall()
        cur.execute("SELECT group_id FROM premium_access WHERE user_id=?", (uid,))
        owned = {r[0] for r in cur.fetchall()}
    return [{"id": r[0], "title": r[1], "price": r[2], "currency": r[3], "owned": r[0] in owned} for r in rows]


def premium_buy(uid, gid):
    """(ok, xabar, havola) — to'lov + bir martalik taklif havolasi."""
    user_dict(uid)
    with db_lock:
        cur.execute("SELECT chat_id, title, price, currency FROM premium_groups WHERE id=? AND active=1", (gid,))
        row = cur.fetchone()
        cur.execute("SELECT 1 FROM premium_access WHERE user_id=? AND group_id=?", (uid, gid))
        owned = cur.fetchone() is not None
    if not row:
        return False, "Guruh topilmadi.", None
    chat_id, title, price, currency = row
    col = "diamond" if currency == "diamond" else "dollar"
    if not owned and user_dict(uid)[col] < price:
        return False, f"Yetarli mablag' yo'q ({price} {'💎' if col == 'diamond' else '$'} kerak).", None
    try:
        link_obj = bot.create_chat_invite_link(chat_id, member_limit=1, expire_date=int(time.time()) + 86400)
        link = link_obj.invite_link
    except Exception:
        return False, "Guruhga havola yaratib bo'lmadi (bot u yerda admin bo'lmasligi mumkin). Bot egasiga xabar bering.", None
    if not owned:
        with db_lock:
            cur.execute(f"UPDATE users SET {col} = {col} - ? WHERE user_id=? AND {col} >= ?", (price, uid, price))
            paid = cur.rowcount > 0
            if paid:
                cur.execute("INSERT OR IGNORE INTO premium_access (user_id, group_id, bought_at) VALUES (?,?,?)",
                            (uid, gid, time.time()))
            conn.commit()
        if not paid:
            try:
                bot.revoke_chat_invite_link(chat_id, link)
            except Exception:
                pass
            return False, "Yetarli mablag' yo'q.", None
    return True, f"«{title}» guruhiga bir martalik havola (24 soat amal qiladi).", link


def _premium_menu(uid):
    items = premium_list(uid)
    if not items:
        return "💎 Hozircha Premium guruhlar yo'q.", None
    lines = ["💎 <b>Premium guruhlar</b>", "", "Yopiq guruhga kirish uchun tanlang:", ""]
    kb = types.InlineKeyboardMarkup()
    for it in items:
        sym = "💎" if it["currency"] == "diamond" else "$"
        lines.append(f"• <b>{esc(it['title'])}</b> — {it['price']} {sym}" + ("  ✅ sizda bor" if it["owned"] else ""))
        label = f"✅ Kirish — {it['title']}" if it["owned"] else f"🛒 {it['title']} — {it['price']} {sym}"
        kb.add(types.InlineKeyboardButton(label, callback_data=f"pgbuy|{it['id']}"))
    return "\n".join(lines), kb


@bot.message_handler(commands=["premium"])
def cmd_premium(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if message.chat.type != "private":
        bot.send_message(message.chat.id, "💎 Premium guruhlar ro'yxati botning shaxsiy chatida — /premium ni botga yozing.")
        return
    text, kb = _premium_menu(message.from_user.id)
    bot.send_message(message.chat.id, text, reply_markup=kb)


