with db_lock:
    cur.execute("CREATE TABLE IF NOT EXISTS user_names (user_id INTEGER PRIMARY KEY, username TEXT NOT NULL)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_user_names_u ON user_names(username)")
    conn.commit()

_NAME_CACHE = {}


def _remember_username(tg_user):
    """@username → user_id moslamasini eslab qoladi (o'tkazma va sovg'a uchun kerak)."""
    try:
        if isinstance(tg_user, dict):
            uid, un = tg_user.get("id"), tg_user.get("username")
        else:
            uid, un = getattr(tg_user, "id", None), getattr(tg_user, "username", None)
        if not uid or not un:
            return
        un = str(un).lower()
        if _NAME_CACHE.get(uid) == un:
            return
        with db_lock:
            cur.execute("INSERT OR REPLACE INTO user_names (user_id, username) VALUES (?, ?)", (uid, un))
            conn.commit()
        _NAME_CACHE[uid] = un
    except Exception:
        pass


def find_uid_by_username(username):
    un = (username or "").strip().lstrip("@").lower()
    if not un:
        return None
    with db_lock:
        cur.execute("SELECT user_id FROM user_names WHERE username=?", (un,))
        row = cur.fetchone()
    return row[0] if row else None


def get_username(uid):
    with db_lock:
        cur.execute("SELECT username FROM user_names WHERE user_id=?", (uid,))
        row = cur.fetchone()
    return row[0] if row else None


def _resolve_target(uid, to_type, to):
    """(target_uid, xato) — oluvchini @username / Telegram ID / Param (juft) bo'yicha topadi."""
    to_type = str(to_type or "").lower()
    if to_type == "param":
        pid = get_partner_id(uid)
        return (pid, None) if pid else (None, "Sizda hali juft (param) yo'q.")
    to = str(to or "").strip()
    if to_type == "id":
        if not to.lstrip("-").isdigit():
            return None, "Telegram ID faqat raqamlardan iborat bo'lishi kerak."
        tid = int(to)
    else:
        tid = find_uid_by_username(to)
        if tid is None:
            return None, "Foydalanuvchi topilmadi (u botga kamida bir marta /start yozgan bo'lishi kerak)."
    with db_lock:
        cur.execute("SELECT COALESCE(banned,0) FROM users WHERE user_id=?", (tid,))
        row = cur.fetchone()
    if not row:
        return None, "Foydalanuvchi botda ro'yxatdan o'tmagan."
    if row[0]:
        return None, "Bu foydalanuvchi bloklangan."
    if tid == uid:
        return None, "O'zingizga yubora olmaysiz."
    return tid, None


# ------------------------------------------------------------------ 🏠 ASOSIY SAHIFA
def _rank_label(level):
    if level >= 35:
        return "Afsona"
    if level >= 20:
        return "Ekspert"
    if level >= 10:
        return "Usta"
    if level >= 5:
        return "Tajribali"
    return "Yangi"


def _inventory_chips(uid):
    """Foydalanuvchining himoya/buyum hisoblagichlari (0 bo'lsa ham ko'rsatiladi — Sherifdagidek)."""
    u = user_dict(uid)
    ch = get_charges(uid)
    chips, seen = [], set()
    for cat in ("dollar", "diamond", "coin"):
        for key, it in SHOP_CATEGORIES[cat][1].items():
            mode = it.get("mode")
            if mode == "shield":
                skey, qty = "shield", u.get("shield", 0)
            elif mode == "charge" and it.get("charge_key"):
                skey, qty = it["charge_key"], ch.get(it["charge_key"], 0)
            else:
                continue
            if skey in seen:
                continue
            seen.add(skey)
            chips.append({"key": skey, "icon": it["name"].split(" ", 1)[0], "name": it["name"], "qty": int(qty or 0)})
    return chips


def home_state(uid):
    u = user_dict(uid)
    games, wins = int(u.get("games") or 0), int(u.get("wins") or 0)
    xp = xp_of_user(u)
    level, xp_in = level_progress(xp)
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users")
        users = int(cur.fetchone()[0] or 0)
    pid = get_partner_id(uid)
    return {
        "uid": uid, "name": u["name"], "username": get_username(uid), "rank": _rank_label(level),
        "dollar": u["dollar"], "diamond": u["diamond"], "coin": u["coin"],
        "games": games, "wins": wins, "losses": max(0, games - wins),
        "winrate": round(wins / games * 100) if games else 0,
        "level": level, "xp_in_level": xp_in, "xp_per_level": XP_PER_LEVEL,
        "points_total": _points_summary(uid)[0], "win_streak": _points_summary(uid)[1],
        "server": {"active_games": len(GAMES), "users": users},
        "vip": {"active": is_elite(uid), "days_left": elite_days_left(uid), "plans": ELITE_PLANS},
        "items": _inventory_chips(uid),
        "partner": user_dict(pid)["name"] if pid else None,
    }


# ------------------------------------------------------------------ 🎭 ROLLAR
_ROLE_SPLIT_RE = re.compile(r"^(.*?)\s*([^\w\s'’ʻ`.\-].*)$")


def _split_role(role):
    m = _ROLE_SPLIT_RE.match(role)
    return (m.group(1).strip(), m.group(2).strip()) if m else (role, "")


def roles_state():
    groups = {"town": [], "mafia": [], "solo": []}
    price_by_role = {r["role"]: r["diamond"] for r in role_shop_catalog()}
    for role in ALL_ROLES:
        name, emoji = _split_role(role)
        team = "mafia" if role in MAFIA_ROLES else ("solo" if role in INDEPENDENT_ROLES else "town")
        groups[team].append({"name": name, "emoji": emoji, "desc": ROLES_INFO.get(role, ""), "team": team,
                              "role_full": role, "buy_price": price_by_role.get(role)})
    items = []
    for cat, (title, its) in SHOP_CATEGORIES.items():
        for key, it in its.items():
            head = it["name"].split(" ", 1)
            items.append({"emoji": head[0], "name": head[1] if len(head) > 1 else head[0], "desc": it.get("desc", ""),
                          "price": it["price"], "currency": it["currency"]})
    return {"groups": [
        {"key": "mafia", "title": "Mafiya guruhi", "icon": "🔪", "roles": groups["mafia"]},
        {"key": "town", "title": "Tinch aholi guruhi", "icon": "👨", "roles": groups["town"]},
        {"key": "solo", "title": "Yakkalar guruhi", "icon": "🃏", "roles": groups["solo"]},
        {"key": "items", "title": "Anjomlar", "icon": "🎒", "roles": items},
    ]}


# ------------------------------------------------------------------ 🛒 DO'KON + ⭐ STARS
STARS_PACKS_DIAMOND = [(10, 70), (30, 200), (70, 450), (250, 1300)]       # (olmos, ⭐)
STARS_PACKS_DOLLAR = [(1275, 7), (12750, 70), (38250, 200)]                # (dollar, ⭐)
STARS_DOLLAR_PER_STAR = 1275 / 7.0                                         # ixtiyoriy miqdor uchun kurs


def _item_is_elite(it):
    return it["currency"] == "coin" or (it["currency"] == "diamond" and it["price"] >= 50) or \
           (it["currency"] == "dollar" and it["price"] >= 800)


def shop_state(uid):
    chips = {c["name"]: c["qty"] for c in _inventory_chips(uid)}
    items = []
    for cat, (title, its) in SHOP_CATEGORIES.items():
        for key, it in its.items():
            head = it["name"].split(" ", 1)
            items.append({
                "cat": cat, "key": key, "emoji": head[0], "name": head[1] if len(head) > 1 else head[0],
                "price": it["price"], "currency": it["currency"], "desc": it.get("desc", ""),
                "mode": it.get("mode"), "elite": _item_is_elite(it), "qty": chips.get(it["name"]),
            })
    return {
        "titles": {c: t for c, (t, _) in SHOP_CATEGORIES.items()}, "items": items,
        "packs": {"diamond": STARS_PACKS_DIAMOND, "dollar": STARS_PACKS_DOLLAR,
                  "diamond_rate": DIAMOND_STARS_RATE, "dollar_per_star": round(STARS_DOLLAR_PER_STAR, 2)},
    }


def shop_buy(uid, name, cat, key):
    if cat not in SHOP_CATEGORIES or key not in SHOP_CATEGORIES[cat][1]:
        return False, "Bunday buyum topilmadi."
    ok, msg = _perform_shop_purchase(uid, name, cat, key)
    return ok, re.sub(r"<[^>]+>", "", str(msg or "")).strip() or ("Xarid amalga oshdi." if ok else "Xarid amalga oshmadi.")


def _stars_for(kind, qty):
    """(sarlavha, ⭐ narxi, payload qismi) yoki (None, xato)."""
    if kind == "diamond":
        packs = dict(STARS_PACKS_DIAMOND)
        if qty in packs:
            return f"{qty} 💎 Olmos", packs[qty]
        if 1 <= qty <= 5000:
            return f"{qty} 💎 Olmos", qty * DIAMOND_STARS_RATE
        return None, "Olmos miqdori 1 dan 5000 gacha bo'lishi kerak."
    if kind == "dollar":
        packs = dict(STARS_PACKS_DOLLAR)
        if qty in packs:
            return f"{qty} 💵 Dollar", packs[qty]
        if 100 <= qty <= 1000000:
            return f"{qty} 💵 Dollar", max(1, int(math.ceil(qty / STARS_DOLLAR_PER_STAR)))
        return None, "Dollar miqdori kamida 100 bo'lishi kerak."
    return None, "Noma'lum to'lov turi."


def stars_invoice(uid, kind, qty=0, days=0, target=None):
    """Telegram Stars uchun to'lov havolasi (Mini App ichida ochiladi). (ok, havola/xato)."""
    kind = str(kind or "")
    try:
        if kind in ("diamond", "dollar"):
            title, stars = _stars_for(kind, int(qty))
            if title is None:
                return False, stars
            payload = f"{'diamondbuy' if kind == 'diamond' else 'dollarbuy'}_{uid}_{int(qty)}"
            desc = f"{title} — Hunter Mafia"
        elif kind == "coin":
            qty = int(qty)
            if not (1 <= qty <= 1000):
                return False, "Miqdor 1 dan 1000 gacha bo'lishi kerak."
            stars = hc_star_price(qty)
            title = f"{qty} 🪙 Hunter Coin"
            payload = f"hc_{uid}_{qty}"
            desc = f"{qty} Hunter Coin — jonli kurs bo'yicha"
        elif kind in ("elite", "elitegift"):
            plan = next((p for p in ELITE_PLANS if p["days"] == int(days)), None)
            if not plan:
                return False, "Bunday tarif yo'q."
            stars = plan["stars"]
            title = f"👑 ELITE — {plan['days']} kun"
            if kind == "elite":
                payload = f"elitepay_{uid}_{plan['days']}"
                desc = "Hunter ELITE obunasi"
            else:
                if not target:
                    return False, "Oluvchi ko'rsatilmagan."
                payload = f"elitegift_{uid}_{int(target)}_{plan['days']}"
                desc = "Hunter ELITE — do'stga sovg'a"
        else:
            return False, "Noma'lum to'lov turi."
        link = bot.create_invoice_link(title, desc, payload, "", "XTR", [types.LabeledPrice(label=title, amount=int(stars))])
        if not isinstance(link, str) or not link:
            return False, "To'lov havolasini yaratib bo'lmadi."
        return True, link
    except Exception:
        _logger.exception("Stars invoice xatoligi")
        return False, "To'lov tizimida xatolik. Keyinroq urinib ko'ring."


# ------------------------------------------------------------------ 👑 VIP (HUNTER ELITE)
def elite_buy(uid, days):
    plan = next((p for p in ELITE_PLANS if p["days"] == int(days)), None)
    if not plan:
        return False, "Bunday tarif yo'q."
    with db_lock:
        cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (plan["diamond"], uid, plan["diamond"]))
        paid = cur.rowcount > 0
        conn.commit()
    if not paid:
        return False, f"Yetarli olmos yo'q ({plan['diamond']} 💎 kerak)."
    grant_elite_days(uid, plan["days"])
    return True, f"👑 ELITE {plan['days']} kunga faollashtirildi!"


def elite_gift(uid, to_type, to, days):
    plan = next((p for p in ELITE_PLANS if p["days"] == int(days)), None)
    if not plan:
        return False, "Bunday tarif yo'q."
    target, err = _resolve_target(uid, to_type, to)
    if target is None:
        return False, err
    with db_lock:
        cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (plan["diamond"], uid, plan["diamond"]))
        paid = cur.rowcount > 0
        conn.commit()
    if not paid:
        return False, f"Yetarli olmos yo'q ({plan['diamond']} 💎 kerak)."
    grant_elite_days(target, plan["days"])
    safe_send(target, f"🎁 {mention(uid, user_dict(uid)['name'])} sizga <b>{plan['days']} kunlik 👑 ELITE</b> sovg'a qildi!")
    return True, f"{esc(user_dict(target)['name'])} ga {plan['days']} kunlik ELITE sovg'a qilindi!"


# ------------------------------------------------------------------ 🔁 O'TKAZMA (dollar / olmos / coin / inventar)
_TRANSFER_LOCK = threading.Lock()
_TRANSFER_COLS = {"dollar": ("dollar", "💵"), "diamond": ("diamond", "💎"), "coin": ("coin", "🪙")}


def transfer_money(uid, to_type, to, what, amount, item=None):
    """(ok, xabar) — bir foydalanuvchidan boshqasiga o'tkazma. Hammasi atomik."""
    what = str(what or "")
    try:
        amount = int(amount)
    except Exception:
        return False, "Miqdor butun son bo'lishi kerak."
    if not (1 <= amount <= 10000000):
        return False, "Miqdor noto'g'ri."
    if is_banned(uid):
        return False, "Siz bloklangansiz."
    if not _rate_ok(uid, "transfer", 20, 3600):
        return False, "Bir soatda juda ko'p o'tkazma — birozdan keyin urinib ko'ring."
    target, err = _resolve_target(uid, to_type, to)
    if target is None:
        return False, err
    sender_name = user_dict(uid)["name"]
    if what in _TRANSFER_COLS:
        col, icon = _TRANSFER_COLS[what]
        with db_lock:
            cur.execute(f"UPDATE users SET {col} = {col} - ? WHERE user_id=? AND {col} >= ?", (amount, uid, amount))
            if cur.rowcount == 0:
                return False, f"Sizda yetarli {what} yo'q."
            cur.execute(f"UPDATE users SET {col} = {col} + ? WHERE user_id=?", (amount, target))
            conn.commit()
        label = f"{amount} {icon}"
    elif what == "inventory":
        chips = {c["key"]: c for c in _inventory_chips(uid)}
        if item not in chips:
            return False, "Bunday buyum topilmadi."
        with _TRANSFER_LOCK:
            if item == "shield":
                with db_lock:
                    cur.execute("UPDATE users SET shield = shield - ? WHERE user_id=? AND shield >= ?", (amount, uid, amount))
                    if cur.rowcount == 0:
                        return False, "Sizda yetarli buyum yo'q."
                    cur.execute("UPDATE users SET shield = shield + ? WHERE user_id=?", (amount, target))
                    conn.commit()
            else:
                if not use_charge(uid, item, amount):
                    return False, "Sizda yetarli buyum yo'q."
                add_charge(target, item, amount)
        label = f"{amount} × {chips[item]['name']}"
    else:
        return False, "Noma'lum o'tkazma turi."
    safe_send(target, f"🎁 {mention(uid, sender_name)} sizga <b>{label}</b> yubordi!")
    return True, f"{esc(user_dict(target)['name'])} ga {label} yuborildi!"


