_AVATAR_SCHEMA_LOCK = threading.Lock()

def _avatar_init_db():
    with db_lock:
        cur.execute("""CREATE TABLE IF NOT EXISTS hm_avatar_defs(
            avatar_id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL,
            name TEXT NOT NULL, gender TEXT NOT NULL, rarity TEXT NOT NULL,
            price INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'diamond',
            active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0,
            colors TEXT NOT NULL DEFAULT '{}', created_at REAL NOT NULL)""")
        cur.execute("""CREATE TABLE IF NOT EXISTS hm_avatar_clothes(
            item_id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL,
            name TEXT NOT NULL, gender TEXT NOT NULL, slot TEXT NOT NULL,
            price INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'diamond',
            active INTEGER NOT NULL DEFAULT 1, rarity TEXT NOT NULL DEFAULT 'Rare',
            colors TEXT NOT NULL DEFAULT '{}', created_at REAL NOT NULL)""")
        cur.execute("""CREATE TABLE IF NOT EXISTS hm_user_avatar(
            user_id INTEGER PRIMARY KEY, avatar_code TEXT NOT NULL, body_json TEXT NOT NULL DEFAULT '{}',
            owned_json TEXT NOT NULL DEFAULT '[]', equipped_json TEXT NOT NULL DEFAULT '{}',
            updated_at REAL NOT NULL)""")
        conn.commit()
    _avatar_seed()

def _avatar_seed():
    now=time.time()
    avatars=[
      ('starter_f1','Luna','female','Starter',0,'diamond',1,10),('starter_f2','Mira','female','Starter',0,'diamond',1,11),
      ('starter_m1','Kael','male','Starter',0,'diamond',1,12),('starter_m2','Arin','male','Starter',0,'diamond',1,13),
      ('mythic_f1','Aurelia','female','Mythic',750,'diamond',1,20),('mythic_f2','Nyxara','female','Mythic',850,'diamond',1,21),
      ('mythic_f3','Selene','female','Mythic',950,'diamond',1,22),('mythic_f4','Veyra','female','Mythic',1100,'diamond',1,23),
      ('mythic_m1','Draven','male','Mythic',750,'diamond',1,30),('mythic_m2','Aether','male','Mythic',850,'diamond',1,31),
      ('mythic_m3','Riven','male','Mythic',950,'diamond',1,32),('mythic_m4','Valen','male','Mythic',1100,'diamond',1,33),
      ('legendary_f','Elysia','female','Legendary',2500,'diamond',1,40),('legendary_m','Lucian','male','Legendary',2500,'diamond',1,41)]
    with db_lock:
        for code,name,g,r,price,curr,active,order in avatars:
            cur.execute("INSERT OR IGNORE INTO hm_avatar_defs(code,name,gender,rarity,price,currency,active,sort_order,colors,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",
                        (code,name,g,r,price,curr,active,order,json.dumps({'skin':'#d8b08c','hair':'#201915','eyes':'#55d9b0','accent':'#d7b64a'}),now))
        slots=['head','hair','face','top','bottom','shoes','cloak','armor','weapon','accessory']
        for gender in ('female','male'):
            for i in range(1,101):
                slot=slots[(i-1)%len(slots)]
                code=f'{gender}_clothing_{i:03d}'
