def _v8_route_get(h, parsed):
    fn = _V8_GET.get(parsed.path)
    if fn is None:
        return False
    qs = parse_qs(parsed.query)
    uid, _name = _v8_auth((qs.get("init_data") or [""])[0])
    if uid is None:
        h._send_json({"error": "invalid_init_data"}, status=401)
        return True
    try:
        payload = fn(uid, qs)
        if isinstance(payload, dict):
            payload = dict(payload)
            payload.setdefault("balance", _v8_balance(uid))
        h._send_json(payload)
    except Exception:
        _logger.exception("API GET xatoligi: %s", parsed.path)
        h._send_json({"error": "server_error"}, status=500)
    return True


def _v8_route_post(h, path, body):
    """True — yo'nalish tanildi (javob yuborildi); False — noma'lum yo'nalish."""
    known = {"/api/daily_bonus_claim", "/api/quest_claim", "/api/support", "/api/hero_action", "/api/fate_list", "/api/avatar_buy", "/api/avatar_save",
             "/api/fate_unlist", "/api/fate_buy", "/api/pair_random", "/api/pair_respond", "/api/premium_buy",
             "/api/news_seen", "/api/shop_buy", "/api/stars_invoice", "/api/elite_buy", "/api/elite_gift",
             "/api/transfer", "/api/resolve_target", "/api/hc_buy", "/api/role_ticket_buy",
             "/api/pair_gift", "/api/fate_boost", "/api/legend_like",
             "/api/world2_choice", "/api/world23_npc", "/api/world23_quest",
             "/api/world22_npc", "/api/world21_event", "/api/world21_quest", "/api/world21_equip"}
    if path not in known:
        return False
    uid, name = _v8_auth(body.get("init_data") if isinstance(body, dict) else "")
    if uid is None:
        h._send_json({"error": "invalid_init_data"}, status=401)
        return True
    if not _rate_ok(uid, "api_post", 40, 60):
        h._send_json({"ok": False, "error": "Juda tez — birozdan keyin urinib ko'ring."}, status=429)
        return True
    try:
        res = {"ok": False, "error": "Noma'lum amal."}
        if path == "/api/daily_bonus_claim":
            res = _perform_daily_bonus(uid, name)
        elif path == "/api/quest_claim":
            ok, msg, reward = quest_claim(uid, str(body.get("key", "")))
            res = {"ok": ok, "message": msg, "reward": reward}
        elif path == "/api/support":
            ok, err = support_send(uid, name, str(body.get("text", "")), body.get("photo"))
            res = {"ok": ok, "error": err} if not ok else {"ok": True}
        elif path == "/api/shop_buy":
            ok, msg = shop_buy(uid, name, str(body.get("cat", "")), str(body.get("key", "")))
            res = {"ok": ok, "message": msg}
        elif path == "/api/stars_invoice":
            ok, r = stars_invoice(uid, body.get("kind"), body.get("qty", 0), body.get("days", 0), body.get("target"))
            res = {"ok": ok, "link": r} if ok else {"ok": False, "message": r}
        elif path == "/api/elite_buy":
            ok, msg = elite_buy(uid, int(body.get("days", 0)))
            res = {"ok": ok, "message": msg}
        elif path == "/api/elite_gift":
            ok, msg = elite_gift(uid, body.get("to_type"), body.get("to"), int(body.get("days", 0)))
            res = {"ok": ok, "message": msg}
        elif path == "/api/avatar_buy":
            ok,msg,state=avatar_buy(uid,str(body.get("kind") or "avatar"),str(body.get("code") or "")); res={"ok":ok,"message":msg,"state":state}
        elif path == "/api/avatar_save":
            ok,msg,state=avatar_update(uid,body.get("body"),body.get("avatar_code"),body.get("equip")); res={"ok":ok,"message":msg,"state":state}
        elif path == "/api/hc_buy":
            ok, msg, _c, _r = hc_buy_with_diamonds(uid, body.get("qty"))
            res = {"ok": ok, "message": msg}
        elif path == "/api/role_ticket_buy":
            ok, msg, _price = role_ticket_buy(uid, str(body.get("role", "")))
            res = {"ok": ok, "message": msg}
        elif path == "/api/resolve_target":
            tid, err = _resolve_target(uid, body.get("to_type"), body.get("to"))
            res = {"ok": True, "uid": tid, "name": user_dict(tid)["name"]} if tid is not None else {"ok": False, "message": err}
        elif path == "/api/transfer":
            ok, msg = transfer_money(uid, body.get("to_type"), body.get("to"), body.get("what"), body.get("amount"), body.get("item"))
            res = {"ok": ok, "message": msg}
        elif path == "/api/hero_action":
            ok, msg = hero_action(uid, str(body.get("action", "")), body.get("key"))
            res = {"ok": ok, "message": msg}
        elif path == "/api/fate_list":
            ok, msg = fate_list(uid, body.get("price"), str(body.get("quote", "")))
            res = {"ok": ok, "message": msg}
        elif path == "/api/fate_unlist":
            ok, msg = fate_unlist(uid)
            res = {"ok": ok, "message": msg}
        elif path == "/api/fate_buy":
            ok, msg = fate_buy(uid, int(body.get("seller_id", 0)))
            res = {"ok": ok, "message": msg}
        elif path == "/api/pair_random":
            ok, r = pair_random_request(uid)
            res = {"ok": ok, "id": r} if ok else {"ok": False, "message": r}
        elif path == "/api/pair_respond":
            ok, msg = pair_respond(uid, int(body.get("id", 0)), bool(body.get("accept")))
            res = {"ok": ok, "message": msg}
        elif path == "/api/pair_gift":
            ok, msg = pair_gift(uid, str(body.get("gift", "")))
            res = {"ok": ok, "message": msg}
        elif path == "/api/fate_boost":
            ok, msg = fate_boost(uid)
            res = {"ok": ok, "message": msg}
        elif path == "/api/legend_like":
            try:
                with db_lock:
                    cur.execute("UPDATE legends SET likes = COALESCE(likes,0) + 1 WHERE id=?", (int(body.get("id", 0)),))
                    conn.commit()
                res = {"ok": True}
            except Exception:
                res = {"ok": False, "error": "Xatolik"}
        elif path == "/api/premium_buy":
            ok, msg, link = premium_buy(uid, int(body.get("id", 0)))
            res = {"ok": ok, "message": msg, "link": link}
        elif path == "/api/world2_choice":
            ok,msg,state=world2_choice(uid,str(body.get("key", ""))); res={"ok":ok,"message":msg,"state":state}
        elif path in ("/api/world23_npc","/api/world22_npc"):
            ok,msg,state=world23_npc(uid,str(body.get("key", ""))); res={"ok":ok,"message":msg,"state":state}
        elif path in ("/api/world23_quest","/api/world21_quest"):
            ok,msg,state=world23_quest(uid,str(body.get("key", ""))); res={"ok":ok,"message":msg,"state":state}
        elif path == "/api/world21_event":
            ok,msg,state=world21_event(uid); res={"ok":ok,"message":msg,"state":state}
        elif path == "/api/world21_equip":
            ok,msg,state=world21_equip(uid,str(body.get("kind", "")),str(body.get("value", ""))); res={"ok":ok,"message":msg,"state":state}
        elif path == "/api/news_seen":
            news_mark_seen(uid)
            res = {"ok": True}
        res = dict(res)
        res["balance"] = _v8_balance(uid)
        h._send_json(res)
    except (ValueError, TypeError):
        h._send_json({"ok": False, "error": "Noto'g'ri so'rov."}, status=400)
    except Exception:
        _logger.exception("API POST xatoligi: %s", path)
        h._send_json({"ok": False, "error": "server_error"}, status=500)
    return True



# ------------------------------------------------------------------ 🔗 Mini App deep-link'lari va /yordam
def _handle_start_payload_v8(message, payload):
    """Mini App'dagi tugmalar ochadigan t.me/BOT?start=... havolalari. True — qayta ishlandi."""
    uid, chat = message.from_user.id, message.chat.id
    if payload == "daily_bonus":
        res = _perform_daily_bonus(uid, message.from_user.first_name)
        if res["already"]:
            bot.send_message(chat, "⏳ Siz bugungi bonusni allaqachon olgansiz!", reply_markup=with_back_button())
        else:
            what = f"+{res['amount']}$ Dollar" if res["kind"] == "dollar" else f"{res['amount']} ta 💎 Olmos"
            extra = f"\n🎉 Seriya mukofoti: +{res['streak_diamond']} 💎" if res["streak_diamond"] else ""
            bot.send_message(chat, f"🎁 Bonus: {what}!\n🔥 Seriya: {res['streak']}-kun{extra}", reply_markup=with_back_button())
        return True
    if payload.startswith("quest_claim_"):
        ok, msg, _reward = quest_claim(uid, payload[len("quest_claim_"):])
        bot.send_message(chat, ("📜 " if ok else "❌ ") + msg, reply_markup=with_back_button())
        return True
    if payload == "support":
        bot.send_message(chat, "💬 Savolingizni shu yerga yozing: <code>/savol Savol matni</code>\nYoki Mini App → Yordam bo'limidan.")
        return True
    if payload == "hero":
        show_hero_panel(chat, uid)
        return True
    if payload.startswith("box_open_"):
        bot.send_message(chat, "🗝 Sandiq botning o'zida: <code>/sandiq</code>")
        return True
    if payload.startswith("gamble_"):
        bot.send_message(chat, "🎰 Omad o'yini botning o'zida: <code>/gildirak</code>")
        return True
    return False


@bot.message_handler(commands=["savol"])
def cmd_savol(message):
    """💬 /savol <matn> — bot egasiga savol yuborish (javob shu chatga keladi).
    (/yordam — buyruqlar ro'yxati uchun band, shuning uchun savol buyrug'i /savol.)"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if message.chat.type != "private":
        bot.send_message(message.chat.id, "💬 Savol yuborish uchun botning shaxsiy chatida yozing: /savol Savol matni")
        return
    parts = (message.text or "").split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id, "💬 Foydalanish: <code>/savol Savol matni</code>")
        return
    ok, err = support_send(message.from_user.id, message.from_user.first_name, parts[1])
    bot.send_message(message.chat.id, "✅ Xabaringiz yuborildi. Javob shu yerga keladi." if ok else f"❌ {err}")


