        kb.add(types.InlineKeyboardButton("↩️ Kursni bazaviyga qaytarish", callback_data="admin|v8|hc_reset"))
        for var, label in (("HC_BASE_DIAMOND_RATE", "✏️ Bazaviy narx (💎)"), ("HC_MARKET_VOLATILITY_PCT", "✏️ Tebranish (%)"),
                           ("HC_RATE_MIN_MULT", "✏️ Pastki chegara (0.85 = 85%)"), ("HC_RATE_MAX_MULT", "✏️ Yuqori chegara (1.15 = 115%)"),
                           ("HC_MARKET_UPDATE_MINUTES", "✏️ Yangilanish oralig'i (daqiqa)")):
            kb.add(types.InlineKeyboardButton(label, callback_data=f"admin|tune_edit|{var}"))
