class _KeepAliveHandler(BaseHTTPRequestHandler):
    def _send_json(self, payload, status=200):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Access-Control-Allow-Origin", "*")  # 🌐 GitHub Pages'dan (boshqa domendan) chaqirish uchun
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parsed = urlparse(self.path)

        # 🧩 v8: yangi Mini App yo'nalishlari (kunlik mukofot, vazifalar, geroy, Taqdir, Premium, yordam...)
        if _v8_route_get(self, parsed):
            return

        # 🎴 Mini App uchun — foydalanuvchining o'z balansi/statistikasi
        if parsed.path == "/api/profile":
            qs = parse_qs(parsed.query)
            init_data = (qs.get("init_data") or [""])[0]
            tg_user = _verify_telegram_webapp_init_data(init_data)
            if tg_user is None or "id" not in tg_user:
                self._send_json({"error": "invalid_init_data"}, status=401)
                return
            uid = int(tg_user["id"])
            u = user_dict(uid, tg_user.get("first_name"))
            ch = get_charges(uid)
            games, wins = u["games"], u["wins"]
            losses = max(0, games - wins)
            rating_pct = round(wins / games * 100) if games else 0
            vip_until = ch.get("vip_until", 0)
            vip_days_left = max(0, int((vip_until - time.time()) // 86400)) if vip_until > time.time() else 0
            partner_id = get_partner_id(uid)
            partner_name = user_dict(partner_id)["name"] if partner_id else None
            self._send_json({
                "name": u["name"], "uid": uid,
                "dollar": u["dollar"], "coin": u["coin"], "diamond": u["diamond"],
                "wins": wins, "games": games, "losses": losses, "rating_pct": rating_pct,
                "vip_days_left": vip_days_left, "married_to": partner_name,
                # 🧩 v8: daraja/XP, ball va seriya
                "xp": xp_of_user(u), "level": level_progress(xp_of_user(u))[0],
                "xp_in_level": level_progress(xp_of_user(u))[1], "xp_per_level": XP_PER_LEVEL,
                "points_total": _points_summary(uid)[0], "win_streak": _points_summary(uid)[1],
            })
            return

        # 📈 Mini App uchun — jonli Hunter Coin kursi (hech qanday autentifikatsiya kerak emas, ochiq ma'lumot)
        if parsed.path == "/api/hc_rate":
            self._send_json({
                "diamond": HC_DIAMOND_RATE, "dollar": HC_DOLLAR_RATE,
                "prev_diamond": HC_PREV_DIAMOND_RATE, "prev_dollar": HC_PREV_DOLLAR_RATE,
            })
            return

        # 🛒 Mini App "Do'kon" bo'limi — botning HAQIQIY 3 ta katalogidan (hech qanday
        # autentifikatsiya kerak emas, narxlar ochiq ma'lumot)
        if parsed.path == "/api/shop_items":
            catalog = []
            for cat, (title, items) in SHOP_CATEGORIES.items():
                for key, item in items.items():
                    catalog.append({
                        "cat": cat, "key": key, "name": item["name"], "price": item["price"],
                        "currency": item["currency"], "desc": item.get("desc", ""),
                    })
            self._send_json({"categories": {c: t for c, (t, _) in SHOP_CATEGORIES.items()}, "items": catalog})
            return

        # ✨ Mini App "Kosmetika" bo'limi — bot egasi haqiqatda sotuvga chiqargan
        # ramka/animatsiya/skin buyumlari (narx va qolgan tiraj bazadan jonli)
        if parsed.path == "/api/cosmetics":
            qs = parse_qs(parsed.query)
            init_data = (qs.get("init_data") or [""])[0]
            tg_user = _verify_telegram_webapp_init_data(init_data) if init_data else None
            uid = int(tg_user["id"]) if tg_user and "id" in tg_user else None
            with db_lock:
                cur.execute("SELECT id, kind, name, emoji, price, currency, stock, sold FROM cosmetics WHERE active=1 ORDER BY id DESC")
                rows = cur.fetchall()
                owned_ids = set()
                if uid:
                    cur.execute("SELECT cosmetic_id FROM user_cosmetics WHERE user_id=?", (uid,))
                    owned_ids = {r[0] for r in cur.fetchall()}
            items = []
            for cid, kind, name, emoji, price, currency, stock, sold in rows:
                left = stock - sold
                if left <= 0:
                    continue
                items.append({
                    "id": cid, "kind": kind, "name": name, "emoji": emoji, "price": price,
                    "currency": currency, "stock": stock, "left": left, "owned": cid in owned_ids,
                })
            self._send_json({"items": items})
            return

        # 🏛 Mini App "Klan" bo'limi — foydalanuvchining o'z klani (bor bo'lsa)
        if parsed.path == "/api/clan":
            qs = parse_qs(parsed.query)
            init_data = (qs.get("init_data") or [""])[0]
            tg_user = _verify_telegram_webapp_init_data(init_data)
            if tg_user is None or "id" not in tg_user:
                self._send_json({"error": "invalid_init_data"}, status=401)
                return
            uid = int(tg_user["id"])
            owner_id = find_member_clan(uid)
            if not owner_id:
                self._send_json({"has_clan": False})
                return
            clan = get_clan(owner_id)
            with db_lock:
                cur.execute("SELECT member_id, member_name FROM clan_members WHERE owner_id=?", (owner_id,))
                member_rows = cur.fetchall()
            leader_row = user_dict(owner_id)
            members = [{"uid": owner_id, "name": leader_row["name"], "role": "Lider"}]
            for mid, mname in member_rows:
                role = "O'rinbosar" if clan.get("deputy_id") == mid else "A'zo"
                members.append({"uid": mid, "name": mname, "role": role})
            self._send_json({
                "has_clan": True, "name": clan["name"], "level": clan["level"],
                "wins": clan["wins"], "losses": clan["losses"], "member_count": len(members),
                "is_leader": owner_id == uid, "members": members,
            })
            return

        # 🏆 Mini App "Reyting" bo'limi — Server (oylik faollik ballari) | Guruh (shu guruh a'zolari)
        if parsed.path == "/api/top":
            qs = parse_qs(parsed.query)
            scope = (qs.get("scope") or ["server"])[0]
            init_data = (qs.get("init_data") or [""])[0]
            tg_user = _verify_telegram_webapp_init_data(init_data)
            uid = int(tg_user["id"]) if tg_user and "id" in tg_user else None

            if scope == "group":
                chat_id_param = (qs.get("chat_id") or [None])[0]
                chat_id = int(chat_id_param) if chat_id_param else None
                if chat_id is None and uid is not None:
                    with db_lock:
                        cur.execute(
                            "SELECT chat_id FROM group_members WHERE user_id=? ORDER BY last_seen DESC LIMIT 1", (uid,)
                        )
                        row = cur.fetchone()
                        chat_id = row[0] if row else None
                if chat_id is None:
                    self._send_json({"scope": "group", "rows": [], "note": "no_group_found"})
                    return
                member_ids = get_group_member_ids(chat_id)
                rows = get_top_players(limit=50, member_ids=member_ids)
                out = [{"uid": r[0], "name": r[1], "value": r[2], "label": "g'alaba"} for r in rows]
            else:
                rows = get_points_leaderboard("oy", limit=50)
                out = [{"uid": r[0], "name": r[1], "value": r[2], "label": "ball"} for r in rows]
            self._send_json({"scope": scope, "rows": out})
            return

        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.end_headers()
        self.wfile.write("🤖 Hunter Mafia bot tirik va ishlamoqda!".encode("utf-8"))

    def do_POST(self):
        """🧩 v8: Mini App amallari (JSON). Har so'rovda Telegram initData tekshiriladi."""
        parsed = urlparse(self.path)
        try:
            length = int(self.headers.get("Content-Length") or 0)
            if length > (1500000 if parsed.path == "/api/support" else 20000):
                self._send_json({"ok": False, "error": "too_large"}, status=413)
                return
            raw = self.rfile.read(length) if length else b""
            body = json.loads(raw.decode("utf-8")) if raw else {}
            if not isinstance(body, dict):
                raise ValueError("body")
        except Exception:
            self._send_json({"ok": False, "error": "bad_request"}, status=400)
            return
        if not _v8_route_post(self, parsed.path, body):
            self._send_json({"ok": False, "error": "not_found"}, status=404)

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    def log_message(self, format, *args):
        pass  # 🔇 har bir keep-alive so'rovini konsolga chiqarib, log'ni iflos qilmaymiz


def start_keepalive_server():
    """Render (yoki shunga o'xshash hostinglar) 'xizmat tirik' deb bilishi
    uchun kichik HTTP server ochadi. $PORT Render tomonidan avtomatik beriladi."""
    try:
        port = int(os.environ.get("PORT", "10000"))
        server = HTTPServer(("0.0.0.0", port), _KeepAliveHandler)
        t = threading.Thread(target=server.serve_forever, daemon=True)
        t.start()
        _logger.info("🌐 Keep-alive HTTP server %s portda ishga tushdi", port)
    except Exception as e:
        _logger.warning("Keep-alive HTTP server ochilmadi (muhim emas): %s", e)


def _self_ping_loop():
    """Har 10 daqiqada botning o'z tashqi manziliga (agar aniqlansa) so'rov
    yuboradi — Render'ning bepul tarifidagi 'uyquga ketish' vaqtini (~15 daqiqa
    faolsizlik) hech qachon to'ldirmaslik uchun."""
    external_url = (
        os.environ.get("RENDER_EXTERNAL_URL")  # Render web-service'lar uchun avtomatik beriladi
        or os.environ.get("KEEPALIVE_URL", "").strip()  # qo'lda ko'rsatilgan manzil (ixtiyoriy)
    )
    port = int(os.environ.get("PORT", "10000"))
    local_url = f"http://127.0.0.1:{port}/"
    while True:
        time.sleep(600)  # 10 daqiqa
        url = external_url or local_url
        try:
            requests.get(url, timeout=15)
            # 🔇 Muvaffaqiyatli self-ping endi HECH QANDAY xabar/log bermaydi —
            # har 10 daqiqada takrorlanaveradigan "tirik" xabari ortiqcha shovqin
            # qilmasin uchun ataylab o'chirilgan (faqat DEBUG darajasida qoladi,
            # standart INFO log darajasida ko'rinmaydi).
            _logger.debug("Self-ping muvaffaqiyatli: %s", url)
        except Exception as e:
            # ❗ Faqat HAQIQIY muammo bo'lsa (self-ping ishlamay qolsa) log yoziladi —
            # bu ham bot egasiga Telegram xabari sifatida YUBORILMAYDI, faqat
            # server logida qoladi, shunda ortiqcha Telegram xabarlari kelmaydi.
            _logger.warning("🌐 Self-ping muvaffaqiyatsiz (%s): %s", url, e)


def start_self_ping_loop():
    t = threading.Thread(target=_self_ping_loop, daemon=True)
    t.start()


def _daily_menu_broadcast_loop():
    """🕖 Har kuni soat 07:00 da (Toshkent vaqti, UTC+5) — botdagi BARCHA
    ro'yxatdan o'tgan foydalanuvchilarga BOSH MENYU avtomatik qayta yuboriladi
    (kunlik 🎁 bonus, do'kon va h.k.ni har kuni eslab, ko'rib turishsin deb)."""
    last_sent_date = None
    while True:
        try:
            now_tashkent = time.gmtime(time.time() + 5 * 3600)  # 🕔 UTC+5, DST yo'q
            today_str = time.strftime("%Y-%m-%d", now_tashkent)
            if now_tashkent.tm_hour == 7 and last_sent_date != today_str:
                last_sent_date = today_str
                with db_lock:
                    cur.execute("SELECT user_id FROM users")
                    user_ids = [r[0] for r in cur.fetchall()]
                sent, failed = 0, 0
                for target_uid in user_ids:
                    try:
                        bot.send_photo(
                            target_uid,
                            MAIN_PHOTO,
                            caption="🌅 <b>Xayrli tong!</b> Yangi kun boshlandi!\n\n"
                                    "🌙 <b>Hunter Mafia</b> — bosh menyu\n\n"
                                    "🎁 Kunlik bonusingizni olishni unutmang!\n\nKerakli bo'limni tanlang 👇",
                            reply_markup=get_main_menu(None, target_uid),
                        )
                        sent += 1
                    except Exception:
                        failed += 1
                    time.sleep(0.05)  # ⏱ Telegram'ning 429 (Too Many Requests) chegarasiga tegib ketmaslik uchun
                _logger.info("🕖 Kunlik soat 07:00 bosh menyu tarqatildi: %s ta muvaffaqiyatli, %s ta yetib bormadi.", sent, failed)
        except Exception as e:
            _logger.warning("_daily_menu_broadcast_loop xatolik: %s", e)
        time.sleep(60)  # ⏱ har daqiqada soat 07:00 bo'lganini tekshiradi


def start_daily_menu_broadcast_loop():
    t = threading.Thread(target=_daily_menu_broadcast_loop, daemon=True)
    t.start()



