def _weekly_report_loop():
    """📅 Har dushanba soat 09:00'da har bir foydalanuvchiga shaxsiy, qisqa
    haftalik statistika xabari yuboradi (reklama emas — faqat o'z natijasi).
    Mavjud kunlik 07:00 broadcast'ga o'xshab ishlaydi, lekin haftada bir marta
    va shaxsiylashtirilgan matn bilan."""
    last_sent_week = None
    while True:
        try:
            now_tashkent = time.gmtime(time.time() + 5 * 3600)
            year_week = time.strftime("%Y-%W", now_tashkent)
            if now_tashkent.tm_wday == 0 and now_tashkent.tm_hour == 9 and last_sent_week != year_week:
                last_sent_week = year_week
                with db_lock:
                    cur.execute("SELECT user_id FROM users WHERE games > 0")
                    user_ids = [r[0] for r in cur.fetchall()]
                sent, failed = 0, 0
                for target_uid in user_ids:
                    try:
                        bot.send_message(target_uid, _weekly_report_text(target_uid))
                        sent += 1
                    except Exception:
                        failed += 1
                    time.sleep(0.05)
                _logger.info("📅 Haftalik hisobot yuborildi: %s ta muvaffaqiyatli, %s ta yetib bormadi.", sent, failed)
        except Exception as e:
            _logger.warning("_weekly_report_loop xatolik: %s", e)
        time.sleep(60)


def start_weekly_report_loop():
    t = threading.Thread(target=_weekly_report_loop, daemon=True)
    t.start()


