# (alohida saqlanmaydi — har chaqirilganda joriy statistikaga qarab yangilanadi).
DESTINY_TITLES = [
    (0, "🌱 Yangi Ovchi", "Siz hali yo'l boshidasiz — Hunter World sizni sinab ko'rmoqda."),
    (5, "🔰 Tajribasiz Kuzatuvchi", "Bir nechta tunni boshdan kechirdingiz, ammo taqdiringiz hali yozilmagan."),
    (15, "⚔️ Sinovdan O'tgan Jangchi", "O'nlab kechalar sizni chiniqtirdi — endi sizni hech narsa hayron qoldirmaydi."),
    (30, "🎭 Ikkiyuzlamachi Usta", "Ko'p marta rol o'ynadingiz — endi kim ekaningizni hech kim bilolmaydi."),
    (60, "👑 Hunter World Afsonasi", "Sizning nomingiz allaqachon afsonalarga kirgan — kam kishi shu darajaga yetadi."),
]


def compute_destiny(uid):
    u = user_dict(uid)
    games = u.get("games", 0)
    wins = u.get("wins", 0)
    winrate = int(100 * wins / games) if games else 0
    title, base_flavor = DESTINY_TITLES[0][1], DESTINY_TITLES[0][2]
    for threshold, t, flavor in DESTINY_TITLES:
        if games >= threshold:
            title, base_flavor = t, flavor
    fav = favorite_role(uid)
    fav_line = ""
    if fav:
        stats = next((r for r in role_stats_of(uid) if r["role"] == fav), None)
        if stats and stats["games"]:
            role_wr = int(100 * stats["wins"] / stats["games"])
            fav_line = f"\n\n🎭 Eng ko'p <b>{esc(fav)}</b> rolida o'ynagansiz ({stats['games']} marta, g'alaba: {role_wr}%)."
    next_row = next((row for row in DESTINY_TITLES if row[0] > games), None)
    progress_line = f"\n\n📈 Keyingi unvongacha: {next_row[0] - games} ta o'yin qoldi." if next_row else "\n\n🏆 Siz eng yuqori unvonga yetdingiz!"
    text = (f"🎭 <b>Taqdir yo'lingiz:</b> {title}\n\n<i>{base_flavor}</i>\n\n"
            f"🎮 Jami o'yin: {games} | 🏆 G'alaba: {wins} ({winrate}%)"
            f"{fav_line}{progress_line}")
    return title, text


