def v11_send_random_event():
    """v10_send_random_event() o'rniga chaqiriladi — 4 formatdan birini tasodifiy tanlaydi."""
    groups = [g for g in list_known_groups() if gsv(g[0], "world_events") != "0"]
    if not groups:
        return
    chat_id, _title = random.choice(groups)
    fmt = random.choice(["first", "number", "reverse", "trivia"])

    if fmt == "first":
        v10_send_random_event()  # mavjud, o'zgarishsiz format
        return

    if fmt == "number":
        target = random.randint(1, 50)
        with _V10_EVENT_LOCK:
            _V10_EVENT_STATE[chat_id] = {"mode": "number", "target": target, "guesses": {},
                                          "expires_at": time.time() + 40, "claimed": False}
        try:
            bot.send_message(chat_id, "🔢 <b>Tasodifiy voqea!</b>\nMen 1 dan 50 gacha son o'yladim. "
                                       "Kim eng yaqin taxmin qilsa — g'olib!\n✏️ <code>/topraqam son</code>")
        except Exception:
            pass
        return

    if fmt == "reverse":
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton(f"🎯 Bos! (IKKINCHI bosgan yutadi)", callback_data="v10ev|claim"))
        try:
            msg = bot.send_message(chat_id, "🎯 <b>Aksincha voqea!</b>\nBu safar BIRINCHI bosgan emas, "
                                             "IKKINCHI bosgan yutadi! Shoshilmang 😏", reply_markup=kb)
        except Exception:
            return
        with _V10_EVENT_LOCK:
            _V10_EVENT_STATE[chat_id] = {"mode": "reverse", "message_id": msg.message_id, "click_count": 0,
                                          "claimed": False, "expires_at": time.time() + 40}
        return

    if fmt == "trivia":
        q, a = random.choice(TRIVIA_QA)
        with _V10_EVENT_LOCK:
            _V10_EVENT_STATE[chat_id] = {"mode": "trivia", "answer": a.lower(), "claimed": False,
                                          "expires_at": time.time() + 60}
        try:
            bot.send_message(chat_id, f"🧠 <b>Tezkor savol!</b>\n{q}\n\n✏️ Javobni oddiy xabar qilib yozing.")
        except Exception:
            pass


@bot.message_handler(commands=["topraqam"])
def cmd_topraqam(message):
    chat_id = message.chat.id
    with _V10_EVENT_LOCK:
        st = _V10_EVENT_STATE.get(chat_id)
        if not st or st.get("mode") != "number" or st["claimed"] or time.time() > st["expires_at"]:
            return
        parts = (message.text or "").split()
        if len(parts) < 2:
            return
        try:
            guess = int(parts[1])
        except ValueError:
            return
        st["guesses"][message.from_user.id] = (guess, message.from_user.first_name or "O'yinchi")


def _v11_resolve_number_event(chat_id, st):
    if not st["guesses"]:
        return
    target = st["target"]
    winner_uid, (winner_guess, winner_name) = min(st["guesses"].items(), key=lambda kv: abs(kv[1][0] - target))
    add_balance(winner_uid, dollar=RANDOM_EVENT_REWARD)
    try:
        bot.send_message(chat_id, f"🔢 Men <b>{target}</b> ni o'ylagan edim!\n🏆 <b>{esc(winner_name)}</b> "
                                   f"eng yaqin taxmin ({winner_guess}) bilan +{RANDOM_EVENT_REWARD}$ yutdi!")
    except Exception:
        pass


@bot.message_handler(func=lambda m: m.chat.id in _V10_EVENT_STATE and
                      _V10_EVENT_STATE[m.chat.id].get("mode") == "trivia" and
                      not _V10_EVENT_STATE[m.chat.id]["claimed"] and
                      time.time() <= _V10_EVENT_STATE[m.chat.id]["expires_at"] and
                      (m.text or "").strip().lower() == _V10_EVENT_STATE[m.chat.id]["answer"])
def cmd_trivia_answer(message):
    chat_id = message.chat.id
    with _V10_EVENT_LOCK:
        st = _V10_EVENT_STATE.get(chat_id)
        if not st or st["claimed"]:
            return
        st["claimed"] = True
    uid = message.from_user.id
    name = message.from_user.first_name or "O'yinchi"
    add_balance(uid, dollar=RANDOM_EVENT_REWARD)
    bot.send_message(chat_id, f"🧠 <b>{esc(name)}</b> to'g'ri javob berdi va +{RANDOM_EVENT_REWARD}$ yutdi!")


def _v11_event_timeout_sweeper():
    """Fon siklida: muddati o'tgan 'number' voqealarni yakunlaydi."""
    with _V10_EVENT_LOCK:
        items = list(_V10_EVENT_STATE.items())
    now = time.time()
    for chat_id, st in items:
        if st.get("mode") == "number" and not st["claimed"] and now > st["expires_at"]:
            with _V10_EVENT_LOCK:
                st["claimed"] = True
            _v11_resolve_number_event(chat_id, st)


# ================================================================================
#  🃏 5) XARAKTER KARTALARI — kombinatsiya bonusi, almashish, kolleksioner
# ================================================================================
CARD_COMBO_ROLE_MAP = {
    "sadoqatli_doktor": ("Doktor", 0.10),   # 3x karta → Doktor bo'lganda +10% muvaffaqiyat
    "sovuq_komissar": ("Komissar", 0.10),
    "qora_niqob": ("Mafiya", 0.08),
}
COLLECTOR_BADGE_LIMIT = 10


def v11_apply_card_combo_bonus(uid, role):
    """end_game() ichida rol natijasini hal qilishdan OLDIN chaqirilishi mumkin:
    agar o'yinchida shu rolga bog'liq kartadan 3+ dona bo'lsa, qo'shimcha
    muvaffaqiyat ehtimolini (0..1 oralig'ida) qaytaradi, bo'lmasa 0."""
    if not role:
        return 0.0
    with db_lock:
        cur.execute("SELECT card_id, count FROM user_cards WHERE user_id=?", (uid,))
        owned = dict(cur.fetchall())
    bonus = 0.0
    for card_id, (role_hint, pct) in CARD_COMBO_ROLE_MAP.items():
        if role_hint in role and owned.get(card_id, 0) >= 3:
            bonus += pct
    return bonus


def v11_check_collector_badge(uid):
    with db_lock:
        cur.execute("SELECT COUNT(DISTINCT card_id) FROM user_cards WHERE user_id=?", (uid,))
        distinct = cur.fetchone()[0]
    if distinct < len(CHARACTER_CARDS):
        return False
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM (SELECT user_id FROM user_cards GROUP BY user_id "
                    "HAVING COUNT(DISTINCT card_id) >= ?)", (len(CHARACTER_CARDS),))
        rank = cur.fetchone()[0]
    return rank <= COLLECTOR_BADGE_LIMIT


@bot.message_handler(commands=["karta_almashtir"])
def cmd_karta_almashtir(message):
    """🃏 Foydalanish: /karta_almashtir @user mening_kartam_id uning_kartasi_id
    Ikkala tomon ham /tasdiqla <savdo_id> deb tasdiqlashi kerak."""
    maybe_capture_owner(message.from_user)
    parts = (message.text or "").split()
    if len(parts) < 4 or not message.reply_to_message:
        bot.send_message(message.chat.id, "Foydalanish: kimningdir xabariga reply qilib\n"
                                           "<code>/karta_almashtir mening_karta_id uning_karta_id</code>")
        return
    to_user = message.reply_to_message.from_user
    from_card, to_card = parts[1], parts[2] if len(parts) > 2 else parts[1]
    if from_card not in CHARACTER_CARDS or to_card not in CHARACTER_CARDS:
        bot.send_message(message.chat.id, "❌ Noto'g'ri karta ID. /kartalarim orqali ID'larni ko'ring.")
        return
    with db_lock:
        cur.execute("INSERT INTO card_trades (from_uid, to_uid, from_card, to_card, created_at) VALUES (?,?,?,?,?)",
                    (message.from_user.id, to_user.id, from_card, to_card, time.time()))
        trade_id = cur.lastrowid
        conn.commit()
    bot.send_message(message.chat.id, f"🔄 Savdo #{trade_id} boshlandi. Ikkalangiz ham "
                                       f"<code>/tasdiqla {trade_id}</code> deb yozing.")


@bot.message_handler(commands=["tasdiqla"])
def cmd_tasdiqla_savdo(message):
    parts = (message.text or "").split()
    if len(parts) < 2:
        return
    try:
        trade_id = int(parts[1])
    except ValueError:
        return
    uid = message.from_user.id
    with db_lock:
        cur.execute("SELECT from_uid, to_uid, from_card, to_card, from_ok, to_ok, status FROM card_trades WHERE id=?",
                    (trade_id,))
        row = cur.fetchone()
        if not row or row[6] != "pending":
            bot.send_message(message.chat.id, "❌ Savdo topilmadi yoki allaqachon yakunlangan.")
            return
        from_uid, to_uid, from_card, to_card, from_ok, to_ok, status = row
        if uid not in (from_uid, to_uid):
            return
        if uid == from_uid:
            from_ok = 1
        else:
            to_ok = 1
        cur.execute("UPDATE card_trades SET from_ok=?, to_ok=? WHERE id=?", (from_ok, to_ok, trade_id))
        conn.commit()
        if from_ok and to_ok:
            cur.execute("SELECT count FROM user_cards WHERE user_id=? AND card_id=?", (from_uid, from_card))
            r1 = cur.fetchone()
            if not r1 or r1[0] < 1:
                cur.execute("UPDATE card_trades SET status='failed' WHERE id=?", (trade_id,))
                conn.commit()
                bot.send_message(message.chat.id, "❌ Savdo bekor qilindi — kartalardan biri yetarli emas.")
                return
            cur.execute("UPDATE user_cards SET count=count-1 WHERE user_id=? AND card_id=?", (from_uid, from_card))
            cur.execute("INSERT INTO user_cards (user_id, card_id, count, obtained_at) VALUES (?,?,1,?) "
                        "ON CONFLICT(user_id, card_id) DO UPDATE SET count=count+1", (to_uid, from_card, time.time()))
            cur.execute("UPDATE user_cards SET count=count-1 WHERE user_id=? AND card_id=?", (to_uid, to_card))
            cur.execute("INSERT INTO user_cards (user_id, card_id, count, obtained_at) VALUES (?,?,1,?) "
                        "ON CONFLICT(user_id, card_id) DO UPDATE SET count=count+1", (from_uid, to_card, time.time()))
            cur.execute("UPDATE card_trades SET status='done' WHERE id=?", (trade_id,))
            conn.commit()
            bot.send_message(message.chat.id, f"✅ Savdo #{trade_id} yakunlandi — kartalar almashtirildi!")


# ================================================================================
#  🧩 6) ARG JUMBOQ ZANJIRI — 3 bosqich, DM orqali, hudud mukofoti
# ================================================================================
@bot.message_handler(commands=["jumboq_qosh"])
def cmd_jumboq_qosh_v11(message):
    """🧩 v10'dagi /jumboq_qosh ni ALMASHTIRADI — endi 3 bosqichli zanjir yaratadi.
    Foydalanish: /jumboq_qosh javob1 | matn1 || javob2 | matn2 || javob3 | matn3"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    raw = (message.text or "").split(maxsplit=1)
    if len(raw) < 2 or "||" not in raw[1]:
        bot.send_message(message.chat.id,
                          "Foydalanish:\n<code>/jumboq_qosh javob1 | matn1 || javob2 | matn2 || javob3 | matn3</code>")
        return
    stages = raw[1].split("||")
    if len(stages) != 3:
        bot.send_message(message.chat.id, "❌ Aniq 3 ta bosqich kerak (|| bilan ajratilgan).")
        return
    with db_lock:
        cur.execute("UPDATE arg_puzzles SET active=0 WHERE active=1")
        chain_id = int(time.time())
        for i, stage in enumerate(stages, start=1):
            bits = [b.strip() for b in stage.split("|")]
            answer = _v10_normalize_answer(bits[0])
            riddle = bits[1] if len(bits) > 1 else "???"
            cur.execute("INSERT INTO arg_puzzles (riddle, answer, reward, active, created_at, chain_stage, chain_id, "
                        "territory_reward) VALUES (?,?,?,?,?,?,?,?)",
                        (riddle, answer, 200 * i, 1 if i == 1 else 0, time.time(), i, chain_id, 1 if i == 3 else 0))
        conn.commit()
    text = (f"🧩 <b>Yangi sirli topshiriq zanjiri boshlandi!</b>\n\n{esc(stages[0].split('|')[1].strip() if '|' in stages[0] else '???')}\n\n"
            f"✏️ Javobni <code>/jumboq javobingiz</code> deb yuboring.\n"
            f"🏆 Zanjirni oxirigacha yechgan klan BEPUL hudud yutadi!")
    sent = 0
    for chat_id, _t in list_known_groups():
        try:
            bot.send_message(chat_id, text)
            sent += 1
        except Exception:
            pass
    bot.send_message(message.chat.id, f"✅ 1-bosqich {sent} ta guruhga yuborildi.")


@bot.message_handler(commands=["jumboq"])
def cmd_jumboq_v11(message):
    """🧩 v10'dagi /jumboq ni ALMASHTIRADI — zanjirni qo'llab-quvvatlaydi:
    to'g'ri javob berilsa, KEYINGI bosqich shu odamga shaxsiy DM orqali yuboriladi."""
    maybe_capture_owner(message.from_user)
    with db_lock:
        cur.execute("SELECT id, riddle, answer, reward, chain_stage, chain_id, territory_reward FROM arg_puzzles "
                    "WHERE active=1 ORDER BY id DESC LIMIT 1")
        row = cur.fetchone()
    if not row:
        bot.send_message(message.chat.id, "🧩 Hozircha faol sirli topshiriq yo'q.")
        return
    pid, riddle, answer, reward, stage, chain_id, territory_reward = row
    parts = (message.text or "").split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id, f"🧩 ({stage}/3-bosqich) {esc(riddle)}\n\n✏️ Javob: <code>/jumboq javobingiz</code>")
        return
    guess = _v10_normalize_answer(parts[1])
    if guess != answer:
        bot.send_message(message.chat.id, "❌ Noto'g'ri javob, qayta urinib ko'ring.")
        return
    uid = message.from_user.id
    name = message.from_user.first_name or "O'yinchi"
    with db_lock:
        cur.execute("SELECT solved_by FROM arg_puzzles WHERE id=?", (pid,))
        check = cur.fetchone()
        if check and check[0]:
            bot.send_message(message.chat.id, "✅ Bu bosqich allaqachon boshqa kishi tomonidan yechilgan.")
            return
        cur.execute("UPDATE arg_puzzles SET active=0, solved_by=?, solved_name=?, solved_at=? WHERE id=?",
                    (uid, name, time.time(), pid))
        conn.commit()
    add_balance(uid, dollar=reward)

    if stage < 3:
        with db_lock:
            cur.execute("SELECT id, riddle FROM arg_puzzles WHERE chain_id=? AND chain_stage=?", (chain_id, stage + 1))
            next_row = cur.fetchone()
        if next_row:
            next_id, next_riddle = next_row
            with db_lock:
                cur.execute("UPDATE arg_puzzles SET active=1 WHERE id=?", (next_id,))
                conn.commit()
            try:
                bot.send_message(uid, f"🎉 To'g'ri! +{reward}$\n\n🧩 <b>{stage + 1}-bosqich (faqat siz uchun):</b>\n"
                                       f"{esc(next_riddle)}\n\n✏️ <code>/jumboq javobingiz</code> — istalgan guruhda yozing.")
            except Exception:
                bot.send_message(message.chat.id, f"🎉 <b>{esc(name)}</b> {stage}-bosqichni yechdi! "
                                                   f"Keyingi bosqich uchun botga shaxsan /start yozing.")
                return
        bot.send_message(message.chat.id, f"🎉 <b>{esc(name)}</b> {stage}-bosqichni yechdi va +{reward}$ yutdi! "
                                           f"Keyingi bosqich unga DM orqali yuborildi 🤫")
        return

    # 3-bosqich (yakuniy) — butun jamoaga e'lon + klanga bepul hudud
    win_text = f"🎉 <b>{esc(name)}</b> SIRLI ZANJIRNI TO'LIQ YECHDI va +{reward}$ yutib oldi!"
    member_clan_owner = find_member_clan(uid)  # o'zi lider bo'lmasa ham, a'zosi bo'lgan klanini topadi
    clan = get_clan(member_clan_owner) if member_clan_owner else None
    if clan and territory_reward:
        tname = v10_capture_territory(clan["owner_id"], None)
        if tname:
            win_text += f"\n🗺 Klani <b>{esc(clan['name'])}</b> bepul, jangsiz <b>{esc(tname)}</b> hududini oldi!"
    for chat_id, _t in list_known_groups():
        try:
            bot.send_message(chat_id, win_text)
        except Exception:
            pass
    try:
        v11_generate_rich_legend(message.chat.id, None, "puzzle",
                                  [name], name, shadow_name=None, lucky_name=None)
    except Exception:
        pass


# ================================================================================
#  🔁 FON SIKLI — v10'dagi start_v10_loop() ga qo'shimcha vazifalar
# ================================================================================
def _v11_daily_loop():
    last_month_check = 0
    while True:
        try:
            time.sleep(1800)  # 30 daqiqada bir tekshiradi
            v11_mark_fortifications()
            _v11_event_timeout_sweeper()
            now = time.time()
            if now - last_month_check > 6 * 3600:  # kuniga necha marta emas, 6 soatda bir urinadi
                last_month_check = now
                # faqat oyning 1-kuni, kunning ertalabki soatida ishga tushadi
                lt = time.localtime(now)
                if lt.tm_mday == 1 and lt.tm_hour < 6:
                    v11_pick_legend_of_month()
        except Exception as e:
            _logger.warning("_v11_daily_loop xatolik: %s", e)


def start_v11_loop():
    t = threading.Thread(target=_v11_daily_loop, daemon=True)
    t.start()


