if __name__ == "__main__":
    print("Hunter Mafia bot v5 (telebot, do'kon + Stars + promo + tarqatish + qora bozor + klan jangi) ishga tushmoqda...")
    start_keepalive_server()  # 🌐 Render "xizmat tirik" deb bilishi uchun — ENG BIRINCHI ishga tushiriladi
    start_self_ping_loop()    # 🌐 har 10 daqiqada o'ziga so'rov — Render uxlab qolmasin deb
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users")
        _existing_users = cur.fetchone()[0]
    _logger.info(f"📂 Baza fayli: {DB_PATH}")
    _logger.info(f"👥 Bazadagi mavjud foydalanuvchilar soni: {_existing_users} ta")
    if _existing_users == 0 and _users_table_existed is False:
        _logger.warning("⚠️ Bu — 'users' jadvali birinchi marta yaratilyapti (yangi/bo'sh baza). Agar avval "
                         "foydalanuvchilar bo'lgan bo'lsa, bot boshqa papkadan yoki boshqa hunter_mafia.db "
                         "fayli bilan ishga tushirilayotgan bo'lishi mumkin — DB_PATH qatorini tekshiring.")
    # 🔒 BITTA NUSXA QULFI (single-instance lock): agar shu skript allaqachon shu
    # papkada ishga tushirilgan bo'lsa (masalan avvalgi jarayon to'liq o'chmagan,
    # yoki kimdir uni ikkinchi marta ishga tushirib yuborgan bo'lsa), bu yerda
    # DARHOL to'xtaydi va aniq xabar beradi — Telegram tomonidan qaytariladigan
    # tushunarsiz "409 Conflict" xatoligi o'rniga.
    _LOCK_PATH = "/tmp/hunter_mafia_bot.lock"
    try:
        import fcntl
        _lock_fh = open(_LOCK_PATH, "w")
        fcntl.flock(_lock_fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
        _lock_fh.write(str(os.getpid()))
        _lock_fh.flush()
    except BlockingIOError:
        print(
            "❌ Bot allaqachon ishga tushirilgan (boshqa jarayon shu bot tokeni bilan "
            "polling qilyapti)! Avval eski jarayonni to'xtating (masalan: "
            "`pkill -f hunter_mafia` yoki serverdagi eski deploy/screen/pm2 sessiyasini "
            "yopib qo'ying), keyin qayta ishga tushiring. Bot ishga tushmaydi."
        )
        sys.exit(1)
    except Exception as _lock_err:
        # fcntl mavjud bo'lmagan tizimlarda (masalan Windows) qulf o'tkazib yuboriladi —
        # bu holatda faqat webhook/eski-session tekshiruvi ishlaydi.
        _logger.warning("Instance-lock o'rnatilmadi (muhim emas): %s", _lock_err)

    # 🧹 Eski WEBHOOK (agar avval webhook rejimida ishlatilgan bo'lsa) yoki Telegram
    # tomonida "osilib qolgan" eski ulanishni tozalab, keyin polling'ni boshlaymiz —
    # bu ham 409 Conflict xatoligining keng tarqalgan sababi.
    try:
        bot.remove_webhook()
        time.sleep(1)
    except Exception as _wh_err:
        _logger.warning("Webhook tozalashda xatolik (muhim emas): %s", _wh_err)

    _state_restored = False
    _consecutive_conflicts = 0
    while True:
        try:
            BOT_USERNAME = bot.get_me().username
            _logger.info("Bot ishga tushdi: @%s", BOT_USERNAME)
            if not _state_restored:
                # 🔄 oldingi ishga tushishda (xatolik/deploy/`/tiklash`) saqlangan aktiv
                # o'yinlar bo'lsa, shu yerda tiklanadi — faqat 1 marta, tarmoq uzilib
                # qayta ulanganda emas (chunki fayl birinchi muvaffaqiyatli tiklashda o'chiriladi).
                load_games_state()
                _state_restored = True
                _check_clan_inactivity()  # 🏛 klan faolsizlik tekshiruvini fon rejimida ishga tushiramiz
                set_bot_commands_for_all_scopes()  # 📜 3 xil buyruqlar menyusini (guruh/shaxsiy/owner) o'rnatish
                start_auto_backup_loop()  # 💾 #6: har 24 soatda avtomatik zaxira nusxa
                start_freeze_watchdog()  # 🩺 bot muzlab qolsa — o'zini avtomatik qayta ishga tushiradi
                start_daily_menu_broadcast_loop()  # 🕖 har kuni soat 07:00'da barchaga bosh menyu
                start_weekly_report_loop()  # 📅 v10: har dushanba 09:00'da shaxsiy haftalik hisobot
                start_hc_market_loop()  # 🪙📈 Hunter Coin jonli kursini har HC_MARKET_UPDATE_MINUTES'da tebratib turadi
                start_v10_loop()  # 🎲 Hunter World: tasodifiy voqealar sikli (hudud/afsona/taqdir/karta/ARG)
                start_v11_loop()  # 🎲 Hunter World chuqurlashtirish: mustahkamlanish, oy afsonasi, muddati o'tgan voqealar
                # 🎴 Mini App endi pastki chap "menyu" tugmasida EMAS — faqat /profil
                # (kabinet) xabari ostidagi alohida tugma orqali ochiladi (foydalanuvchi so'rovi).
                try:
                    bot.set_chat_menu_button(menu_button=types.MenuButtonDefault())
                except Exception:
                    pass
            bot.infinity_polling(skip_pending=True, timeout=30, long_polling_timeout=30)
            _consecutive_conflicts = 0
        except telebot.apihelper.ApiTelegramException as e:
            if getattr(e, "error_code", None) == 409 or "409" in str(e) or "Conflict" in str(e):
                # 🚨 409 = boshqa bir nusxa HALI HAM shu tokendan foydalanib polling
                # qilyapti. Tez-tez qayta urinish faqat vaziyatni yomonlashtiradi —
                # shuning uchun har safar sal uzoqroq kutamiz (progressiv orqaga
                # chekinish), bosh ko'rsatiladigan xatolik xabarlari sonini kamaytiradi.
                _consecutive_conflicts += 1
                wait_s = min(60, 10 * _consecutive_conflicts)
                _logger.warning(
                    "⚠️ 409 Conflict: shu bot tokeni bilan BOSHQA bir nusxa polling "
                    "qilyapti (ehtimol eski jarayon o'chirilmagan). %s soniya kutib, "
                    "qayta urinilmoqda...", wait_s,
                )
                time.sleep(wait_s)
            else:
                _logger.exception("Telegram API xatoligi, 5 soniyadan keyin qayta urinilmoqda: %s", e)
                time.sleep(5)
        except Exception as e:
            # Tarmoq uzilishi yoki Telegram API vaqtinchalik ishlamay qolishi kabi hollarda
            # bot butunlay o'chib qolmasin — 5 soniya kutib qayta ulanadi.
            _logger.exception("Polling to'xtadi, 5 soniyadan keyin qayta urinilmoqda: %s", e)
            time.sleep(5)
